(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.3"]={"from":72,"a":[["\u0003אלא\u0004 יש לומר: האיסור על שלקות גוים הוא \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וקרא\u0004 \u0005[והמקרא]\u0006 הוא \u0003אסמכתא בעלמא\u0004 \u0005[בלבד].\u0006","ועוד בדיני בישולי גוים, \u0003אמר רב שמואל בר רב יצחק אמר רב: כל\u0004 דבר \u0003הנאכל כמות שהוא חי\u0004 — \u0003אין בו משום בישולי גוים,\u0004 שהבישול לא הפך אותו לאוכל שעשאו הגוי, שהרי אפשר לאכול אותו גם ללא בישול. ומעירים, \u0003בסורא מתנו הכי\u0004 \u0005[היו שונים\u0006 מסורת זו \u0005כך].\u0006 ואילו \u0003בפומבדיתא מתנו הכי\u0004 \u0005[היו שונים כך],\u0006 \u0003אמר רב שמואל בר רב יצחק אמר רב: כל שאינו נאכל על שולחן מלכים ללפת בו את הפת\u0004 — \u0003אין בו משום בישולי גוים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהן]\u0006 בין שתי מסורות אלה הלכה למעשה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהן]\u0006 לגבי \u0003דגים קטנים וארדי\u0004 (פטריות), \u0003ודייסא,\u0004 שאין עולים על שולחן מלכים, אף על פי שאי אפשר לאכול אותם חיים.","\u0003אמר רב אסי אמר רב: דגים קטנים מלוחים\u0004 — \u0003אין בהן משום בישולי גוים,\u0004 שהרי הם נאכלים כמות שהם. \u0003אמר רב יוסף: אם צלאן גוי\u0004 — \u0003סומך ישראל עליהם משום עירובי תבשילין. ו\u0004מכל מקום \u0003אי עבדינהו\u0004 \u0005[אם עשה אותם]\u0006 \u0003גוי כסא דהרסנא\u0004 (דגים המטוגנים בשמן וקמח) — \u0003אסור.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 ואומרים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הרסנא\u0004 (הדגים המלוחים) הם ה\u0003עיקר,\u0004 והם נאכלים כמות שהם, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003קימחא\u0004 \u0005[הקמח]\u0006 הוא \u0003עיקר,\u0004 ומשום הקמח אסור לאכול.","\u0003אמר רב ברונא אמר רב: גוי שהצית את האור\u0004 (אש) \u0003באגם\u0004 (באחו) — \u0003כל החגבים\u0004 המתים \u0003שבאגם אסורין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דלא ידע הי\u0004 \u0005[שאינו יודע איזה\u0006 מהם\u0005]\u0006 \u0003טהור והי\u0004 \u0005[ואיזה]\u0006 \u0003טמא,\u0004 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא] שהצית את האור \u0003גוי? אפילו\u0004 הצית \u0003ישראל נמי\u0004 \u0005[גם כן]!\u0006 \u0003אלא\u0004 תאמר שהוא \u0003משום בישולי גוים\u0004 —","\u0003כי האי גוונא מי אסיר\u0004 \u0005[כגון זה האם\u0006 הוא \u0005אסור]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 רב חנן בר אמי אמר ר' פדת אמר ר' יוחנן: האי גוי דחריך רישא \u0005[גוי זה שחורך ראש\u0006 של בהמה\u0005]\u0006 כדי להסיר את השיער — \u0003שרי למיכל מיניה\u0004 \u0005[מותר לאכול ממנו]\u0006 \u0003אפילו מריש אוניה\u0004 \u0005[מראש אזנו]\u0006 שהוא רך ועל ידי חריכה זו נתבשל, \u0003אלמא לעבורי שער קמיכוין\u0004 \u0005[מכאן\u0006 שאנו אומרים ש\u0005להעביר\u0006 את \u0005השיער\u0006 מן הראש \u0005הוא מתכוון]\u0006 ולא לבשלו, ומשום כך הוא מותר, \u0003הכא נמי לגלויי אגמא קא מיכוין\u0004 \u0005[כאן גם כן לחשוף\u0006 את קרקע \u0005האגם הוא מתכוון]\u0006 ואינו מתכוון לבישול!","ומשיבים: \u0003לעולם\u0004 תפרש שהאיסור הוא משום \u0003דלא ידע הי\u0004 \u0005[שאינו יודע איזה]\u0006 מהחגבים \u0003טהור והי\u0004 \u0005[ואיזה]\u0006 \u0003טמא, ומעשה שהיה\u0004 שהורו בו הלכה זו, \u0003בגוי היה.\u0004","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: האי גוי דחריך רישא\u0004 \u0005[גוי זה שחורך ראש]\u0006 — \u0003שרי למיכל מיניה אפילו מריש אוניה\u0004 \u0005[מותר לאכול ממנו אפילו מראש אזנו].\u0006 \u0003אמר רבינא: הלכך\u0004 \u0005[משום כך]\u0006 על פי הלכה זו, \u0003האי גוי דשדא סיכתא לאתונא\u0004 \u0005[גוי זה שהניח יתד בכבשן]\u0006 כדי לייבשה ובכך לחזקה, \u0003וקבר\u0004 (טמן) \u0003בה ישראל קרא מעיקרא\u0004 \u0005[דלעת\u0006 חיה \u0005קודם לכן]\u0006 לפני שהגוי הצית את האש בתנור — \u0003שפיר דמי\u0004 \u0005[כשר הדבר].\u0006 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שכך! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לבשולי מנא קא מיכוין\u0004 \u0005[שלבשל\u0006 את \u0005הכלי\u0006 היתד \u0005התכוון]\u0006 והרי התכוון לשם בישול, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003לשרורי מנא קא מיכוין\u0004 \u0005[\u0006שרק \u0005לחזק\u0006 את \u0005הכלי,\u0006 את היתד, \u0005הוא מתכוון].\u0006","\u0003אמר רב יהודה אמר שמואל: הניח ישראל בשר על גבי גחלים, ובא גוי והפך בו\u0004 — \u0003מותר.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דאי לא הפך ביה הוה בשיל\u0004 \u0005[אם תאמר ש\u0006גם \u0005אם לא היה הופך אותו היה מתבשל],\u0006 \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שהגוי לא עשה דבר! \u0003אלא לאו דאי לא הפך לא הוה בשיל\u0004 \u0005[האם לא\u0006 מדובר \u0005שאם לא היה הופך לא היה מתבשל],\u0006 ואם כן יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותר?\u0004 הלוא \u0003בישולי של גוים נינהו\u0004 \u0005[הם]!\u0006","ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה כזה, \u0003דאי לא הפך הוה בשיל בתרתי שעי\u0004 \u0005[שאם לא היה הופך היה מתבשל בשתי שעות],\u0006 \u0003והשתא קא בשיל בחדא שעתא\u0004 \u0005[ועכשיו הוא מתבשל בשעה אחת],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003קרובי בישולא מילתא היא\u0004 \u0005[קירוב,\u0006 החשת \u0005הבישול דבר היא]\u0006 לענין זה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין זה כן.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אסי אמר ר' יוחנן: כל שהוא\u0004 מבושל כבר \u0003כמאכל בן דרוסאי\u0004 (שודד ידוע, שהיה רגיל לאכול דברים מבושלים למחצה) — \u0003אין בו משום בישולי גוים,\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי אם]\u0006 \u0003אינו כמאכל בן דרוסאי\u0004 ולא התבשל עד כדי כך — \u0003יש בו משום בשולי גוים\u0004 הואיל ונתבשל יותר!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אין מדובר בהמשך הבישול, אלא \u0003כגון דאותביה בסילתא\u0004 \u0005[ששם אותו\u0006 היהודי \u0005בסל],\u0006 שלא היה יכול להתבשל, \u0003ושקליה גוי ואותביה בתנורא\u0004 \u0005[ולקחו הגוי והושיבו,\u0006 הניחו \u0005בתנור],\u0006 אבל לא במקרה שהוא כבר מונח בתנור בוער.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מניח ישראל בשר על גבי גחלים, ובא גוי ומהפך בו עד שיבא ישראל מבית הכנסת או מבית המדרש, ואינו חושש\u0004 לאיסור שבזה. וכן \u0003שופתת אשה קדירה על גבי כירה, ובאת גויה\u0004"],["\u0003ומגיסה\u0004 (בוחשת) \u0003עד שתבא\u0004 האשה היהודיה \u0003מבית המרחץ או מבית הכנסת, ואינה חוששת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 במקרה ההפוך, ש\u0003הניח גוי\u0004 את הבשר על גבי הגחלים \u0003והפך\u0004 בו \u0003ישראל, מהו\u0004 הדין? \u0003אמר רב נחמן בר יצחק: קל וחומר\u0004 הוא שמותר, אם במקרה ש\u0003גמרו\u0004 של התבשיל \u0003ביד גוי מותר,\u0004 אם \u0003גמרו ביד ישראל לא כל שכן?\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב אחא בר בר חנה אמר ר' יוחנן: בין שהניח גוי והפך ישראל, בין שהניח ישראל והפך גוי\u0004 — \u0003מותר, ואינו אסור עד שתהא תחלתו וגמרו ביד גוי.\u0004","\u0003אמר רבינא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003הא ריפתא דשגר\u0004 \u0005[לחם זה שהסיק]\u0006 \u0003גוי\u0004 את התנור \u0003ואפה\u0004 אותו \u0003ישראל, אי נמי שגר\u0004 \u0005[או גם כן\u0006 ש\u0005הסיק]\u0006 \u0003ישראל ואפה גוי, אי נמי\u0004 \u0005[או גם כן]\u0006 אפילו \u0003שגר\u0004 \u0005[הסיק]\u0006 \u0003גוי ואפה גוי, ואתא\u0004 \u0005[ובא]\u0006 \u0003ישראל\u0004 בין ההסקה והאפיה \u0003וחתה בה חתויי\u0004 \u0005[חיתוי]\u0006 באש מעט — \u0003שפיר דמי\u0004 \u0005[מותר הדבר],\u0006 ואין בו משום פת גוים.","\u0003דג מליח\u0004 שמלחו גוי, \u0003חזקיה שרי\u0004 \u0005[התיר]\u0006 לאכול, \u0003ור' יוחנן אסר. ביצה צלויה\u0004 שצלאה גוי — \u0003בר קפרא שרי\u0004 \u0005[התיר],\u0006 \u0003ור' יוחנן אסר. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר: אחד דג מליח ואחד ביצה צלויה\u0004 — באלה \u0003חזקיה ובר קפרא שרו\u0004 \u0005[התירו],\u0006 \u0003ור' יוחנן אסר.\u0004","מסופר, \u0003ר' חייא פרוואה\u0004 (מהמקום פרווא) \u0003איקלע לבי ריש גלותא\u0004 \u0005[הזדמן לבית ראש הגולה],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ביצה צלויה\u0004 שצלאה גוי \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003חזקיה ובר קפרא שרו\u0004 \u0005[התירו],\u0006 \u0003ור' יוחנן אסר,\u0004 \u0003ואין דבריו של אחד\u0004 נחשבים \u0003במקום\u0004 (כנגד) דברי \u0003שנים,\u0004 ואם כן מותר. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב זביד: לא תציתו ליה\u0004 \u0005[אל תשמעו לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אביי: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003ר' יוחנן.\u0004 כעסו עליו עבדי ראש הגולה \u0003אשקיוהו נגוטא דחלא ונח נפשיה\u0004 \u0005[השקו אותו כוס של חומץ\u0006 חריף, \u0005ונחה נפשו,\u0006 מת\u0005]\u0006 מחמת זה.","בענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקפריסין, והקפלוטות\u0004 (כרישין), \u0003והמטליא\u0004 (שיבואר עניינה להלן), \u0003והחמין, והקליות\u0004 (חיטים קלויות) \u0003שלהן\u0004 (של גוים) — \u0003מותרין, ביצה צלויה\u0004 — \u0003אסורה. שמן\u0004 של גוים — \u0003ר' יהודה הנשיא ובית דינו נמנו\u0004 (הצביעו) \u0003עליו והתירוהו.\u0004","בפירושה של \"מטליא\" \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היא המטליא היא פשליא היא שיעתא.\u0004 כל המונחים האלה לא היו ידועים, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003שיעתא? אמר רבה בר בר חנה אמר ר' יוחנן: הא ארבעין שנין דנפיק האי עובדא\u0004 \u0005[זה ארבעים שנה שיצא מעשה זה]\u0006 \u0003ממצרים, ורבה בר בר חנה דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר: הא שתין שנין דנפיק האי עובדא\u0004 \u0005[זה ששים שנה שיצא מעשה זה]\u0006 \u0003ממצרים,\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 בענין, אלא \u0003מר בשניה ומר בשניה\u0004 \u0005[חכם זה בשנותיו וחכם זה בשנותיו],\u0006 שרבה בר בר חנה אמר את הדברים עשרים שנה לאחר ר' יוחנן. ומה עניינו?","\u0003מייתו ביזרא דכרפסא וביזרא דכיתנא וביזרא דשבלילתא\u0004 \u0005[מביאים זרע כרפס וזרע פשתן וזרע תלתן],\u0006 \u0003ותרו להו בהדי הדדי בפשורי\u0004 \u0005[ושורים אותם ביחד ב\u0006מים \u0005פושרים],\u0006 \u0003ושבקו ליה עד דמקבל\u0004 \u0005[ומניחים אותם עד שמתחילים לנבוט],\u0006 \u0003ומייתי חצבי חדתי ומלו להו מיא\u0004 \u0005[ומביאים כדים חדשים וממלאים אותם מים],\u0006 \u0003ותרו בהו גרגישתא ומדבקין ביה\u0004 \u0005[ושורים בהם אדמה ומדביקים בה]\u0006 את הזרעים הללו, \u0003ועיילין לבי בני\u0004 \u0005[והולכים לבית המרחץ\u0006 לרחוץ\u0005],\u0006 \u0003אדנפקו מלבלבי, ואכלי מינייהו\u0004 \u0005[עד ש\u0006הם \u0005יוצאים\u0006 מהמרחץ, הצמחים הללו \u0005מלבלבים, ו\u0006הם \u0005אוכלים מהם],\u0006 \u0003וקיירי מבינתא דרישייהו\u0004 \u0005[ו\u0006הם \u0005מתקררים\u0006 על ידי כך \u0005משערות ראשם]\u0006 \u0003עד טופרא דכרעייהו\u0004 \u0005[צפרני רגליהם].\u0006 \u0003אמר רב אשי, אמר לי ר' חנינא: מילין\u0004 \u0005[דיבורים]\u0006 הם אלה, גוזמה היא, שכן אין הצמחים צומחים כל כך מהר. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003במילין\u0004 \u0005[בדיבורים],\u0006 אם עושים דבר כזה הרי זה נעשה בכשפים. ולענייננו, למדנו מכאן כי שריית אותם זרעים בפושרים — אין בה משום בישולי גוים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכוספן\u0004 (גפת של תמרים ושאר פירות) \u0003של גוים\u0004 שפעמים היו שורים אותם במים חמים כדי לעשות מהם שיכר וכיוצא בזה, \u0003שהוחמו חמין\u0004 לתקנם, \u0003ביורה גדולה\u0004 — \u0003אסור, ביורה קטנה\u0004 — \u0003מותר.\u0004 ושואלים: \u0003ואיזו היא\u0004 מיהי הנחשבת \u0003יורה קטנה\u0004 לענין זה? \u0003אמר ר' ינאי: כל שאין צפור דרור יכול ליכנס בתוכה,\u0004 ולכן אין לחשוש שבישלו קודם לכן ביורה זו דבר איסור.","ושואלים: \u0003ודלמא אדמויי אדמוה ועיילוה\u0004 \u0005[ושמא חתכו אותו לחתיכות והכניסו אותו]!\u0006 \u0003אלא\u0004 צריך לומר שהיורה קטנה עד \u0003כל שאין ראש צפור דרור יכול ליכנס בתוכה.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אחת יורה גדולה ואחת יורה קטנה\u0004 — \u0003מותר!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא כמאן דאמר\u0004 \u0005[זו,\u0006 האוסרת יורה גדולה, \u0005כ\u0006שיטת \u0005מי שאומר]:\u0006 \u0003נותן טעם לפגם אסור,\u0004 ויש לחשוש איפוא לטעמו של דבר איסור שהיה ביורה, \u0003הא כמאן דאמר\u0004 \u0005[זו,\u0006 שמתירה בכל יורה, \u0005כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003נותן טעם לפגם מותר.\u0004","\u0003אמר רב ששת: האי מישחא שליקא דארמאי\u0004 \u0005[שמן שלוק,\u0006 מבושל \u0005של גוים]\u0006 — \u0003אסור. אמר רב ספרא: למאי ניחוש לה\u0004 \u0005[למה נחשוש בזה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום איערובי\u0004 \u0005[תערובת]\u0006 של דברים אחרים אסורים — הרי הוא \u0003מיסרא סרי\u0004 \u0005[מסריח]\u0006 משום כך, ובוודאי לא עשו כן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום בישולי גוים\u0004 — הרי שמן \u0003נאכל הוא כמו שהוא חי, אי\u0004 \u0005[אם]\u0006 \u0003משום גיעולי גוים\u0004 שהסיר שנתבשל בו פלט (געל) לתוכו איסור שנתבשל בו קודם לכן — הרי \u0003נותן טעם לפגם הוא ומותר!\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מר' אסי: הני אהיני שליקי דארמאי מאי\u0004 \u0005[תמרים שלוקים של גוים מה\u0006 דינם\u0005]?\u0006 ומפרטים: אם הם היו \u0003חוליי\u0004 \u0005[\u0006תמרים \u0005מתוקים]\u0006 מתחילתם — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שב\u0003ודאי שרו\u0004 \u0005[\u0006הם \u0005מותרים],\u0006 שהרי הם נאכלים כמו שהם חיים, \u0003מרירי\u0004 \u0005[\u0006תמרים \u0005מרים]\u0006 שצריכים לבישול זה כדי למתקם — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שב\u0003ודאי אסירי\u0004 \u0005[\u0006הם \u0005אסורים].\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר יסתפק]\u0006 \u0003לך\u0004 הרי זה ב\u0003מציעאי\u0004 \u0005[אמצעיים]\u0006 שאינם מתוקים דיים ואינם מרים ביותר, \u0003מאי\u0004 \u0005[מה\u0006 דינם\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי תיבעי להו\u0004 \u0005[מה תישאל לכם]\u0006 בענין זה? ש\u0003רבי\u0004 (הרב שלי) \u0003אסר\u0004 דבר זה, \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 רבו של ר' אסי? \u0003לוי.\u0004","\u0003שתיתאה\u0004 מאכל שעושים מקמח של קליות (זרעים קלויים באש) — \u0003רב שרי\u0004 \u0005[התיר],\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל ולוי אסרי\u0004 \u0005[אוסרים].\u0006 ומעירים: \u0003בחיטי ושערי כולי עלמא לא פליגי דשרי\u0004 \u0005[ב\u0006מאכל הנעשה מקליות של \u0005חיטים ושעורים הכל אינם חולקים שמותר],\u0006 ומצד אחר, \u0003בטלפחי דחלא כולי עלמא לא פליגי דאסיר\u0004 \u0005[בעדשים\u0006 קלויות ששמים בהם \u0005חומץ הכל אינם חולקים שאסור]\u0006 בגלל החומץ של גוים, \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חולקים]\u0006 — הרי זה \u0003בטלפחי דמיא\u0004 \u0005[בעדשים של מים]\u0006 שמכניסים רק מים בתוכם, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 אביו של שמואל ולוי, \u0005סבור]:\u0006 \u0003גזרינן הא אטו הא\u0004 \u0005[גוזרים אנו זה משום זה],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003בטלפחי דמיא כולי עלמא לא פליגי דאסיר\u0004 \u0005[בעדשים של מים הכל אינם חולקים שאסור],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חולקים]\u0006 — הרי זה \u0003בחיטי ושערי\u0004 \u0005[בחיטים ושעורים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003גזרינן הא אטו הא\u0004 \u0005[גוזרים אנו זה משום זה],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","אגב זה מביאים מה ש\u0003אמר רב: תרי מיני שתיתאה\u0004 \u0005[שני מיני\u0006 מאכלי \u0005קליות]\u0006 \u0003שדר\u0004 \u0005[שלח]\u0006 \u0003ברזילי הגלעדי לדוד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"משכב וספות וכלי יוצר חטים ושערים וקמח וקלי ופול ועדשים וקלי\"\u0004 (שמואל ב יז, כח), שנכפל פעמיים \"קלי\" בכתוב, פעם לאחר חיטים ושעורים, ופעם לאחר פול ועדשים, לומר ששני מיני קלי היו. ובמסקנת ההלכה בענין זה מעירים: \u0003והשתא הוא דקא מפקי צני צני\u0004 \u0005[ועכשיו\u0006 בימינו \u0005שמוציאים סלים סלים]\u0006 של שתיתא של גוים, \u0003לשוקי נהרדעא ולית דחייש להא דאבוה\u0004 \u0005[ואין חושש לזו של אביו]\u0006 של \u0003שמואל ולוי\u0004 שאסרוה.","שנינו במשנה: \u0003וכבשין שדרכן לתת בתוכן יין\u0004 מותרים בהנאה ואסורים באכילה. \u0003אמר חזקיה: לא שנו אלא שדרכן\u0004 לתת בתוכן ביין, אבל אינו יודע אם אכן הכניסו בהם יין, \u0003אבל בידוע\u0004 שיש שם יין — \u0003אסור אפילו בהנאה\u0004 משום היין. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 הדבר \u0003ממורייס\u0004 (מאכל העשוי מציר של דגים) שנותנים בו יין, \u0003דשרו רבנן\u0004 \u0005[שהתירו חכמים]\u0006 \u0003בהנאה?\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 נותנים את היין רק \u0003לעבורי זוהמא\u0004 \u0005[להעביר\u0006 את \u0005הזוהמה]\u0006 ואין הוא בא לשבח את טעמו של המורייס, \u0003הכא\u0004 \u0005[כאן],\u0006 בכבשים, נותנים אותו \u0003למתוקי טעמא\u0004 \u0005[למתק\u0006 את \u0005הטעם]\u0006 והוא נחשב כחלק ממשי של המאכל, ורוצים אנו אותו.","\u0003ור' יוחנן אמר: אפילו בידוע\u0004 שהכניסו בו יין \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004 ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 הדבר \u0003ממורייס ל\u0004דעת \u0003ר' מאיר דאסיר\u0004 \u0005[שאסור]\u0006 \u0003בהנאה?\u0004"],["ומשיבים: \u0003התם ידיע\u0004 \u0005[שם,\u0006 במורייס, \u0005ידוע]\u0006 \u0003ממשו\u0004 הממשות שלו, שהיין הוא חלק מן המורייס שטובלים בו את הפת, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא ידיע\u0004 \u0005[ידוע]\u0006 \u0003ממשן,\u0004 שאינו ניכר בכבשים.","שנינו שעוד דברים שאסורים באכילה והם: \u0003טרית טרופה, וציר שאין בה דגה\u0004 וחילק \u0003וכו'.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 פירוש \u0003חילק? אמר רב נחמן בר אבא אמר רב: זו סולתנית\u0004 (מין דגים קטנים) שבקטנותם אין להם עדיין קשקשים, \u0003ומפני מה אסורה? מפני שערבונה\u0004 כלומר, דגים טמאים מעורבים בה \u0003עולה עמה\u0004 ולא ניתן להבחין ביניהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 דג ש\u0003אין לו עכשיו\u0004 קשקשים, שהוא מסימני טהרה בדג, \u0003ועתיד לגדל\u0004 קשקשים \u0003לאחר זמן, כגון הסולתנית והעפיץ\u0004 — \u0003הרי זה מותר.\u0004 וכן דג ש\u0003יש לו עכשיו\u0004 קשקשים \u0003ועתיד להשיר\u0004 אותם \u0003בשעה שעולה מן הים, כגון אקונס ואפונס, כטספטייס ואכספטייס ואוטנס\u0004 — \u0003מותר,\u0004 שמה שאסור באכילה הוא דווקא דג שאין לו סנפירים וקשקשת כלל בכל שלב שהוא.","ובענין זה של כשרות הדגים מסופר, \u0003אכריז\u0004 \u0005[הכריז]\u0006 \u0003ר' אבהו בקיסרי: קירבי דגים ועוברן\u0004 (ביצי דגים) \u0003ניקחין\u0004 \u0003מכל אדם,\u0004 ובכלל זה גוים, ואין בודקים אותם, ומדוע? \u0003חזקתן אינן באים אלא מפלוסא ואספמיא,\u0004 ושם אין הדגים הטמאים מצויים. ומעירים: ודבר זה הוא \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר אביי: האי צחנתא דבב נהרא\u0004 \u0005[אותו מאכל\u0006 \u0005העשוי מדגים\u0006 קטנים \u0005של הנהר בב]\u0006 — \u0003שריא\u0004 [\u0005מותר],\u0006 שאין דג טמא מצוי שם.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דרדיפי מיא\u0004 \u0005[שהמים זורמים בו בכוח],\u0006 \u0003והאי\u0004 \u0005[ואותו]\u0006 \u0003דג טמא כיון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003חוט השדרה, בדוכתא דרדיפי מיא לא מצי קאי\u0004 \u0005[במקום שהמים זורמים\u0006 \u0005בכוח\u0006 \u0005אינו יכול לעמוד],\u0006 על כך יש להקשות: \u0003והא קא חזינן דקאי\u0004 \u0005[והרי אנו רואים ש\u0006דג טמא \u0005עומד,\u0006 מתקיים\u0005]\u0006 במקום כזה!","\u0003אלא\u0004 תאמר \u0003משום דמליחי מיא\u0004 \u0005[שהמים מלוחים]\u0006 בנהר זה, \u0003והאי\u0004 \u0005[ואותו]\u0006 \u0003דג טמא\u0004 \u0003כיון דלית ליה קלפי\u0004 \u0005[שאין לו קשקשים],\u0006 \u0003בדוכתא דמליחי מיא לא מצי קאי\u0004 \u0005[במקום שהמים מלוחים אינו יכול לעמוד],\u0006 גם על כך יש להקשות: \u0003והא קחזינן דקאי\u0004 \u0005[והרי אנו רואים ש\u0006הוא \u0005עומד,\u0006 מתקיים שם\u0005]!\u0006 \u0003אלא,\u0004 טעם הדבר הוא, \u0003משום\u0004 ש\u0003לא מרבה טינא\u0004 \u0005[מגדל הטיט]\u0006 בקרקעית נהר זה \u0003דג טמא.\u0004 \u0003אמר רבינא: האידנא דקא שפכי ביה\u0004 \u0005[עכשיו,\u0006 בימינו, \u0005שנשפכים לתוכו,\u0006 לנהר בב] \u0003נהר גוזא ונהר גמדא\u0004 — \u0003אסירי\u0004 \u0005[אסורים\u0006 הדגים\u0005],\u0006 שמא הם דגים טמאים שבאו לשם מאותם נהרות. ומביאים עדויות בענין כשרותם של דגים שונים.","\u0003אמר אביי: האי חמרא דימא\u0004 \u0005[זה\u0006 הקרוי \u0005חמור הים]\u0006 — \u0003שרי\u0004 [\u0005מותר],\u0006 \u0003תורא דימא\u0004 \u0005[זה\u0006 הקרוי \u0005שור הים]\u0006 — \u0003אסיר\u0004 [\u0005אסור],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 לזכור: \u0003טמא טהור, טהור טמא,\u0004 שהרי חמור שהוא טמא ביבשה טהור בים, והפכו של דבר בשור.","\u0003אמר רב אשי:\u0004 הדג הקרוי \u0003שפר נונא\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003קדש נונא\u0004 — \u0003אסיר\u0004 \u0005[אסור],\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003\"קדש לה' \"\u0004(שמות טז, כג), ש\"קדש\" אסור כדבר של קודש. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 הדג הקרוי \u0003קבר נונא\u0004 — הוא \u0003אסור, וסימניך\u0004 \u0005[וסימנך]:\u0006 \"קבר\" טמא כ\u0003קברי גוים.\u0004","מסופר, \u0003ר' עקיבא איקלע\u0004 \u0005[נזדמן]\u0006 \u0003ל\u0004מקום הקרוי \u0003גינזק, אייתו לקמיה ההוא נונא דהוה דמי\u0004 \u0005[הביאו לפניו דג שהיה דומה]\u0006 \u0003לחיפושא\u0004 שהוא דג טמא, \u0003חפייה בדיקולא\u0004 \u0005[כיסה\u0006 הניח \u0005אותו,\u0006 את הדג \u0005בסל]\u0006 ופירכס, \u0003חזא ביה קלפי ושרייה\u0004 \u0005[ראה בו\u0006 בדפני הסל \u0005קשקשים והתירו],\u0006 שקודם לא ראו את הקשקשים על עור הדג, מפני שהיו דקים ושקופים. מסופר, \u0003רב אשי איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום הקרוי \u0003טמדוריא, אייתו לקמיה ההוא נונא דהוה דמי לצלופחא\u0004 \u0005[הביאו לפניו דג אחד שהיה דומה לצלופח]\u0006 שהוא דג טמא, \u0003נקטיה להדי יומא\u0004 \u0005[לקח אותו אל מול\u0006 אור \u0005היום],\u0006 \u0003חזא דהוה ביה צימחי ושרייה\u0004 \u0005[ראה שהיו בו קשקשים דקים והתירו].\u0006","ועוד מסופר כי \u0003רב אשי איקלע לההוא אתרא\u0004 \u0005[הזדמן למקום אחד],\u0006 \u0003אייתו לקמיה נונא דהוי דמי\u0004 \u0005[הביאו לפניו דג שהיה דומה]\u0006 \u0003לשפרנונא\u0004 שגם הוא דג טמא, \u0003חפייה במשיכלי חיורי\u0004 \u0005[הכניס אותו בתוך כלי לבן],\u0006 \u0003חזא ביה קלפי ושרייה\u0004 \u0005[ראה בו\u0006 את \u0005הקשקשים,\u0006 שהיו שחורים, \u0005והתירו].\u0006 ועוד מסופר, \u0003רבה בר בר חנה איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לאקרא דאגמא, קריבו ליה צחנתא\u0004 \u0005[הביאו לו מאכל עשוי מדגים קטנים],\u0006 \u0003שמעיה לההוא גברא דהוה קרי ליה\u0004 \u0005[שמע לאדם אחד שהיה קורא לו]\u0006 \u0003באטי,\u0004","\u0003אמר: מדקא קרי ליה\u0004 \u0005[מכיון שהוא קורא לו]\u0006 \u0003באטי\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003דבר טמא אית ביה\u0004 \u0005[יש בו],\u0006 משום שבאטי הוא שם של דג טמא, \u0003לא אכל מיניה\u0004 \u0005[ממנו].\u0006 \u0003לצפרא\u0004 \u0005[בבוקר]\u0006 \u0003עיין בה\u0004 בדק מאכל זה, \u0003אשכח ביה\u0004 \u0005[מצא בו]\u0006 \u0003דבר טמא, קרי אנפשיה\u0004 \u0005[קרא על עצמו]\u0006 את הפסוק: \u0003\"לא יאנה לצדיק כל און\"\u0004 (משלי יב, כא).","שנינו במשנה: \u0003והקורט\u0004 (חתיכה) \u0003של חילתית\u0004 (צמח חריף) של גוים אסור באכילה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003משום דמפסקי ליה בסכינא\u0004 \u0005[שחותכים אותו בסכין]\u0006 ועל הסכין יש מן הסתם שמנונית של איסור הנבלעת בחלתית. ומוסיפים: \u0003אף על גב דאמר מר\u0004 \u0005[אף על פי שאמר החכם]:\u0006 שאם האיסור \u0003נותן טעם לפגם מותר,\u0004 במקרה זה \u0003אגב חורפיה דחילתיתא מחליא ליה שמנוניתא\u0004 \u0005[מתוך החריפות של החילתית, ממתיקה\u0006 \u0005אותה השמנונית\u0006 שבסכין\u0005],\u0006 \u0003והוה ליה\u0004 \u0005[והריהו]\u0006 \u0003כנותן טעם לשבח\u0004 בחלתית \u0003ואסור.\u0004","מסופר, \u0003עבדיה\u0004 \u0005[עבדו\u0006 הגוי\u0005]\u0006 של \u0003ר' לוי הוה קא מזבין חילתיתא\u0004 \u0005[היה מוכר חלתית]\u0006 והיו סומכים עליו כעבדו של ר' לוי, \u0003כי נח נפשיה\u0004 \u0005[כאשר נפטר]\u0006 \u0003ר' לוי אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מהו למיזבן מיניה\u0004 \u0005[לקנות ממנו]?\u0006 האם גם עכשיו מותר הדבר? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003עבדו של חבר\u0004 (המקפיד בעניינים של טהרה וכשרות המזון) \u0003הרי הוא\u0004 נאמן \u0003כחבר.\u0004","כיוצא בו מסופר, \u0003רב הונא בר מניומי זבן תכילתא מאנשי דביתיה\u0004 \u0005[היה קונה תכלת\u0006 לציצית \u0005מאנשי ביתו,\u0006 אשתו\u0005]\u0006 של \u0003רב עמרם חסידא\u0004 \u0005[החסיד],\u0006 שתכלת אין קונים אלא ממי שאפשר לסמוך עליו לגמרי, מפני שקל לזייפה בצבעים דומים וזולים יותר. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף\u0004 לשאול האם אפשר לסמוך על האשה, \u0003לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 של רב יוסף תשובה\u0005],\u0006","\u0003פגע ביה\u0004 \u0005[פגש בו]\u0006 \u0003חנן חייטא\u0004 \u0005[החייט]\u0006 את רב הונא בר מניומי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 כששמע את הסיפור: \u0003יוסף עניא מנא ליה\u0004 \u0005[יוסף העני,\u0006 המסכן, \u0005מנין לו]\u0006 לדעת תשובה לשאלה זו? \u0003בדידי הוה עובדא\u0004 \u0005[בי היה מעשה],\u0006 \u0003דזביני תכילתא מאנשי דביתיה\u0004 \u0005[שקניתי תכלת מאנשי ביתו,\u0006 מאשתו\u0005]\u0006 של \u0003רבנאה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' חייא בר אבא, ואתאי לקמיה\u0004 \u0005[ובאתי לפני]\u0006 \u0003רב מתנא\u0004 לשאול, \u0003לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005],\u0006 \u0003אתאי לקמיה\u0004 \u0005[באתי לפני]\u0006 \u0003רב יהודה מהגרוניא, אמר לי: נפלת ליד\u0004 (לידי), כלומר, בעל כרחך אתה נזקק לשמועתי, שאני יודע תשובה לשאלה זו, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אשת חבר הרי היא כחבר.\u0004","ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו את זה],\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אשת חבר הרי היא כחבר, עבדו של חבר הרי הוא כחבר,\u0004 ולכן \u0003חבר שמת\u0004 — \u0003אשתו ובניו ובני ביתו הרי הן בחזקתן\u0004 של כשרות כמו החבר בעצמו \u0003עד שיחשדו\u0004 כלומר, עד שיתגלה שאינם נאמנים. \u0003וכן חצר שמוכרין בה תכלת\u0004 בקביעות, \u0003הרי היא בחזקתן עד שתיפסל\u0004 שיתברר שיש רמאות שם.","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אשת עם הארץ שנשאת לחבר, וכן בתו של עם הארץ שנשאת לחבר, וכן עבדו של עם הארץ שנמכר לחבר\u0004 — \u0003כולן צריכין לקבל\u0004 על עצמם \u0003דברי חברות\u0004 בפני שלושה חברים, כדי שאפשר יהיה לסמוך עליהם כעל החברים. \u0003אבל אשת חבר שנשאת לעם הארץ, וכן בתו של חבר שנשאת לעם הארץ, וכן עבדו של חבר שנמכר לעם הארץ\u0004 — \u0003אינן צריכין לקבל דברי חברות לכתחלה,\u0004 משום שסומכים על מה שהיו נאמנים קודם לכן, אלו \u0003דברי ר' מאיר;\u0004","\u0003ר' יהודה אומר: אף הן צריכין לקבל דברי חברות לכתחלה. וכן היה ר' שמעון בן אלעזר אומר: מעשה באשה אחת שנשאת לחבר, והיתה קושרת לו תפילין על ידו,\u0004 לאחר מכן \u0003נשאת למוכס, והיתה קושרת לו קשרי מוכס על ידו.\u0004 משמע שהאישה הולכת אחר בעלה, ולכן גם אם היתה קודם אשת חבר — אין לסמוך על כך אחרי שנישאה לעם הארץ.","ובענין דברים שמפקידים בידי גוי, \u0003אמר רב:\u0004 הדברים שראשי התיבות שלהם: \u0003חבי\"ת\u0004 — \u0003אסור\u0004 לסמוך עליהם אם נחתמו \u0003בחותם אחד,\u0004 שמא החליפו או זייפו אותם. דברים שראשי התיבות שלהם: \u0003חמפ\"ג\u0004 — \u0003מותר בחותם אחד.\u0004 מהו חבי\"ת? \u0003חלב, בשר, יין, תכלת\u0004 —"],["\u0003אסורין בחותם אחד\u0004 שמא יזייפם. \u0003חילתית, מורייס, פת, גבינה\u0004 — \u0003מותרין בחותם אחד.\u0004","ומסבירים: \u0003פת,\u0004 אין מצריכים לה שני חותמות, שכן \u0003למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה?\u0004 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום איחלופי קרירא בחמימא\u0004 \u0005[החלפה\u0006 של פת \u0005קרה בחמה]\u0006 — הדבר הזה \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 וניכר\u0005,\u0006 \u0003דחיטי בדשערי נמי מידע ידיע\u0004 \u0005[\u0006החלפה \u0005של חיטים בשל שעורים\u0006 — \u0005גם כן ידוע הדבר],\u0006 \u0003אי כי הדדי\u0004 \u0005[אם\u0006 החלפה של \u0005זה כמו זה,\u0006 שאין הבדל במינם וטיבם\u0005],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חותם אחד לא טרח ומזייף\u0004 \u0005[אינו טורח ומזייף].\u0006","ושואלים: \u0003ורב, מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003גבינה\u0004 שדי לה בחותם אחד? משום \u0003דלא טרח\u0004 \u0005[שאינו טורח]\u0006 \u0003ומזייף,\u0004 שהרי אין רווח גדול מזיוף כזה, \u0003חלב נמי\u0004 \u0005[גם כן]\u0006 \u0003לא טרח\u0004 \u0005[אינו טורח]\u0006 \u0003ומזייף\u0004 מאותה סיבה, ומדוע הצריך שני חותמות? \u0003אמר רב כהנא: אפיק\u0004 \u0005[הוצא]\u0006 מרשימת חבי\"ת \u0003חלב, ועייל\u0004 \u0005[והכנס]\u0006 במקומה \u0003חתיכת דג שאין בה סימן.\u0004","ושואלים: \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003בשר!\u0004 ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003בשר,\u0004 בשר בהמה ובשר דג. עד כאן הדיון בדברי רב.","\u0003ושמואל אומר: בי\"ת אסור בחותם אחד, מח\"ג מותר בחותם אחד.\u0004 בי\"ת שהם: \u0003בשר, יין, תכלת\u0004 — \u0003אסורין בחותם אחד\u0004 (ואינו מזכיר חתיכת דג שאין בה סימן); מח\"ג שהם \u0003מורייס, חילתית, גבינה\u0004 — \u0003מותרין בחותם אחד\u0004 (ואינו מזכיר פת). ומסבירים: \u0003ל\u0004דעת \u0003שמואל, חתיכת דג שאין בה סימן היינו\u0004 \u0005[זהו]\u0006 ממש \u0003בשר,\u0004 ואין צריך לחזור ולשנות זאת, כי הנימוק של \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003בשר לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחין ימ\"ח מח\"ג בסוריא,\u0004 אפילו מיהודים — \u0003לא יין ולא מורייס ולא חלב, ולא מלח סלקונדרית ולא חילתית ולא גבינה, אלא מן המומחה\u0004 כלומר, מי שיודעים בו שהוא מקפיד על כך. שאין מקפידים שם שלא למכור דברים של גוים. \u0003וכולן אם נתארח אצל בעל הבית\u0004 — \u0003מותר\u0004 לאכול כל אלה, ואינו צריך לחשוש.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003לר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: שגר\u0004 (שלח) \u0003לו בעל הבית לביתו\u0004 אחד מכל אלה — \u0003מותר; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003בעל הבית לא שביק היתירא ואכל איסורא\u0004 \u0005[אינו מניח היתר ואוכל איסור\u0006 בכוונה\u0005],\u0006 \u0003וכי משגר ליה, ממאי דאכיל משדר ליה\u0004 \u0005[וכאשר\u0006 הוא \u0005שולח לו, ממה\u0006 שהוא עצמו \u0005אוכל\u0006 הוא \u0005שולח לו],\u0006 אף שלענין מכירה הוא חשוד.","שנינו במשנה: \u0003ומלח סלקונדרית\u0004 אסור באכילה. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003מלח סלקונדרית? אומר רב יהודה אמר שמואל: מלח שכל סלקונדרי\u0004 (נחתומי) \u0003רומי אוכלין אותה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלח סלקונדרית, שחורה\u0004 — \u0003אסורה, לבנה\u0004 — \u0003מותרת, דברי ר' מאיר. ר' יהודה אומר:\u0004 אם היתה \u0003לבנה\u0004 — \u0003אסורה, שחורה\u0004 — \u0003מותרת. ר' יהודה בן גמליאל משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל אומר: זו וזו אסורה.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: לדברי האומר לבנה אסורה,\u0004 הטעם הוא משום ש\u0003קירבי דגים לבנים טמאים מעורבין בה. לדברי האומר שחורה אסורה,\u0004 משום ש\u0003קירבי דגים שחורים טמאים מעורבין בה.\u0004","\u0003לדברי האומר זו וזו אסורה,\u0004 משום ש\u0003זה וזה מעורבין בה,\u0004 ואין זו מחלוקת אלא במה שהיה נהוג במקומו של כל אחד מהם. \u0003אמר ר' אבהו משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל: זקן אחד\u0004 גוי \u0003היה בשכונתנו,\u0004 \u0003שהיה מחליק פניה\u0004 של מלח זה \u0003בשומן חזיר,\u0004 להוסיף שיש מקום לחשוש גם משום איסורים אחרים.","שנינו בסוף המשנה: \u0003הרי אלו אסורים\u0004 ואין איסורם איסור הנאה. ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 הרי כבר פתחה בכך המשנה: ואלו אסורים ואין איסורם איסור הנאה! ומסבירים: \u0003ל\u0004שיטת \u0003חזקיה\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 ולאסור בהנאה \u0003ב\u0004כבשים ש\u0003ידוע\u0004 שהיה שם יין, וכפי שפירש לעיל (עבודה זרה לח,ב). \u0003לר' יוחנן\u0004 שהתיר בהנאה גם כבשים כאלה — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מורייס וגבינת בית אונייקי,\u0004 שהם אסורים בהנאה, \u0003ו\u0004נמצא לפי שיטתו זה כי \u0003סתמא\u0004 \u0005[סתמה\u0006 של \u0005המשנה]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר\u0004 במשנה הקודמת (לעיל עבודה זרה ל,ב), שהם אסורים בהנאה.","\u0003ואלו מותרין באכילה: חלב שחלבו גוי וישראל רואהו\u0004 בשעת חליבה, \u0003והדבש\u0004, \u0003והדבדבניות\u0004 (אשכולות ענבים) \u0003אף על פי שמנטפין\u0004 — שאין לחשוש להם משום יין של גוי. וכן \u0003אין בהן\u0004 גם \u0003משום הכשר משקה\u0004 שאינם נחשבים כיין להכשיר אוכלים לקבל טומאה. \u0003ו\u0004כן מותר לאכול כל מיני \u0003כבשין שאין דרכן לתת לתוכן יין וחומץ, וטרית\u0004 (מן דג) \u0003שאינה טרופה\u0004 (חתוכה) ורואים שדג טהור הוא, \u0003וציר\u0004 של דגים \u0003שיש בה דגה\u0004 כאשר יבואר, \u0003ועלה של חילתית\u0004 שלא נחתך בסכין, \u0003וזיתי גלוסקאות המגולגלין\u0004 זיתים שמכניסים אותם בכלים, כדי שיתחממו ויתרככו מחמת שמן שבהם.","\u0003ר' יוסי אומר: השלחין\u0004 (הרכים ביותר) — \u0003אסורין. החגבים הבאים מן הסלולה\u0004 (מן הסלים) שמוכר החנוני — \u0003אסורין\u0004 שמא זילפו עליהם יין, \u0003מן ההפתק\u0004 (מקום איחסון ארעי) — \u0003מותרין. וכן\u0004 הדין \u0003לתרומה,\u0004 כאשר יבואר בגמרא.","שנינו במשנה כי חלב שחלבו גוי וישראל רואהו מותר. ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנתנו דבר \u0005זה\u0006 \u0005ששנו חכמים]\u0006 בברייתא: \u0003יושב ישראל בצד עדרו של גוי, וגוי חולב לו ומביא לו, ואינו חושש.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דליכא\u0004 \u0005[אם שאין]\u0006 \u0003דבר\u0004 \u0003טמא בעדרו,\u0004 וכל העדר הוא בהמות טהורות — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, \u0003ואי דאיכא\u0004 \u0005[ואם שיש]\u0006 \u0003דבר טמא בעדרו, אמאי\u0004 \u0005[מדוע]\u0006 יהיה מותר?","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003דבר טמא\u0004 בעדרו, \u0003וכי קאי חזי ליה\u0004 \u0005[ו\u0006מדובר כאן ש\u0005כאשר היהודי עומד רואה\u0006 הוא \u0005אותו],\u0006 \u0003וכי יתיב לא חזי ליה\u0004 \u0005[וכאשר\u0006 הוא \u0005יושב אינו רואה אותו];\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דיתיב לא חזי ליה\u0004 \u0005[\u0006שבזמן \u0005ש\u0006הוא \u0005יושב אינו רואה אותו],\u0006 \u0003ניחוש דלמא מייתי\u0004 \u0005[נחשוש שמא מביא]\u0006 חלב טמא \u0003ומערב ביה\u0004 \u0005[בו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003כיון דכי קאי חזי ליה, אירתותי מירתת ולא מיערב ביה\u0004 \u0005[כיון שכאשר\u0006 הוא \u0005עומד הוא רואה אותו,\u0006 הרי הוא \u0005מפחד ואינו מערב בו].\u0006","ועוד שנינו: \u0003והדבש\u0004 של גוים שמותר באכילה. ומסבירים: \u0003דבש למאי ניחוש לה\u0004 \u0005[למה נחשוש לו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום איערובי\u0004 \u0005[תערובת]\u0006 של דבר טמא או יין — \u0003מיסרא סרי\u0004 \u0005[מסריח\u0006 הוא\u0005]\u0006 כשמערבים בו, ואין לחשוש לכך, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום בישולי גוים,\u0004 אפילו אם נתבשל — הרי הוא \u0003נאכל כמו שהוא חי\u0004 ואינו נאסר בבישולם. \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום גיעולי גוים\u0004 שנתבשל בכלי שנתבשל בו איסור — \u0003נותן טעם לפגם הוא\u0004 בדבש, \u0003ומותר.\u0004","שנינו במשנה: \u0003והדבדבניות אף על פי שמנטפות\u0004 — \u0003אין בהן משום הכשר משקה. ורמינהי\u0004 \u0005[ומשליכים\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו: \u0003הבוצר\u0004 ענבים על מנת להביאם \u0003לגת\u0004 לעשות מהם יין, \u0003שמאי אומר: הוכשר\u0004 כלומר, כל מה שהיה באשכולות הוכשר לקבל טומאה מחמת טיפות המיץ המנטפות מן הענבים, ו\u0003הלל אומר: לא הוכשר, ו\u0004אנו יודעים כי \u0003אודי ליה\u0004 \u0005[הודה לו]\u0006 \u0003הלל לשמאי,\u0004 ואם כן הנוטף מן האשכול מכשיר לקבל טומאה!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 במקרה של בוצר לגת, \u0003קא בעי ליה\u0004 \u0005[רוצה הוא אותו\u0006\u0005]\u0006 \u0003למשקה,\u0004 שהרי הוא מעוניין מתחילה בכל המיץ שבענבים כדי לעשות ממנו יין, \u0003הכא לא קא בעי ליה\u0004 \u0005[כאן הוא אינו רוצה אותו]\u0006 \u0003למשקה,\u0004 שהרי הוא מעוניין באכילת הענבים.","שנינו במשנה: \u0003וטרית שאינה טרופה\u0004 וציר שיש בה דגה מותרים באכילה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזו היא טרית שאינה\u0004 נחשבת \u0003טרופה\u0004 אפילו לא היתה דג שלם ממש? \u0003כל שראש ושדרה ניכר\u0004 בה, שבכך יודעים שהיא דג טהור. \u0003ואיזו ציר שיש בה דגה? כל שכילבית אחת\u0004 (מין יצור קטן שגדל בתוך ציר של דגים טהורים) \u0003או שתי כילביות\u0004"],["\u0003שוטטות בו.\u0004 ותחילה תוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003כילבית אחת אמרת שרי\u0004 \u0005[מותר],\u0006 \u0003שתי כילביות מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמותר? ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שצריך שתהיינה לפחות שתיים — \u0003ב\u0004חביות \u0003פתוחות, כאן\u0004 שדי באחת — \u0003בסתומות.\u0004","ובהסבר מה ששנינו בתחילת הברייתא, שטרית שאינה טרופה היא כל שראש ושדרה ניכר, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בכך אמוראים, \u0003רב הונא אמר: עד שתהא\u0004 גם \u0003ראש ו\u0004גם \u0003שדרה ניכר, רב נחמן אמר: או ראש או שדרה. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עוקבא בר חמא\u0004 ממה ששנינו במשנה במסכת חולין: \u0003ובדגים, כל שיש לו סנפיר וקשקשת\u0004 מותר. משמע שרק סנפיר וקשקשים הם סימני דגים טהורים, ואין סימנים של ראש ושדרה! \u0003אמר אביי: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 משנה\u0005]\u0006 הרי זה \u0003ב\u0004מיני הדגים \u0003אראה ופלמודא, דדמו רישייהו\u0004 \u0005[שדומים ראשיהם]\u0006 \u0003ל\u0004דגים \u0003טמאים,\u0004 ולכן אי אפשר לסמוך על סימני הראש בלבד.","\u0003אמר רב יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: מחלוקת\u0004 האם מותר \u0003לטבל בצירן\u0004 של דגים אלה, \u0003אבל בגופן\u0004 — \u0003דברי הכל אסור\u0004 לאוכלם \u0003עד שיהא ראש ושדרה ניכר. אמר ר' זירא: מריש הוה מטבילנא\u0004 \u0005[מתחילה הייתי מטבל]\u0006 \u0003בצירן\u0004 של דגים מעורבים כאלה, ואולם \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי את זה]\u0006 ש\u0003אמר רב יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: מחלוקת לטבל בצירן, אבל בגופן\u0004 — \u0003דברי הכל אסור עד שיהא ראש ושדרה ניכר, בצירן נמי לא מטבילנא\u0004 \u0005[גם כן אין אני מטבל]\u0006 שהרי יש אוסרים בכך.","\u0003אמר רב פפא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 אין להתיר טרית טרופה \u0003עד שיהא ראש ושדרה ניכר של כל אחת ואחת\u0004 מהדגים. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003חתיכות\u0004 של דגים \u0003שיש בהן סימן, בין בכולן בין במקצתן, ואפילו באחד ממאה שבהן\u0004 — \u0003כולן מותרות; ומעשה בגוי אחד שהביא גרב\u0004 (כד גדול) \u0003של חתיכות\u0004 דגים \u0003ונמצא סימן\u0004 טהרה \u0003באחת מהן, והתיר רבן שמעון בן גמליאל את הגרב כולו!\u0004","\u0003תרגמה\u0004 (הסביר אותה) \u0003רב פפא: כשחתיכות\u0004 הדגים \u0003שוות\u0004 תואמות ומצטרפות זו לזו, ואם כן ברור שכל אלה שייכים לדג אחד. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר\u0006 בזה\u0005]\u0006 הרי פשוט הוא שמותר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ניחוש דלמא אתרמי\u0004 \u0005[נחשוש שמא הזדמן\u0006 כך\u0005]\u0006 אבל באמת אין הם מאותו דג, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לכך.","מסופר, \u0003ההוא ארבא דצחנתא דאתי\u0004 \u0005[ספינה אחת של דגים קטנים קצוצים שבאה] ל\u0006עיר \u0003סיכרא,\u0004 ולא ניתן היה לזהותם, \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רב הונא בר חיננא וחזא ביה קלפי ושרייה\u0004 \u0005[וראה בה קשקשים והתיר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ומי איכא דשרי כהאי גוונא באתרא דשכיחי קלפי\u0004 \u0005[האם יש\u0006 מי \u0005שמתיר כגון זה במקום שמצויים קשקשים],\u0006 שמא הקשקשים נשארו מדגים טהורים שהיו קודם באותה ספינה! \u0003נפק שיפורי\u0004 \u0005[יצאו\u0006 בעיר \u0005שופרות]\u0006 מטעם \u0003רבא\u0004 להודיע לכל שהוא \u0003אסור\u0004 אותה ספינה, ויצאו \u0003שיפורי\u0004 \u0005[שופרות]\u0006 מטעם \u0003רב הונא בר חיננא ושרי\u0004 \u0005[והתיר].\u0006","\u0003אמר ר' ירמיה מדפתי, לדידי\u0004 \u0005[לי\u0006 עצמי\u0005]\u0006 \u0003אמר לי רב פפי:\u0004 גם \u0003כי שרא\u0004 \u0005[כאשר התיר]\u0006 \u0003רב הונא בר חיננא\u0004 — הרי זה לטבל \u0003בצירן, אבל בגופן\u0004 עצמן \u0003לא\u0004 התיר. \u0003אמר רב אשי, לדידי\u0004 \u0005[לי]\u0006 \u0003אמר לי רב פפא: כי שרא\u0004 \u0005[כאשר התיר]\u0006 \u0003רב הונא בר חיננא אפילו בגופן\u0004 התיר.","והוסיף רב אשי: \u0003ואנא לא מיסר אסרינא\u0004 \u0005[אני איני אוסר],\u0006 \u0003דקאמר\u0004 \u0005[\u0006משום \u0005שאמר]\u0006 \u0003לי רב פפא\u0004 שרב הונא התיר אפילו בגופן, \u0003ולא מישרא שרינא\u0004 \u0005[ואין אני מתיר]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר (לי) רב יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: מחלוקת לטבל בצירן, אבל בגופן\u0004 — \u0003דברי הכל עד שיהא ראש ושדרה ניכר של כל אחד ואחד.\u0004","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב חיננא בר אידי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אדא בר אהבה ויתיב וקאמר\u0004 \u0005[ויושב\u0006 היה \u0005ואומר]:\u0006 \u0003גוי שהביא עריבה\u0004 (סירה) \u0003מלאה חביות\u0004 של דגים, \u0003ונמצאת כילבית באחת מהן,\u0004 אם היו החביות \u0003פתוחות\u0004 — \u0003כולן מותרות,\u0004 אם היו \u0003סתומות\u0004 — \u0003היא\u0004 החבית שנמצאה בה הכילבית \u0003מותרת, וכולן אסורות. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מנא לך הא\u0004 \u0005[מנין לך\u0006 דבר \u0005זה]?\u0006 אמר לו: \u0003מתלתא קראי שמיע לי\u0004 \u0005[משלושה מקראות אני יודע\u0006 זאת\u0005],\u0006 משלושה חכמים גדולים, שראוי לסמוך עליהם כאילו נכתב הדבר בתורה, \u0003מרב ושמואל ור' יוחנן.\u0004","\u0003אמר רב ברונא אמר רב: קירבי\u0004 (מעי) \u0003דגים ועוברן\u0004 (ביצים של דגים) \u0003אין נקחין\u0004 \u0003אלא מן המומחה\u0004 מי שידוע בו שהוא מוכר רק דגים טהורים. ובענין זה \u0003רמי ליה\u0004 \u0005[השליך\u0006 \u0005לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003עולא לר' דוסתאי מן\u0004 המקום \u0003בירי: מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003רב: קירבי דגים ועוברן אין נקחין אלא מן המומחה, מכלל\u0004 הדברים אתה למד ש\u0003דג טמא אית ליה\u0004 \u0005[יש לו]\u0006 \u0003עובר, ורמינהי\u0004 \u0005[והשלך,\u0006 הקשה על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003דג טמא משריץ\u0004 כלומר, הוא מוליד ולדות חיים, ו\u0003דג טהור מטיל ביצים!\u0004","ענה לו: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן עוברן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: לא תיסמי\u0004 \u0005[אל תמחק],\u0006 \u0003תרוייהו\u0004 \u0005[שניהם],\u0006 גם הטהורים וגם הטמאים, \u0003מטילי ביצים נינהו\u0004 \u0005[הם],\u0006 \u0003אלא זה\u0004 הדג הטהור \u0003משריץ מבחוץ\u0004 שמטיל ביצים ומהן בוקעים דגים, \u0003וזה\u0004 הדג הטמא \u0003משריץ מבפנים,\u0004 הוולדות בוקעים מן הביצים בתוך גוף הדגה.","ושואלים על דבריהם: \u0003למה לי מומחה\u0004 לסמוך עליו? \u0003לבדוק\u0004 \u0005[שנבדוק]\u0006 \u0003בסימנין! דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כסימני ביצים\u0004 של עוף טהור \u0003כך סימני דגים;\u0004 ותחילה תוהים: \u0003סימני דגים\u0004 ממש \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הלוא \u0003סימני דגים סנפיר וקשקשת כתיב בהו\u0004 \u0005[כתוב בהם]\u0006 בתורה! \u0003אלא\u0004 הכוונה היא: \u0003כסימני ביצים כך סימני עוברי\u0004 (ביצי) \u0003דגים,\u0004","\u0003ואלו הן סימני ביצים: כל שכודרת ועגולגלת\u0004 כלומר, שהיא עגולה אבל אינה עגולה לגמרי, אלא \u0003ראשה אחד כד\u0004 (רחב) \u0003וראשה אחד חד\u0004 — הרי זו ביצה \u0003טהורה, שני ראשיה חדין\u0004 או \u0003שני ראשיה כדין\u0004 — הרי זו \u0003טמאה,\u0004 אם היה \u0003חלמון מבחוץ וחלבון\u0004 נמצא \u0003מבפנים\u0004 — הרי זו ביצה \u0003טמאה,\u0004 אם \u0003חלבון מבחוץ וחלמון מבפנים\u0004 — הרי זה \u0003טהור,\u0004 אם היו \u0003חלבון וחלמון מעורבין זה בזה\u0004 — \u0003זו היא ביצת השרץ.\u0004 ואם כן מדוע צריך מומחה? \u0003אמר רבא:\u0004 כאן מדובר \u0003כשנימוחו\u0004 ואי אפשר לבדוק את צורתן.","ושואלים: \u0003ול\u0004שיטת \u0003רב דוסתאי\u0004 ש\u0003מן בירי\u0004 ש\u0003אמר: סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן\u0004 את מה שאמר רב \u0003עוברן,\u0004"],["\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כסימני ביצים כך סימני עוברי דגים,\u0004 משמע שאף לדגים טמאים יש ביצים! ומשיבים: \u0003לאו תרוצי מתרצת לה\u0004 \u0005[וכי אין אתה מתרץ אותה],\u0006 את הברייתא הזו, ומשנה את לשונה? ואם כן שנה כך: \u0003כך סימני קירבי דגים.\u0004","ושואלים: \u0003והיכי משכחת\u0004 \u0005[ואיך אתה מוצא]\u0006 \u0003בסימני קירבי דגים שיהא כד וחד?\u0004 ומשיבים: \u0003משכחת לה בשילפוחא\u0004 \u0005[בשלפוחית]\u0006 השחיה של הדג, ובודקים לפי צורתה אם של דג טמא או טהור היא.","ושואלים: \u0003אם אין שם מומחה, מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003אמר רב יהודה: כיון דאמר\u0004 \u0005[שאומר]\u0006 המוכר: \u0003אני מלחתים\u0004 את הדגים, וטהורים הם, ואני הוצאתי את הקרביים מהם — \u0003מותרין. רב נחמן אמר: עד שיאמר\u0004 ויראה לנו: \u0003אלו דגים\u0004 שהם טהורים, \u0003ואלו קירביהן.\u0004 מסופר, \u0003אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003רב יהודה לאדא דיילא\u0004 \u0005[השמש]:\u0006 \u0003כיון\u0004 ש\u0003אמר \"אני מלחתים\"\u0004 — \u0003מותרין.\u0004 שנינו במשנה ש\u0003עלה של חילתית\u0004 מותר באכילה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא הדין, וכי מדוע יהא אסור? ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא לקרטין\u0004 (לפירורים) של חילתית \u0003ש\u0004יש \u0003בו,\u0004 שהם הרי אסורים כדברי המשנה הקודמת, מפני שנחתכו בסכין של איסור (לעיל עבודה זרה לט,ב), \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש דלמא מייתי\u0004 \u0005[נחשוש שמא\u0006 הוא \u0005מביא]\u0006 קרטין כאלו \u0003ומערב ביה\u0004 \u0005[בו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003דהא אישתרוקי היא דאישתרוק ואתא בהדה\u0004 \u0005[שזה\u0006 קרטין אלו רק \u0005נדבקו ובאו יחד\u0006 עם העלה\u0005],\u0006 ואין זה ממה שחתך בסכין.","","שנינו במשנה: \u0003וזיתי גלוסקאות המגולגלין\u0004 מותרים באכילה, כלומר זיתים שהונחו בכלי ונתרככו שם. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, מדוע יהיו אסורים? ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא להתיר אותם \u0003אף על גב דרפי טובא\u0004 \u0005[אף על פי ש\u0006הם \u0005רכים ביותר],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003חמרא רמא בהו\u0004 \u0005[יין הטיל בהם\u0006 הגוי לרככם\u0005]\u0006 ויהא אסור, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003הני\u0004 \u0005[אלה]\u0006 \u0003מחמת\u0004 שיש בהם \u0003מישחא\u0004 \u0005[שמן]\u0006 \u0003הוא דרפו\u0004 \u0005[שנעשו רכים].\u0006 ועוד שנינו שם: \u0003ור' יוסי אומר: שלחין אסורין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003שלחין? אמר ר' יוסי בר חנינא: כל\u0004 זית שהוא רך כל כך \u0003ש\u0004כאשר הוא \u0003אוחזו בידו וגרעינתו נשמטת\u0004 מתוכו, שאז יש מקום יתר לחשוש שהטילו בהם יין.","","שנינו במשנה: \u0003החגבין הבאין\u0004 מן הסלולה. ומביאים בענין זה מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החגבין, ו\u0004כן \u0003הקפריסין\u0004 (פירות הצלף), \u0003והקפלוטות\u0004 (כרישין), אותם \u0003הבאין מן האוצר\u0004 (מחסן) \u0003ומן ההפתק\u0004 (מקום אחסון ארעי) \u0003ומן הספינה\u0004 — \u0003מותרין,\u0004 מפני שסתמם לא עירבו בהם דבר אסור. אבל \u0003הנמכרין בקטלוזא\u0004 (בשוק) ומונחים \u0003לפני חנוני\u0004 — \u0003אסורין, מפני שמזלף יין עליהן\u0004 להשביחם. \u0003וכן יין תפוחים של גוים,\u0004 אלה \u0003הבאין מן האוצר ומן ההפתק ומן הסלולה\u0004 — \u0003מותרין, הנמכר בקטלוזא\u0004 — \u0003אסור, מפני שמערבין בו יין\u0004 של ענבים. אגב שהזכירו יין תפוחים, מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת חש\u0004 (סבל) \u0003רבי במעיו, אמר: כלום\u0004 \u0003יש איש שיודע,\u0004 האם \u0003יין תפוחים של גוים\u0004 (שמועילה שתייתו לכאב מעיים) \u0003אסור או מותר? אמר לפניו ר' ישמעאל בן ר' יוסי: פעם אחת חש אבא\u0004 (ר' יוסי) \u0003במעיו, והביאו לו יין תפוחים של גוים של\u0004 (בן) \u0003שבעים שנה, ושתה ונתרפא; אמר לו\u0004 רבי: \u0003כל כך היה בידך\u0004 כלומר, פתרון כזה היה בידך, \u0003ואתה מצערני\u0004 שלא גילית לי דבר זה עד עכשיו!","","מיד \u0003בדקו\u0004 (חיפשו) \u0003ומצאו גוי אחד שהיה לו שלש מאות גרבי\u0004 (כדי) \u0003יין של תפוחים של שבעים שנה, ושתה\u0004 מהם \u0003ונתרפא, אמר: ברוך המקום\u0004 (הקב\"ה) \u0003שמסר עולמו לשומרים,\u0004 שגוי זה שמר יינו זמן רב כל כך, עד שהועיל לרפואתו של רבי.","שנינו במשנה: \u0003וכן לתרומה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן לתרומה\"?\u0004 מה שייך ענין תרומה לכאן? \u0003אמר רב ששת: וכן לכהן החשוד למכור תרומה לשם\u0004 (בתורת) \u0003חולין,\u0004 מה שהיה מונח \u0003לפניו הוא\u0004 ש\u0003אסור, אבל הבא מן האוצר ומן ההפתק ומן הסלולה\u0004 — \u0003מותר,\u0004 וטעמו של דבר: \u0003אירתותי מירתת\u0004 \u0005[מפחד\u0006 הוא לעשות כן\u0005],\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003שמעי ביה רבנן ומפסדו ליה מינאי\u0004 \u0005[ישמעו בזה חכמים ויפסידו\u0006 את הכל \u0005ממני],\u0006 שיפקירו את כל מה שאני מוכר.","","\u0003כל הצלמים\u0004 (הפסלים) \u0003אסורין\u0004 בהנאה, \u0003מפני שהן נעבדין פעם אחת בשנה\u0004 לפחות, אלה \u0003דברי ר' מאיר. וחכמים אומרים: אינו אסור\u0004 בהנאה כעבודה זרה \u0003אלא כל\u0004 פסל \u0003שיש בידו מקל או צפור או כדור,\u0004 שהם סמלים המוכיחים שפסל זה הוא עבודה זרה, אבל אחרים לנוי הם. \u0003רבן שמעון בן גמליאל אומר: אף כל\u0004 פסל \u0003שיש בידו כל דבר\u0004 בוודאי עבודה זרה הוא.","על מחלוקת ר' מאיר וחכמים שואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בפסלים ש\u0003נעבדין פעם אחת בשנה, מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שמתירים? הלוא ברור שהם עבודה זרה! \u0003אמר ר' יצחק בר יוסף אמר ר' יוחנן: במקומו של ר' מאיר היו עובדין אותה פעם אחת בשנה\u0004 את כל הפסלים. \u0003ור' מאיר דחייש למיעוטא\u0004 \u0005[\u0006שבכלל, שיטתו הוא \u0005שחושש למיעוט]\u0006 — \u0003גזר\u0004 ב\u0003שאר מקומות אטו\u0004 \u0005[משום]\u0006 \u0003אותו מקום\u0004 בו הוא גר, \u0003ורבנן דלא חיישי למיעוטא\u0004 \u0005[וחכמים שאינם חוששים למיעוט]\u0006 — \u0003לא גזרו שאר מקומות אטו\u0004 \u0005[משום]\u0006 \u0003אותו מקום\u0004 של ר' מאיר.","\u0003אמר רב יהודה אמר שמואל: באנדרטי\u0004 (בפסלי דמותם) \u0003של מלכים שנינו\u0004 שדווקא בהם נחלקו אם יש לאסור בהם משום חשש עבודה זרה או לא. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ובעומדין על פתח מדינה שנינו,\u0004 שרואים שהעמידום במקום חשוב, ויש לחשוש שעובדים להם."],["\u0003אמר רבה: מחלוקת\u0004 ר' מאיר וחכמים היא דווקא \u0003ב\u0004אנדרטאות \u0003של כפרים, אבל בשל כרכים\u0004 — \u0003דברי הכל מותרין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לנוי עבדי להו\u0004 \u0005[עושים אותם]\u0006 ולא לפולחן.","ושואלים: \u0003ו\u0004של \u0003כפרים מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 ש\u0003לנוי קעבדי להו\u0004 \u0005[עושים אותם]?\u0006 והרי של \u0003כפרים ודאי למיפלחינהו עבדי להו\u0004 \u0005[לעבוד אותם עושים אותם]!\u0006","\u0003אלא אי אתמר הכי אתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רבה: מחלוקת בשל כרכים, אבל בשל כפרים\u0004 — \u0003דברי הכל אסורים.\u0004","שנינו במשנה, \u0003וחכמים אומרים: אינן אסורין\u0004 אלא כל שיש בידו מקל או צפור או כדור. ומסבירים: בכל אלו עובדיהם נותנים בהם סימן של אלהות, שהוא מלך העולם, \u0003מקל\u0004 — \u0003שרודה את עצמו תחת כל העולם כולו כמקל,\u0004 כלומר, שהוא רודה את כל העולם כולו תחתיו כמי שרודה בהמה במקל. וחכמים אמרוהו בלשון גנאי. \u0003צפור\u0004 — \u0003שתופש את עצמו תחת\u0004 (כלומר, מעל) \u0003כל העולם כולו כצפור. כדור\u0004 — \u0003שתופש את עצמו תחת\u0004 (כלומר, מעל) \u0003כל העולם כולו כ\u0004מי שמחזיק \u0003כדור\u0004 בידו.","ומעירים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005],\u0006 \u0003הוסיפו עליהן\u0004 חכמים לאסור: זה שיש בידו \u0003סייף,\u0004 או \u0003עטרה\u0004 על ראשו, או \u0003טבעת\u0004 בידו","\u0003.\u0004 ומסבירים: \u0003סייף\u0004 — \u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]\u0006 שאם הפסל מחזיק בידו סייף — הרי פסל של \u0003לסטים\u0004 (שודד) \u0003בעלמא\u0004 \u0005[סתם],\u0006 \u0003ולבסוף סבור\u0004 \u0005[סברו]\u0006 שהכוונה היא \u0003שהורג את עצמו תחת כל העולם כולו\u0004 כלומר, שהורג את העולם כולו תחתיו.","\u0003עטרה\u0004 — \u0003מעיקרא סבור גדיל כלילי בעלמא\u0004 \u0005[מתחילה סברו ש\u0006הוא פסל של מי ש\u0005נושא עטרה סתם],\u0006 \u0003ולבסוף סבור\u0004 \u0005[סברו]\u0006 שהכוונה היא \u0003כעטרה למלך. טבעת\u0004 — \u0003מעיקרא סבור אישתיימא בעלמא\u0004 \u0005[מתחילה סברו\u0006 שהוא פסל של \u0005שליח שנושא חותמת בלבד],\u0006 \u0003ולבסוף סבור\u0004 \u0005[סברו]\u0006 שהכוונה היא \u0003שחותם את עצמו תחת כל העולם כולו\u0004 (כלומר, את עולם כולו תחתיו) \u0003למיתה.\u0004","ועוד שנינו במשנה, \u0003רבן שמעון בן גמליאל\u0004 אומר: אף כל שיש בידו כל דבר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 הכוונה היא \u0003אפילו\u0004 מחזיק בידו \u0003צרור\u0004 (אבן), ו\u0003אפילו קיסם\u0004 עץ.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 אם \u0003תפש בידו צואה, מהו?\u0004 האם רואים זאת כענין של כבוד, או לא? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 שהכוונה היא: \u0003כולי עלמא זילו באפיה כי\u0004 \u0005[\u0006ש\u0005כל העולם מזולזל בעיניו כמו]\u0006 \u0003צואה, או דילמא\u0004 \u0005[שמא]\u0006 \u0003הוא מיהו דזיל באפי כולי עלמא\u0004 \u0005[זה שמזולזל בעיני הכל]\u0006 \u0003כצואה?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003המוצא שברי צלמים\u0004 כלומר, שברים של צורות שאין הוא יודע אם שימשו כעבודה זרה — \u0003הרי אלו מותרין,\u0004 \u0003מצא תבנית יד או תבנית רגל\u0004 — \u0003הרי אלו אסורין, מפני שכיוצא בהן נעבד\u0004 כדבר בפני עצמו.","\u0003אמר שמואל:\u0004 לא רק שברי צלמים, אלא \u0003אפילו שברי עבודה זרה\u0004 שאנו יודעים שהיו נעבדים, הרי אלו מותרים. ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003שברי צלמים,\u0004 משמע שמדובר דווקא באלה שלא ברור אם היו עבודה זרה או לא!","ומשיבים: \u0003הוא הדין\u0004 ש\u0003אפילו שברי עבודה זרה, והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003שברי צלמים\u0004 — הרי זה \u0003משום דקבעי למיתנא סיפא\u0004 \u0005[שרצה לשנות בסוף]\u0006 מקרה כעין זה: \u0003מצא תבנית יד תבנית רגל\u0004 — \u0003הרי אלו אסורין\u0004 למרות שאין ודאות שנעבדו, \u0003מפני שכיוצא בהן נעבד.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא תבנית יד תבנית רגל\u0004 — \u0003הרי אלו אסורין מפני שכיוצא בו נעבד.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006"],["\u0003והא\u0004 \u0005[והרי]\u0006 גם הם \u0003שברים נינהו\u0004 \u0005[הם],\u0006 ושברים מותרים! \u0003תרגמה\u0004 (הסביר אותה) \u0003שמואל:\u0004 מדובר \u0003בעומדין על בסיסן,\u0004 שיש להם בסיס המתוקן להם, שניכר שאינם רק שברים, אלא נעשו כך מתחילה, וכיוצא בהם נעבדים.","\u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003עבודה זרה שנשתברה מאיליה, ר' יוחנן אמר:\u0004 עדיין \u0003אסורה\u0004 היא. \u0003ר' שמעון בן לקיש אמר: מותרת.\u0004","\u0003ר' יוחנן אמר: אסורה, דהא\u0004 \u0005[שהרי]\u0006 \u0003לא בטלה. ר' שמעון בן לקיש אמר: מותרת,\u0004 שכן \u0003מסתמא בטולי מבטיל לה\u0004 \u0005[מן הסתם מבטל\u0006 הוא \u0005אותה],\u0006 \u0003מימר אמר\u0004 \u0005[אומר הוא\u0006 בלבו\u0005]:\u0006 \u0003איהי נפשה לא אצלה, לההוא גברא מצלה ליה\u0004 \u0005[היא\u0006 את \u0005עצמה לא הצילה\u0006 מלהישבר, \u0005את האיש הזה\u0006 שעובד אותה \u0005תציל אותו]?\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש\u0004 מן הכתוב: \u0003\"וראש דגון ושתי כפות ידיו כרתות\u0004 אל המפתן\" (שמואל א ה, ד) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"על כן לא ידרכו כהני דגון\u0004 על מפתן בית דגון\" (שמואל א ה, ה). משמע שאף לאחר שנשברה עבודה זרה נוהגים בה כבוד ויראה!","\u0003אמר לו: משם\u0004 אתה מביא \u0003ראיה? התם\u0004 \u0005[שם]\u0006 הכוונה היא \u0003שמניחין את הדגון,\u0004 שבטל ערכו בעיניהם, \u0003ועובדין את המפתן, דאמרי הכי\u0004 \u0005[שאומרים\u0006 הם \u0005כך]:\u0006 \u0003שבקיה איסריה\u0004 \u0005[עזב אותו שרו,\u0006 כוחו של\u0005]\u0006 \u0003דגון, ואתא איתיב ליה\u0004 \u0005[ובא וישב לו]\u0006 \u0003על המפתן.\u0004","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן ממשנתנו: \u0003המוצא שברי צלמים\u0004 — \u0003הרי אלו מותרין.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שברי עבודה זרה\u0004 — \u0003אסורין!\u0004","ודחה ריש לקיש: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 ותדייק ש\u0003שברי עבודה זרה אסורין, אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003צלמים עצמן אסורין, וסתמא\u0004 \u0005[וסתמה]\u0006 של המשנה הוא \u0003כ\u0004דעת \u0003ר' מאיר\u0004 האוסר במשנה הקודמת את כל הצלמים.","ומקשים: \u0003ו\u0004לדברי \u0003ר' יוחנן,\u0004 כיון שמשנתנו כדעת ר' מאיר, הרי \u0003מ\u0004דברי \u0003ר' מאיר נשמע להו לרבנן\u0004 \u0005[נלמד ל\u0006שיטת \u0005חכמים],\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר ר' מאיר\u0004 כי \u0003צלמים\u0004 עצמם \u0003אסורין\u0004 ובכל זאת \u0003שברי צלמים מותרין,\u0004 אם כן, \u0003לרבנן\u0004 \u0005[לדעת חכמים]\u0006 \u0003עבודה זרה נמי\u0004 \u0005[גם כן]\u0006 נאמר: \u0003היא אסורה ושבריה מותרין!\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בשברי צלמים, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003עבדום אימר\u0004 \u0005[אמור]\u0006 ש\u0003לא עבדום, ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003עבדום\u0004 — \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003בטלום\u0004 לאחר שנשברו, ולכן מתיר ר' מאיר בשברי צלמים, שאינו אלא ספק ספיקא. אבל \u0003עבודה זרה ודאי עבדוה, מי יימר\u0004 \u0005[יאמר]\u0006 ש\u0003בטלה?\u0004 ואם כן, \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ספק\u0004 ביטול, \u0003וודאי\u0004 עבודה זרה, \u0003ואין ספק מוציא מידי ודאי.\u0004","ושואלים: \u0003ו\u0004האם \u0003אין ספק\u0004 מעין זה \u0003מוציא מידי ודאי\u0004 כלל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חבר\u0004 שיודעים בו שנזהר בתרומות ומעשרות \u0003שמת, והניח מגורה\u0004 (מחסן) \u0003מלאה פירות, אפילו הן בני יומן\u0004 שהביאו אותם לשם ביום מותו — \u0003הרי הן בחזקת מתוקנין,\u0004 שמן הסתם עישר אותם.","\u0003והא הכא דודאי טבילי\u0004 \u0005[והרי כאן שודאי היו טבל]\u0006 כשהביאו אותם למגורה, \u0003ספק עשרינהו\u0004 \u0005[עישרם]\u0006 \u0003ספק לא עשרינהו\u0004 \u0005[עישרם],\u0006 \u0003וקאתי\u0004 \u0005[ובא]\u0006 \u0003ספק ומוציא מידי ודאי\u0004 טבל!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003ודאי וודאי הוא,\u0004 ש\u0003ודאי עשרינהו\u0004 \u0005[עישר אותם],\u0006 \u0003כ\u0004דברי \u0003ר' חנינא חוזאה,\u0004 ש\u0003אמר ר' חנינא חוזאה: חזקה על חבר שאינו מוציא דבר שאינו מתוקן\u0004 (בהפרשת תרומה ומעשר) \u0003מתחת ידו,\u0004 ועל חזקה זו אפשר לסמוך.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: יתכן כי \u0003מעיקרא לא טבילי\u0004 \u0005[מתחילה לא\u0006 היו הפירות האלה \u0005טבל]\u0006 ולפיכך אף כאן \u0003ספק וספק הוא,\u0004 וכיצד ייתכן הדבר?","\u0003אפשר דעבד כד\u0004ברי \u0003ר' אושעיא\u0004 ש\u0003אמר: מערים אדם על תבואתו ומכניסה במוץ שלה\u0004 למגורה, ואינו משלים את תיקונה בדישה ובמירוח ערימת התבואה, \u0003כדי שתהא בהמתו אוכלת ופטורה מן המעשר.\u0004 שכל עוד לא נגמרה מלאכת האיסוף והעימור של התבואה לא נכנסה לכלל חיוב תרומה ומעשר, והיא מותרת למאכל בהמה בלי שיהיה צורך לעשר אותה. ויתכן איפוא שמתחילה לא חל חיוב תרומה על התבואה, וכיוון שהיא ספק — בא ספק ומוציא מידי ספק.","ושואלים עוד: \u0003ו\u0004כי \u0003אין ספק מוציא מידי ודאי? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: מעשה בשפחתו\u0004"],["\u0003של מציק\u0004 (איש אלים) \u0003אחד ברימון שהטילה נפל לבור, ובא כהן והציץ\u0004 בבור, שרצה \u0003לידע אם\u0004 נפל זה \u0003זכר\u0004 הוא \u0003אם נקבה\u0004 הוא, שכן יש הבדל בין לידת זכר או נקבה לענין דיני טומאה וטהרה של יולדת. ולא ראה הכהן את הנפל, אלא שיש חשש שמא הנפל נמצא בתוך הבור, ואולי נטמא בטומאת מת מפני שהאהיל עליו, \u0003ובא מעשה לפני חכמים וטיהרוהו, מפני שחולדה וברדלס מצוין שם\u0004 ואכלוהו או גררוהו משם.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003ודאי הטילה נפל, ספק גררוהו\u0004 החיות \u0003ספק לא גררוהו, וקאתי\u0004 \u0005[ובא]\u0006 \u0003ספק\u0004 זה \u0003ומוציא מידי ודאי!\u0004","ודוחים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003הטילה נפל\u0004 ודאי \u0003לבור,\u0004 שהוא ודאי מטמא, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003הטילה כמין נפל לבור,\u0004 ויש איפוא ספק מתחילה אם הוא מטמא.","ומקשים: כיצד אפשר לפרש כך? \u0003והא\u0004 \u0005[והרי]\u0006 רק \u0003\"לידע אם זכר אם נקבה הוא\" קתני\u0004 \u0005[שנה]!\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר]\u0006 זאת כוונת הדברים: \u0003לידע אם רוח הפילה\u0004 כלומר, דבר שאינו בגדר וולד, או \u0003אם נפל הטילה, ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר נפל הטילה, לידע אם זכר אם נקבה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003כיון שחולדה וברדלס מצוין שם\u0004 — \u0003ודאי גררוהו,\u0004 ואין זה ספק.","ושבים לעיקר מחלוקת ר' יוחנן וריש לקיש, בעבודה זרה שנשתברה מאליה שלדעת ריש לקיש היא מותרת. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן ממשנתנו: \u0003מצא תבנית יד\u0004 או \u0003תבנית רגל\u0004 של צלמים — \u0003הרי אלו אסורין, מפני שכיוצא בהן נעבד; אמאי\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 אסורים? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שברים נינהו\u0004 \u0005[הם],\u0006 ולשיטתך שברי עבודה זרה מותרים!","ודוחים: \u0003הא תרגמה\u0004 \u0005[הרי\u0006 כבר \u0005פירש אותה]\u0006 \u0003שמואל:\u0004 \u0003בעומדין על בסיסן,\u0004 שיש לחשוש שהם נעבדים כמות שהם, ואינם בכלל שברים.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן ממה ששנינו: \u0003גוי מבטל עבודה זרה שלו\u0004 שהוא עצמו עובד אותה, או \u0003של חברו\u0004 שחבירו עובד אותה אף שהוא אינו עובדה. \u0003ו\u0004אולם \u0003ישראל אינו מבטל עבודה זרה של גוי.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הדין כך? \u0003תיהוי\u0004 \u0005[תהיה\u0006 זאת\u0005]\u0006 אותה עבודה זרה שביטלה הישראל, \u0003כעבודה זרה שנשתברה מאליה,\u0004 ותהיה מותרת!","\u0003אמר אביי:\u0004 אין מדובר ששבר חלק מן העבודה זרה, אלא \u0003שפחסה\u0004 (שמעך אותה). ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 רק \u0003פחסה\u0004 \u0003מאי הוי\u0004 \u0005[מה\u0006 \u0005בכך]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003פחסה\u0004 את העבודה זרה \u0003אף על פי שלא חסרה\u0004 — \u0003בטלה!\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ש\u0003פחסה גוי, אבל פחסה ישראל לא בטלה.\u0004","\u0003ורבא אמר: לעולם כי\u0004 \u0005[כאשר]\u0006 \u0003פחסה\u0004 \u0003ישראל נמי\u0004 \u0005[גם כן]\u0006 היא \u0003בטלה\u0004 מן הדין. \u0003אלא\u0004 דבר זה שלא יוכל ישראל לבטל עבודה זרה של גוי, הוא \u0003גזרה\u0004 של חכמים \u0003דלמא מגבה לה\u0004 \u0005[שמא מגביה אותה]\u0006 תחילה וקונה אותה לעצמו \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מבטיל לה\u0004 \u0005[אותה],\u0006 \u0003והוי\u0004 \u0005[ו\u0006אז \u0005הריהי]\u0006 \u0003עבודה זרה\u0004 ש\u0003ביד ישראל, וכל עבודה זרה\u0004 ש\u0003ביד ישראל אינה בטלה לעולם.\u0004 אבל עבודה זרה שנשתברה מאליה — בטלה.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 לשיטת ריש לקיש ממה ששנינו: \u0003גוי שהביא אבנים מן המרקוליס\u0004 ערימת אבנים שעשויה לעבודה זרה, \u0003וחיפה בהן\u0004 באבנים הללו \u0003דרכים וטרטיאות\u0004 (תיאטרונות) — הרי האבנים \u0003מותרות\u0004 כיון שהגוי ביטלן, \u0003וישראל שהביא אבנים מן המרקוליס וחיפה בהן דרכים וטרטיאות\u0004 — האבנים \u0003אסורות.\u0004 ויש לשאול: לדעת ריש לקיש \u0003אמאי\u0004 \u0005[מדוע]\u0006 אסורות? \u0003תיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 לפחות \u0003כעבודה זרה שנשתברה מאליה\u0004 שמותרת לשיטתו!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש \u0003כ\u0004דברי \u0003רבא,\u0004 שגזרו שלא יוכל ישראל לבטל עבודה זרה, למרות שאם נשברה בעצמה — הריהי מותרת.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003גוי ששיפה\u0004 (שייף, הקציע) מ\u0003עבודה זרה לצרכו\u0004 כלומר, שהיה צריך למה ששיפה — בין \u0003היא\u0004 עבודה זרה עצמה, \u0003ו\u0004בין \u0003שיפוייה\u0004 — \u0003מותרין,\u0004 שהרי בעצם השיפוי הוא מבטלה, שאינו נוהג בה כבוד. אבל אם עשה את השיפוי הזה \u0003לצרכה,\u0004 כגון לייפותה — \u0003היא אסורה\u0004 עדיין, אבל \u0003שיפוייה\u0004 שאינו רוצה בהם \u0003מותרין,\u0004 שהרי ביטל אותם ואינו רוצה בהם. \u0003וישראל ששיפה עבודה זרה, בין לצרכו בין לצרכה\u0004 — \u0003היא ושיפוייה אסורין.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 כששיפה ישראל שיפוייה אסורים? \u0003תיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 \u0003כעבודה זרה שנשתברה מאליה!\u0004","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש להסביר \u0003כ\u0004דברי \u0003רבא,\u0004 שמשום גזירה היא, שמא יקנה אותה תחילה ישראל.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו, \u0003ר' יוסי אומר:\u0004 עבודה זרה \u0003שוחק וזורה לרוח או מטיל\u0004 אותה \u0003לים. אמרו לו:\u0004 אין תקנה בשחיקה, כי \u0003אף היא נעשה\u0004 (נעשית) \u0003זבל, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח). ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 ייאסר הדבר? \u0003תיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 \u0003כעבודה זרה שנשתברה מאליה!\u0004","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש להבין \u0003כ\u0004דברי \u0003רבא,\u0004 שהוא משום גזירה.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו, \u0003ר' יוסי בן יסיאן אומר: מצא צורת דרקון\u0004 שיש לומר שהוא עבודה זרה, \u0003וראשו חתוך, ספק גוי חתכו ספק ישראל חתכו\u0004 — \u0003מותר, ודאי ישראל חתכו\u0004 — \u0003אסור.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אסור כשחתכו ישראל? \u0003תיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 \u0003כעבודה זרה שנשתברה מאליה!\u0004","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש להשיב \u0003כ\u0004דברי \u0003רבא.\u0004","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו, \u0003ר' יוסי אומר: אף לא\u0004 יקח \u0003ירקות\u0004 הגדלים תחת אשירה (עץ של עבודה זרה) \u0003בימות הגשמים, מפני שהנבייה\u0004 (השלכת) \u0003נושרת עליהן\u0004 ומשמשת לירקות כזבל, ונמצא נהנה מעבודה זרה. ויש לשאול: לשיטת ריש לקיש \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא אסור? \u0003תיהוי\u0004 \u0005[שיהיו]\u0006 אותם העלים שנפלו מן האשירה \u0003כעבודה זרה שנשתברה מאליה!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003עיקר עבודה זרה קיימת,\u0004 שהרי האשירה עדיין עומדת במקומה."],["ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שיפויין\u0004 של אשירה שהזכרנו קודם, ש\u0003עיקר עבודה זרה קיימת, וקתני\u0004 \u0005[ושנה]:\u0006 אם עשה את השיפוי \u0003לצרכה\u0004 — \u0003היא אסורה ושיפוייה מותרין!\u0004","על כן \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר\u0004 באופן אחר: טעם הדבר שהנבייה של אשירה אסורה — \u0003לפי שאין עבודה זרה בטלה דרך גדילתה,\u0004 ודרכה הוא להשיר עלים. עד כאן הקושיות על שיטת ריש לקיש.","ומן הצד השני, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן\u0004 ממה ששנינו: \u0003קן\u0004 של ציפורים \u0003ש\u0004היה מצוי \u0003בראש האילן של הקדש\u0004 — \u0003לא נהנין\u0004 מהקן הזה, \u0003ו\u0004מן הצד האחר \u0003לא מועלין\u0004 שאם נהנה ממנו אינו מביא קרבן מעילה. אם היה הקן \u0003בראשה של אשרה\u0004 — \u0003יתיז\u0004 את הקן \u0003בקנה,\u0004 ולא יטפס על העץ כדי להורידו, שהרי אסור לו ליהנות מעבודה זרה.","ומעירים: \u0003קא סלקא דעתך\u0004 \u0005[עולה בדעתך]\u0006 כהנחה ראשונה, שהקן שמדובר עליו הוא \u0003כגון ש\u0004הציפור \u0003שברה ממנו\u0004 מן העץ \u0003עצים וקינתה\u0004 (ועשתה את קינה) \u0003בהן, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003יתיז בקנה\u0004 כלומר שמותר להשתמש בקן, ומכאן שעבודה זרה שנשתברה מאליה מותרת בהנאה!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון דאייתי\u0004 \u0005[שהביאה]\u0006 הצפור \u0003עצים מעלמא\u0004 \u0005[מהעולם]\u0006 ולא מהאשירה עצמה, \u0003וקינתה\u0004 (ועשתה את קינה) \u0003בהן.\u0004","ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר, \u0003דקתני\u0004 \u0005[ששנה]\u0006 בתחילת המשנה ל\u0003גבי הקדש: לא נהנין ולא מועלין; אי אמרת בשלמא דאייתי עצים מעלמא\u0004 \u0005[נניח אם אתה אומר\u0006 שמדובר במשנה זו \u0005שהביאה עצים מהחוץ],\u0006 \u0003היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 ל\u0003גבי הקדש: לא נהנין ולא מועלין, לא נהנין\u0004 לכתחילה מקן זה — \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 שאסרו דבר זה כדי שלא יבואו להשתמש בעץ של ההקדש עצמו, \u0003ו\u0004אולם \u0003לא מועלין מדאורייתא\u0004 \u0005[מן התורה]\u0006 בקן, \u0003דהא לא קדישי\u0004 \u0005[שהרי לא קדושים]\u0006 עצים אלו,","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר במשנה \u0003ששברה עצים ממנו\u0004 מן העץ של ההקדש עצמו \u0003וקינתה בהן, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא מועלין\u0004 בהם מדין תורה? \u0003הא קדישי\u0004 \u0005[הרי קדושים\u0006 הם\u0005]!\u0006","ודוחים: \u0003מידי איריא\u0004 \u0005[כלום שייך הדבר]?\u0006 אין מכאן ראיה, \u0003הכא\u0004 \u0005[כאן]\u0006 לא בגוף העץ שהוקדש מדובר, אלא \u0003בגידולין הבאין לאחר מכאן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וקא סבר\u0004 \u0005[וסבור\u0006 חכם \u0005זה]\u0006 כי \u0003אין מעילה בגידולין\u0004 של הקדש.","\u0003ור' אבהו אמר\u0004 בשם \u0003ר' יוחנן\u0004 דרך אחרת להסביר את המשנה לשיטתו: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"יתיז\"\u0004 ששנינו? \u0003יתיז באפרוחין\u0004 כלומר, את האפרוחים יכול להפיל כדי לאוכלם, אבל לא ישתמש בקן עצמו, ואם כן אין מכאן קושיה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא, אסברה\u0004 \u0005[ואסביר אותה\u0006 את המשנה\u0005]\u0006 \u0003לך:\u0004 \u0003ב\u0004מקרה שהיו \u0003אפרוחין\u0004 בתוך הקן — \u0003כאן וכאן,\u0004 בין בהקדש בין בעבודה זרה, \u0003מותרין\u0004 הם, \u0003בביצים\u0004 — \u0003כאן וכאן אסורין. אמר רב אשי: ואפרוחין שצריכין לאמן כביצים דמו\u0004 \u0005[נחשבים],\u0006 ואסורים בהנאה.","\u0003המוצא כלים ועליהם צורת חמה,\u0004 או \u0003צורת לבנה,\u0004 או \u0003צורת דרקון\u0004 — הרי אלו אסורים בהנאה ו\u0003יוליכם לים המלח\u0004 (כלומר, יאבדם), שחזקתם שהם משמשים לעבודה זרה. \u0003רבן שמעון בן גמליאל אומר:\u0004 צורות אלה \u0003ש\u0004הן \u0003על\u0004 הכלים \u0003המכובדין\u0004 — \u0003אסורין,\u0004 שיתכן שהם נעבדים, \u0003שעל\u0004 הכלים \u0003המבוזין\u0004 — \u0003מותרין.\u0004","על עצם האיזכור של צורות חמה, לבנה ודרקון, שואלים: \u0003למימרא, דלהני הוא דפלחי להו, למידי אחרינא לא\u0004 \u0005[האם לומר שלאלה הוא שעובדים להם,\u0006 ו\u0005לדבר אחר לא]?\u0006 \u0003ורמינהי\u0004 \u0005[ומקשים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה אחרת: \u0003השוחט לשום\u0004 (לשם) פולחן לכל דבר שהוא: לשם \u0003ימים, לשום נהרות, לשום מדבר, לשום חמה, לשום לבנה, לשום כוכבים ומזלות,\u0004 או \u0003לשום מיכאל\u0004 המלאך ה\u0003שר הגדול, לשום שילשול\u0004 (מין תולעת) \u0003קטן\u0004 — \u0003הרי\u0004 כל אחד מ\u0003אלו\u0004 הם \u0003זבחי מתים\u0004 כלומר, זבחי עבודה זרה. משמע שעבודה זרה יכולה להיות בצורות רבות ושונות!","\u0003אמר אביי: מיפלח\u0004 \u0005[לעבוד]\u0006 \u0003לכל\u0004 מה \u0003דמשכחי פלחי\u0004 \u0005[ש\u0006הם \u0005מוצאים\u0006 הם \u0005עובדים],\u0006 אבל \u0003מיצר ומפלחי\u0004 \u0005[לצור\u0006 צורות \u0005ולעבוד],\u0006 \u0003הני תלתא דחשיבי ציירי להו ופלחי להו\u0004 \u0005[\u0006דווקא \u0005שלושה אלה ש\u0006הם \u0005חשובים, צרים אותם ועובדים אותם],\u0006 \u0003למידי אחרינא\u0004 \u0005[לדבר אחר]\u0006 — \u0003לנוי בעלמא עבדי להו\u0004 \u0005[בלבד עושים אותם]\u0006 ולא לשם עבודה זרה.","מסופר, \u0003מנקיט\u0004 \u0005[אוחז,\u0006 אוסף היה בידו\u0005]\u0006 \u0003רב ששת חומרי מתנייתא ותני\u0004 \u0005[\u0006את \u0005הפרטים של המשניות\u0006 בענין זה, \u0005ושונה\u0006 אותן יחד\u0005]\u0006 בדרך זו: \u0003כל המזלות\u0004 (גרמי השמים) צורותיהם \u0003מותרין\u0004 — \u0003חוץ ממזל חמה ולבנה, וכל הפרצופין\u0004 \u0003מותרין\u0004 — \u0003חוץ מפרצוף אדם, וכל הצורות\u0004 של דברים אחרים \u0003מותרות\u0004 — \u0003חוץ מצורת דרקון.\u0004","ודנים בדבריו, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל המזלות מותרין חוץ ממזל חמה ולבנה.\u0004 ויש לשאול: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בעושה\u0004 אותם, אם מותר או אסור לעשותם; הרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעושה\u0004 מדובר, \u0003כל המזלות מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תעשון אתי\"\u0004 (שמות כ, כ), ודרשו חכמים: \u0003לא תעשון כדמות שמשי המשמשין לפני במרום,\u0004 שהם נמצאים אתי, משמע שאסור לעשות צורות של כל מיני מזלות!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003במוצא\u0004 כלים שיש עליהם צורות של מזלות, \u0003וכדתנן\u0004 \u0005[וכמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוצא כלים ועליהם צורת חמה,\u0004 או \u0003צורת לבנה, צורת דרקון\u0004 — \u0003יוליכם לים המלח.\u0004","ואולם \u0003אי\u0004 \u0005[אם]\u0006 מדובר כאן \u0003במוצא, אימא מציעתא\u0004 \u0005[אמור\u0006 את ההלכה \u0005האמצעית]:\u0006 \u0003כל הפרצופות מותרין\u0004 — \u0003חוץ מפרצוף אדם; אי\u0004 \u0005[אם]\u0006 מדובר \u0003במוצא, פרצוף אדם מי\u0004 \u0005[האם]\u0006 \u0003אסור? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוצא כלים ועליהם צורת חמה, צורת לבנה, צורת דרקון\u0004 — \u0003יוליכם לים המלח.\u0004 ונדייק מכאן: \u0003צורת דרקון\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אסורה, \u0003פרצוף אדם\u0004 — \u0003לא!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר בהלכה זו לגבי מי ש\u0003עושה\u0004 את הצורות הללו, \u0003וכ\u0004דברי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 להלן (עבודה זרה מג,ב).","אלא שיש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעושה\u0004 מדובר, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את ההלכה \u0005שבסוף]:\u0006 \u0003כל הצורות מותרות\u0004 — \u0003חוץ מצורת דרקון; ואי\u0004 \u0005[ואם]\u0006 מדובר רק \u0003בעושה, צורת דרקון מי אסיר\u0004 \u0005[האם אסור]\u0006 לעשות? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תעשון אתי אלהי כסף ואלהי זהב\"\u0004 (שמות כ, כ), ודרשו חכמים: לא תעשון כדמות שמשי המשמשים לפני במרום,"],["ונדייק: \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 אסורים בעשייה, אבל \u0003צורת דרקון\u0004 — \u0003לא!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר בהלכה זו \u0003במוצא, וכדתנן\u0004 \u0005[וכמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוצא כלים ועליהם צורת חמה\u0004 ולבנה ודרקון — יוליכם לים המלח.","אם כן תמוה, וכי אפשר לפרש ש\u0003רישא וסיפא\u0004 \u0005[בראש ובסוף]\u0006 של הלכות אלה מדובר \u0003במוצא\u0004 כלים אלה, \u0003ומציעתא\u0004 \u0005[ובאמצעית]\u0006 מדובר \u0003בעושה\u0004 אותם?","\u0003אמר אביי: אין\u0004 \u0005[כן],\u0006 כך נפרש אותן: \u0003רישא וסיפא\u0004 \u0005[ראש וסוף]\u0006 \u0003במוצא, ומציעתא\u0004 \u0005[ואמצעית]\u0006 \u0003בעושה,\u0004 ואין לתמוה על כך.","\u0003רבא אמר: כולה\u0004 מדברת \u0003במוצא, ומציעתא\u0004 \u0005[ואמצעית]\u0006 ממנה עולה כי המוצא כלי ועליו פרצוף אדם אסור, שיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה מוסיף\u0004 על הצלמים האסורים \u0003אף דמות\u0004 אשה \u0003מניקה וסר אפיס,\u0004 ומסביר: דמות \u0003מניקה\u0004 — \u0003על שם חוה שמניקה כל העולם כולו,\u0004 שכל בני האדם בניה הם. \u0003סר אפיס\u0004 — \u0003על שם יוסף ש\u0004היה \u0003סר\u0004 \u0005[בודק]\u0006 \u0003ומפיס\u0004 (מרצה) \u0003את כל העולם כולו.\u0004 ומעירים: \u0003ו\u0004מה שנאמר בסר אפיס שאסור \u0003הוא\u0004 דווקא כשעושים אותו בצורה \u0003דנקיט גריוא וקא כייל\u0004 \u0005[שמחזיק\u0006 בידו \u0005סאה ומודד\u0006 בה\u0005],\u0006 וכן לגבי מניקה — \u0003והיא דנקטא\u0004 \u0005[שמחזיקה]\u0006 עליה \u0003בן וקא מניקה\u0004 \u0005[ומניקה\u0006 אותו\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו צורת דרקון\u0004 שנאסרה במשנה, שאינה צורת נחש סתם או חיה אחרת? \u0003פירש ר' שמעון בן אלעזר: כל שיש לו ציצין\u0004 (כעין סנפירים) שמצויירים לו \u0003בין פרקיו. מחוי\u0004 \u0005[מראה היה]\u0006 \u0003ר' אסי\u0004 בידו בפירוש הדברים \u0003בין פרקי צואר. אמר ר' חמא בר' חנינא: הלכה כר' שמעון בן אלעזר.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יהושע בן לוי: פעם אחת הייתי מהלך אחר ר' אלעזר הקפר בריבי\u0004 (הגדול) \u0003בדרך, ומצא שם טבעת ועליה צורת דרקון, ומצא גוי קטן ולא אמר לו כלום, מצא גוי גדול ואמר לו: בטלה,\u0004 בטל את העבודה הזרה הזו, \u0003ולא בטלה, סטרו\u0004 והכריחו לבטל, \u0003ו\u0004אכן \u0003בטלה.\u0004","ואומרים: \u0003שמע מינה תלת\u0004 \u0005[למד מכאן שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003גוי מבטל עבודה זרה שלו ושל חבירו,\u0004 בין שהיא שייכת לו בין שהיא שייכת לאחר, בין שהוא עובדה בין שאינו עובדה. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שמי ש\u0003יודע בטיב של עבודה זרה ומשמשיה\u0004 הוא \u0003מבטל, ושאינו יודע בטיב עבודה זרה ומשמשיה\u0004 — \u0003אינו מבטל,\u0004 ולכן רק גוי גדול יכול לבטל. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003גוי מבטל בעל כרחו.\u0004","\u0003מגדף\u0004 \u0005[היה מתקיף\u0006 ומתקשה\u0005]\u0006 \u0003בה ר' חנינא, ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לר' אלעזר הקפר בריבי הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 בהלכות מציאת אבידה: \u0003המציל\u0004 כל דבר \u0003מן הארי ומן הדוב ומן הנמר, ומן הגייס, ומן הנהר, ומזוטו של ים, ומשלוליתו של נהר, והמוצא בסרטיא\u0004 (דרך ראשית) \u0003ופלטיא\u0004 (רחבה) \u0003גדולה,\u0004 \u0003ובכל מקום שהרבים מצוין שם\u0004 — \u0003הרי אלו שלו, מפני שהבעלים מתייאשין מהן.\u0004 ואם כן, כיון שאבדה בדרך — כבר נתייאש הגוי ממנה, ובטלה, ומדוע צריכה ביטול נוסף?","\u0003אמר אביי: נהי דמינה מייאש, מאיסורא מי מייאש\u0004 \u0005[אם אמנם שממנה\u0006 מהטבעת עצמה \u0005מתייאש\u0006 המאבד, \u0005מן האיסור\u0006 שבה \u0005האם\u0006 הוא \u0005מתייאש]?\u0006 שאין המאבד מבטלה מלהיות עבודה זרה, \u0003מימר אמר\u0004 \u0005[אומר\u0006 הוא בליבו\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003גוי משכח לה\u0004 \u0005[ימצא אותה]\u0006 — \u0003מפלח פלח לה\u0004 \u0005[יעבוד אותה\u0006 את הצורה\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ישראל משכח לה\u0004 \u0005[ימצא אותה]\u0006 — \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003דמיה יקרין מזבין לה\u0004 \u0005[\u0006הריהו \u0005מוכר אותה]\u0006 \u0003לגוי ופלח לה\u0004 \u0005[ו\u0006אותו גוי \u0005עובד אותה],\u0006 ומשום כך אין הגוי המאבד מתייאש מצד עבודה זרה שבה, ולכן צריך היה לבטלה באופן אחר.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003דמות צורות לבנות היה לו לרבן גמליאל בעלייתו\u0004 שהיו מצויירים \u0003בטבלא\u0004 (לוח) \u0003בכותל, שבהן\u0004 היה \u0003מראה את ההדיוטות\u0004 שהיו באים להעיד על ראיית הלבנה לקידוש החודש, \u0003ואומר להן\u0004 ושואל אותם: \u0003כזה ראיתם או כזה ראיתם?\u0004 כדי לברר מה באמת ראו, משום שלא יכלו להסביר היטב כיצד ראו, והיו צריכים להראות להם.","ועל כך שואלים: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 לצייר צורות לבנה? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תעשון אתי\u0004 אלהי כסף ואלהי זהב לא תעשו לכם\" (שמות כ, כ), ולמדו מכאן: \u0003לא תעשון כדמות שמשי המשמשים לפני\u0004 (\"אתי\")!","\u0003אמר אביי: לא אסרה תורה\u0004 לעשות \u0003אלא שמשין שאפשר לעשות כמותן\u0004 ממש בעולם הזה, באותן מדות ובאותם חומרים,","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 לענין המקדש וכליו, שגם הם משמשים לפניו: \u0003לא יעשה אדם בית\u0004 שיהיה בדיוק ב\u0003תבנית\u0004 ה\u0003היכל\u0004 שבמקדש, ולא יעשה \u0003אכסדרה\u0004 (מרפסת מקורה) ב\u0003תבנית\u0004 ה\u0003אולם\u0004 שהיה במקדש, או \u0003חצר\u0004 ב\u0003תבנית עזרה\u0004 שבמקדש, ו\u0003שולחן\u0004 שבביתו לא יעשה ב\u0003תבנית שולחן\u0004 של המקדש, \u0003מנורה\u0004 לא יעשה אותה ב\u0003תבנית מנורה\u0004 של המקדש, \u0003אבל הוא עושה\u0004 מנורה \u0003של חמש ושל שש ושל שמונה\u0004 קנים. \u0003ושל שבע\u0004 קנים, כמו במקדש, \u0003לא יעשה אפילו\u0004 היא \u0003של שאר מיני מתכות,\u0004 ולא מזהב כמנורת המקדש.","\u0003ר' יוסי בר יהודה אומר: אף של עץ לא יעשה,\u0004 שלא יעשה \u0003כדרך שעשו בית חשמונאי\u0004 שעשו מתחילה מנורה של עץ.","\u0003אמרו לו: משם ראיה?\u0004 מתחילה \u0003שפודין של ברזל היו,\u0004 שהשתמשו בברזלים של חניתות, \u0003וחופין\u0004 (וחיפו אותם) \u0003בבעץ\u0004 (בדיל), כיון ש\u0003העשירו\u0004 לאחר זמן \u0003עשאום של כסף, חזרו והעשירו עשאום של זהב.\u0004 ומברייתא זאת למד אביי שהאיסור הוא לעשות שמשים בדיוק כפי שהם, וירח ממש הרי אי אפשר לעשות, ולכן מותר לעשות את צורתו.","ושואלים: \u0003ושמשין שאי אפשר לעשות כמותן מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא תעשון אתי\"\u0004 (שמות כ, כ), כוונתו: \u0003לא תעשון כדמות שמשי המשמשים לפני\u0004 \u0003במרום!\u0004","\u0003אמר אביי:\u0004"],["\u0003לא אסרה תורה אלא בדמות ארבעה פנים בהדי הדדי\u0004 \u0005[יחד],\u0006 שהוא עושה צורה כצורת חיות הקודש שיש להן (כמבואר בתיאור מעשה המרכבה בספר יחזקאל א׳:ו׳) ארבעה פנים לאחת: פני שור, פני אריה, פני נשר ופני אדם, וחיות הקודש הן \"אתי\".","ושואלים: \u0003אלא מעתה,\u0004 לפי זה, עשיית \u0003פרצוף אדם לחודיה\u0004 \u0005[לבדו]\u0006 בלא שאר שלושת הפנים \u0003תשתרי\u0004 \u0005[תהיה מותרת],\u0006 \u0003אלמה תניא\u0004 \u0005[מדוע שנינו]:\u0006 \u0003כל הפרצופות מותרין, חוץ מפרצוף אדם?\u0004","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 \u0003מפרקיה\u0004 \u0005[משיעורו,\u0006 מלימודו\u0005]\u0006 של \u0003ר' יהושע שמיע לי\u0004 \u0005[שמעתי]\u0006 כי הכתוב \u0003\"לא תעשון אתי\"\u0004 (שמות כ, כ) יש לפרשו: \u0003לא תעשון אותי,\u0004 ולכן אין לעשות פרצוף אדם, שהוא כעין דוגמה של מעלה, שנאמר: \"בצלם אלוקים עשה את האדם\" (בראשית ט, ו). \u0003אבל שאר שמשין\u0004 שבמרום \u0003שרי\u0004 \u0005[מותר],\u0006 ולכן עשה רבן גמליאל דמות צורות לבנה.","ומקשים: \u0003ושאר שמשין מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא תעשון אתי\"\u0004 — \u0003לא תעשון כדמות שמשי המשמשין לפני במרום, כגון\u0004 הדרך שבה מתוארים כדברי הנביאים \u0003אופנים ושרפים וחיות הקדש ומלאכי השרת!\u0004","\u0003אמר אביי: לא אסרה תורה אלא שמשין שבמדור העליון\u0004 כגון המלאכים, אבל לא החמה והלבנה.","ושואלים: \u0003ושבמדור התחתון מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \"לא תעשה לך פסל וכל תמונה \u0003אשר בשמים\"\u0004 (שמות כ, ד) — \u0003לרבות חמה ולבנה כוכבים ומזלות, \"ממעל\"\u0004 (שמות כ, ד) — \u0003לרבות מלאכי השרת!\u0004","ומשיבים: דבר זה לא נאמר לענין איסור עשיה, אלא \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 באיסור \u0003לעובדם.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לעובדם,\u0004 מדוע דווקא אלה? \u0003אפילו שילשול\u0004 (תולעת) \u0003קטן נמי\u0004 \u0005[גם כן]\u0006 אסור לעובדו! ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 \u0003ו\u0004אולם דבר זה \u0003מסיפיה דקרא נפקא\u0004 \u0005[מסופו של\u0006 אותו \u0005מקרא,\u0006 פסוק, \u0005יוצא],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אשר בארץ\"\u0004 (שמות כ, ד) — הרי זה בא \u0003לרבות\u0004 שאסור לעבוד \u0003ימים ונהרות הרים וגבעות, \"מתחת\"\u0004 (שמות כ, ד) — \u0003לרבות שילשול קטן.\u0004","וחוזרים ושואלים על מעשהו של רבן גמליאל: \u0003ועשייה גרידתא\u0004 \u0005[לבדה]\u0006 של צורת חמה ולבנה, בלי לעובדם, \u0003מי שרי\u0004 \u0005[האם מותרת]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא תעשון אתי\"\u0004 — \u0003לא תעשון כדמות שמשי המשמשין לפני במרום, כגון חמה ולבנה, כוכבים ומזלות!\u0004","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רבן גמליאל,\u0004 ש\u0003אחרים\u0004 (גוים) \u0003עשו לו\u0004 את הצורות הללו.","ושואלים: ובמקום שאחרים עושים, מותר לו לאדם להניחו ברשותו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יהודה,\u0004 ש\u0003אחרים עשו לו\u0004 צורה על חותם שהיה בטבעתו, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול שיניים],\u0006 \u0003סמי עיניה דדין\u0004 \u0005[עוור\u0006 את \u0005עינו של זה]\u0006 כלומר, טשטש את צורת הפרצוף שלו!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר היה \u0003בחותמו בולט,\u0004 \u0003ומשום חשדא\u0004 \u0005[החשד\u0006 שיש בכך\u0005].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003טבעת שחותמה בולט\u0004 ויש בה צורה — \u0003אסור להניחה\u0004 על אצבעו, משום שהיא נראית כעבודה זרה, \u0003ומותר לחתום בה\u0004 משום שהחתימה יוצאת שקועה, ואינה נראית כעבודה זרה. טבעת ש\u0003חותמה שוקע\u0004 — \u0003מותר להניחה\u0004 על אצבעו, מפני שאינה דמות, \u0003ואסור לחתום בה\u0004 משום שהיא יוצרת צורה בולטת.","ושואלים: \u0003ומי חיישינן לחשדא\u0004 \u0005[והאם חוששים אנו לחשד]?\u0006 \u0003והא בי כנישתא דשף ויתיב\u0004 \u0005[והרי\u0006 אותו \u0005בית כנסת\u0006 מפורסם \u0005שנפל והוקם]\u0006 \u0003בנהרדעא, דאוקמי ביה אנדרטא\u0004 \u0005[שהעמידו בו פסל\u0006 של המלך\u0005],\u0006 \u0003והוו עיילי ביה\u0004 \u0005[והיו נכנסים בו]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל ולוי ומצלו בגויה\u0004 \u0005[ומתפללים בו],\u0006 \u0003ולא חיישי לחשדא\u0004 \u0005[חששו לחשד]!\u0006 ומשיבים: מקום של \u0003רבים שאני\u0004 \u0005[שונה],\u0006 ואין חושדים בציבור.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבן גמליאל\u0004 ש\u0003יחיד הוה\u0004 \u0005[היה]\u0006 והיה מקום לחשוד בו! ומשיבים: \u0003כיון\u0004 ש\u0003נשיא הוא, שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רבים גביה\u0004 \u0005[אצלו].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: זו של רבן גמליאל לא היתה צורה שלימה, אלא של \u0003פרקים הואי\u0004 \u0005[היתה],\u0006 שהיו מרכיבים ומפרקים אותה, וכיון שכן לא היה מקום לחשד.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003להתלמד שאני\u0004 \u0005[שונה]\u0006 הדבר, שאם צריך הדבר לשם לימוד כדרך שעשה רבן גמליאל — מותר, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לענין איסור עשיה של עבודה זרה: \u0003\"לא תלמד לעשות\u0004 כתועבת הגוים ההם\" (דברים יח, ט), דוקא לעשות, \u0003אבל אתה למד\u0004 כדי \u0003להבין ולהורות\u0004 הלכה.","שנינו במשנה: \u0003רבן שמעון בן גמליאל אמר\u0004 שיש להבדיל אם הצורות שעל הכלים הן על המבוזים או על המכובדים. ושואלים: \u0003איזו הן מכובדין, ואיזו הן מבוזין?\u0004","\u0003אמר רב: מכובדין\u0004 — הם כלים שהצורות מצויות \u0003למעלה מן המים\u0004 (או האוכל) שבתוכם, \u0003מבוזין\u0004 — שנמצאים \u0003למטה מן המים. ושמואל אמר: אלו ואלו מבוזין הן, אלא אלו הן מכובדין\u0004 — הצורות \u0003שעל השירין\u0004 (אצדעות) \u0003ועל הנזמים ועל הטבעות.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל: מכובדין\u0004 — \u0003ש\u0004עושים אותם \u0003על השירין ועל הנזמים ועל הטבעות, מבוזין\u0004 — אלה \u0003ש\u0004עושים אותם \u0003על היורות\u0004 (סירים גדולים) \u0003ועל הקומקמסין\u0004 (כלי חימום קטנים) \u0003ועל מחמי\u0004 מים \u0003חמים, ושעל הסדינין ועל המטפחות,\u0004 שכיון שמשתמשים בהם לכל מיני תשמיש, לא עשו אותם לעבודה זרה אלא כקישוט בלבד.","במשנה הקודמת שנינו כי המוצא צורה שיש לחשוד בה כעבודה זרה יוליכה לים המלח. ואילו \u0003ר' יוסי אומר: שוחק\u0004 אותה \u0003וזורה\u0004 את השחקים \u0003לרוח, או מטיל\u0004 אותה \u0003לים. אמרו לו:\u0004 מה ששוחק וזורה \u0003אף הוא נעשה זבל\u0004 ומביא תועלת לאנשים, וגם הנאה זו אסורה, \u0003שנאמר: \"לא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 כהמשך של הדיון במשנה זו: \u0003אמר להם ר' יוסי, והלא כבר נאמר: \"ואת חטאתכם\u0004"],["\u0003אשר עשיתם את העגל לקחתי ואשרף אתו באש ואכת אתו טחון היטב עד אשר דק לעפר ואשלך את עפרו אל הנחל הירד מן ההר\"\u0004 (דברים ט, כא), משמע שאפשר לבטל עבודה זרה על ידי שחיקה, ואין חוששים במה שמזבל בכך!","\u0003אמרו לו: משם ראיה? הרי הוא אומר\u0004 בענין זה: \u0003\"ויזר על פני המים וישק את בני ישראל\"\u0004 (שמות לב, כ), שלא על מנת לאבד את העגל שחקו בנחל, אלא \u0003לא נתכוין\u0004 משה \u0003אלא לבודקן\u0004 לבני ישראל בשתיית מי הנחל שבהם שחיקת העגל, כדי שהחוטאים ימותו על ידי כך, \u0003כסוטות\u0004 השותות ממי סוטה ונבדקות בהם.","\u0003אמר להם ר' יוסי\u0004 ראיה אחרת, \u0003והלא כבר נאמר\u0004 על המלך אסא: \u0003\"וגם את מעכה אמו\u0004 אם המלך \u0003הסירה מגבירה אשר עשתה מפלצתה\u0004 \u0003וידק\u0004 (כלומר, טחן) \u0003וישרף בנחל קדרון\"\u0004 (ראה מלכים א טו, יג. דברי הימים ב טו, טז) ומשמע מכאן שאין חוששים שמא יזבלו בשחיקת עבודה זרה! \u0003אמר לו:\u0004 וכי \u0003משם\u0004 יש \u0003ראיה?\u0004 והלוא \u0003נחל קדרון אינו מגדל צמחין.\u0004","ותוהים: \u0003ולא,\u0004 האם אינו מגדל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 משנה\u0005]:\u0006 \u0003אלו ואלו,\u0004 גם שיירי דם של הקרבנות שמזים בקדש הקדשים, וגם שיירי דם הקרבנות שנזרקים על מזבח החיצון, \u0003מתערבין באמה\u0004 (תעלת המים שהיתה בקרקע המקדש) \u0003ויוצאין לנחל קדרון, ונמכרין לגננין לזבל, ומועלין בהן!\u0004 ומשיבים: \u0003מקומות מקומות יש בו\u0004 בנחל קדרון, \u0003יש מקום\u0004 בנחל קדרון ש\u0003מגדל צמחין,\u0004 ולשם היתה האמה מגיעה, \u0003ויש מקום שאין מגדל צמחין,\u0004 ולשם זרקו את אפר המפלצת שעשתה מעכה.","אגב כך שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מפלצתה\"? אמר רב יהודה: דהוה\u0004 \u0005[שהיתה]\u0006 \u0003מפליא\u0004 (מרבה) \u0003ליצנותא\u0004 \u0005[ליצנות],\u0006 \u0003כדתני\u0004 \u0005[כמו ששנה]\u0006 \u0003רב יוסף\u0004 בהסבר הדבר: \u0003כמין\u0004 אבר \u0003זכרות עשתה לה, והיתה נבעלת לו בכל יום.\u0004","וממשיכה הברייתא, \u0003אמר להן ר' יוסי\u0004 ראיה נוספת, \u0003והלא כבר נאמר\u0004 על חזקיה המלך: \u0003\"וכתת נחש נחשת אשר עשה משה\u0004 כי עד הימים ההמה היו בני ישראל מקטרים לו\" (מלכים ב יח, ד), משמע שכתיתה בלבד מועילה לעבודה זרה!","\u0003אמרו לו:\u0004 וכי \u0003משם\u0004 יש \u0003ראיה?\u0004 ו\u0003הרי הוא אומר\u0004 לגבי אותו נחש: \u0003\"ויאמר ה' אל משה עשה לך שרף\"\u0004 (במדבר כא, ח), \u0003\"לך\"\u0004 — פירושו \u0003משלך,\u0004 ואם כן נחש הנחושת היה של משה, \u0003ו\u0004ישראל שעבדוהו לא היו יכולים לאוסרו בכך, לפי ש\u0003אין אדם אוסר דבר שאינו שלו.\u0004 ומסבירים: \u0003והתם\u0004 \u0005[ושם]\u0006 \u0003בדין הוא דכתותי\u0004 \u0005[שלכותתו]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003צריך,\u0004","\u0003אלא כיון דחזא\u0004 \u0005[שראה]\u0006 חזקיה \u0003דקא טעו\u0004 \u0005[שטועים]\u0006 \u0003ישראל בתריה\u0004 \u0005[אחריו]\u0006 לעשותו כעבודה זרה, \u0003עמד וכיתתו.\u0004","וממשיכה הברייתא, ועוד \u0003אמר להם\u0004 ר' יוסי, \u0003והלא כבר נאמר\u0004 על הפלשתים: \u0003\"ויעזבו שם את עצביהם\u0004 (אליליהם) \u0003וישאם דוד ואנשיו\"\u0004 (שמואל ב ה, כא), והכוונה שם שזרה אותם לרוח לאחר שטחנם! ומסבירים: \u0003ומאי משמע\u0004 \u0005[ומה המשמעות,\u0006 מהיכן נובע\u0005]\u0006 \u0003דהאי\u0004 \u0005[שזו]\u0006 המלה \u0003\"וישאם דוד\" לישנא דזרויי הוא\u0004 \u0005[לשון של זרייה\u0006 לרוח \u0005היא]?\u0006 \u0003כדמתרגם\u0004 \u0005[כמו שהיה מתרגם]\u0006 \u0003רב יוסף: \"תזרם ורוח תשאם\"\u0004 (ישעיהו מא, טז), \u0003ומתרגמינן\u0004 \u0005[ו\u0006כפי ש\u0005אנו מתרגמים\u0006 פסוק זה\u0005]:\u0006 \u0003תזרינון ורוח תטלטלינון\u0004 \u0005[תטלטלם],\u0006 משמע שלשון \"תשאם\" היא זריה לרוח!","\u0003אמרו לו\u0004 לר' יוסי: וכי \u0003משם\u0004 יש \u0003ראיה?\u0004 ו\u0003הרי הוא אומר\u0004 במקרא אחר על אותו ענין \u0003\"וישרפו באש\"\u0004 (דברי הימים א יד, יב), \u0003ומדלא כתיב\u0004 \u0005[וממה שלא נאמר]\u0006 בספר שמואל \u0003\"וישרפם וישאם\",\u0004 אלא רק \"וישאם\", \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003וישאם ממש,\u0004 שנטל אותם לעצמו.","ושואלים: \u0003מכל מקום קשו קראי אהדדי\u0004 \u0005[קשים המקראות זה על זה],\u0006 האם שרף אותם או לקח אותם!","ומשיבים: יש לפרש זאת \u0003כ\u0004דברי \u0003רב הונא,\u0004 ש\u0003רב הונא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בענין זה, \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק האחד: \u0003\"ויאמר דוד וישרפו באש\"\u0004 (דברי הימים א יד, יב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק האחר: \u0003\"וישאם\"!\u0004","והשיב: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003כאן\u0004 שאמר דוד לשורפם, מדובר \u0003קודם שבא איתי הגיתי\u0004 שהיה נכרי ויכול היה לבטל עבודה זרה. \u0003כאן\u0004 שנטלה דוד, מדובר \u0003לאחר שבא איתי הגיתי\u0004 וביטלה.","שכן מצינו כיוצא בזה, כשכבש דוד את רבת בני עמון, \u0003דכתיב\u0004 \u0005[שנאמר\u0006 שם\u0005]:\u0006 \u0003\"ויקח את עטרת מלכם מעל ראשו ומשקלה ככר זהב\u0004 ואבן יקרה ותהי על ראש דוד\" (שמואל ב יב, ל), ויש לתמוה: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 היה להשתמש בה? הרי \u0003איסורי הנאה נינהו\u0004 \u0005[הם]\u0006 ש\"מלכם\" היה שמו של אלהי העמונים! \u0003אמר רב נחמן: איתי הגיתי בא וביטלה.\u0004","אגב שהוזכר ענין זה שואלים: כיון ש\u0003משקלה ככר זהב, היכי מצי מנח לה\u0004 \u0005[איך היה יכול\u0006 דוד \u0005להניח אותה\u0006 על ראשו מרוב כובדה\u0005]?\u0006 \u0003אמר רב יהודה אמר רב: ראויה\u0004 ומתאימה היתה \u0003לנוח על ראש דוד,\u0004 אבל לא הניחה ממש. \u0003ר' יוסי בר' חנינא אמר: אבן שואבת היתה בה\u0004 בתוך העטרה הזו, \u0003דהות דרא לה\u0004 \u0005[שהיתה נושאת\u0006 ומרימה \u0005אותה].\u0006 \u0003ר' אלעזר אמר: אבן יקרה היתה בה ששוה ככר זהב,\u0004 ולא היה משקלה ככר זהב ממש.","מתוך כך מפרשים את הפסוק שאמר דוד: \u0003\"זאת היתה לי כי פקודיך נצרתי\"\u0004 (תהלים קיט, נו). ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 למה הוא מתכוון באותו \"זאת\"? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003בשכר שפקודיך נצרתי\u0004 — \u0003זאת\u0004 עטרה זו \u0003היתה לי לעדות\u0004 שראוי אני למלוכה. ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003עדותה? אמר ר' יהושע בן לוי: שהיה מניחה\u0004 את העטרה \u0003במקום תפילין והולמתו\u0004 והיתה מתאימה לו. ושואלים: \u0003והא בעי אנוחי\u0004 \u0005[והרי צריך להניח]\u0006 \u0003תפילין,\u0004 וכיצד שם שם עטרה? ומשיבים: \u0003אמר רב שמואל בר רב יצחק: מקום יש בראש שראוי להניח בו שתי תפילין\u0004 והניח שם גם תפילין וגם את העטרה.","ועוד בענין זה, נאמר על יואש: \u0003\"ויוציאו את בן המלך ויתנו עליו את הנזר ואת העדות\"\u0004 (דברי הימים ב כג, יא), ומסבירים: \u0003\"נזר\"\u0004 — \u0003זו כלילא\u0004 (העטרה), \u0003\"עדות\"\u0004 — \u0003אמר ר' יהודה אמר רב: עדות היא לבית דוד, שכל הראוי למלכות הולמתו\u0004 עטרה זו, \u0003וכל שאינו ראוי למלכות אין הולמתו\u0004 אין העטרה מתאימה לו.","וכן מפרשים מה שנאמר: \u0003\"ואדניה בן חגית מתנשא לאמר אני אמלך\"\u0004 (מלכים א א, ה), \u0003אמר רב יהודה אמר רב: שמתנשא\u0004 שהוא מנסה את העטרה \u0003להולמו ולא הולמתו.\u0004","נאמר: \u0003\"ויעש לו רכב ופרשים וחמשים איש רצים לפניו\"\u0004 (מלכים א א,ה). ושואלים: \u0003מאי רבותייהו\u0004 \u0005[מה הגדולה\u0006 שבכך\u0005]\u0006 שהיו לו חמישים איש שרצים לפניו? ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כולם נטולי טחול וחקוקי כפות הרגלים היו,\u0004 שעל ידי ניתוחים אלה היו רצים מהר ביותר, וחמישים אנשים כאלה הרצים לפניו יש בכך דבר מיוחד."],["\u0003שאל\u0004 החכם הנכרי \u0003פרוקלוס בן פלוספוס את רבן גמליאל בעכו,\u0004 בעת \u0003שהיה רוחץ במרחץ של אפרודיטי\u0004 (אלילה יוונית), שפסלה עמד שם, \u0003אמר ליה\u0004 \u0005[לו],\u0006 הרי \u0003כתוב בתורתכם: \"לא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח), \u0003מפני מה אתה רוחץ במרחץ של אפרודיטי?\u0004","\u0003אמר לו: אין משיבין במרחץ,\u0004 שאינו מקום שראוי לומר בו דברי תורה. \u0003וכשיצא, אמר לו: אני לא באתי בגבולה, היא באה בגבולי\u0004 שעוד מתחילה היה זה מרחץ ששימש את האנשים לרחצה, ורק אחר כך הכניסו לשם את הפסל. ועוד, \u0003אין\u0004 אנשים \u0003אומרים: נעשה מרחץ נוי לאפרודיטי, אלא אומר\u0004 אדם: \u0003נעשה אפרודיטי נוי למרחץ,\u0004 ואם כן אין הפסל עיקר אלא טפל למרחץ.","\u0003דבר אחר:\u0004 אף \u0003אם נותנים לך ממון הרבה, אי\u0004 \u0005[אין]\u0006 \u0003אתה נכנס ל\u0004מקום \u0003עבודה זרה שלך\u0004 כשאתה \u0003ערום ובעל קרי ומשתין בפניה,\u0004 ואילו עבודה זרה \u0003זו\u0004 של אפרודיטי \u0003עומדת על פי הביב וכל העם משתינין לפניה\u0004 אל תוך הביב, והרי \u0003לא נאמר\u0004 באיסורי עבודה זרה (ראה דברים פרק יב) \u0003אלא \"אלהיהם\",\u0004 לומר: \u0003את שנוהג\u0004 הגוי \u0003בו\u0004 בפסל בדרך כבוד \u0003משום אלוה\u0004 — \u0003אסור, את שאינו נוהג בו משום אלוה,\u0004 אלא נוהג בו זלזול — \u0003מותר,\u0004 ואף אפרודיטי בכלל זה.","מסופר במשנה שרבן גמליאל השיב מתחילה שאין משיבין במרחץ. ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[ואיך עשה כך]\u0006 לומר אפילו דבר תורה זה במרחץ? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: בכל מקום מותר להרהר\u0004 בדברי תורה, \u0003חוץ מבית המרחץ ומבית הכסא!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003בלשון חול אמר לו\u0004 ודבר זה מותר, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: דברים של חול מותר לאומרן\u0004 בבית המרחץ ובבית הכסא \u0003בלשון קדש, דברים של קדש אסור לאומרן\u0004 שם אפילו \u0003בלשון חול!\u0004","ומשיבים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בענין זה: \u0003כשיצא\u0004 מן המרחץ \u0003אמר לו: אין משיבין במרחץ.\u0004","\u0003אמר רב חמא בר יוסף ברבי,\u0004 כך \u0003אמר ר' אושעיא: תשובה גנובה השיבו רבן גמליאל לאותו הגמון\u0004 כלומר, אין זו תשובה אמיתית אלא תשובה של דחיה. והוסיף רב חמא בר יוסף, \u0003ואני אומר:\u0004 תשובה זו \u0003אינה גנובה.\u0004","ומסבירים: \u0003מה גנובתיה\u0004 \u0005[גנובתה,\u0006 העורמה שבה\u0005]?\u0006 \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003לו: זו עומדת על פי הביב וכל אדם משתין בפניה.\u0004 ויש לשאול: \u0003וכי משתין בפניה מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: פעור יוכיח, שמפערין לפניו\u0004 (שמטילים לפניו צואה) בכל יום ואינו בטל על ידי כך.","\u0003ואני אומר:\u0004 תשובה זו \u0003אינה גנובה,\u0004 כי \u0003זו,\u0004 בעל פעור, דרך \u0003עבודתה בכך\u0004 בפיעור, \u0003וזו\u0004 אפרודיטי \u0003אין עבודתה בכך.\u0004","\u0003אמר אביי\u0004 באופן אחר: \u0003גנובתה\u0004 (עורמתה) היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 רבן גמליאל לפרוקלוס: \u0003אני לא באתי בגבולה והיא באה בגבולי.\u0004 ובאמת, \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003בא בגבולה מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003עבודה זרה שיש לה מרחץ או גינה\u0004 — \u0003נהנין מהן\u0004 מהמרחץ או מהגינה, \u0003שלא בטובה\u0004 כלומר, כאשר אין צורך להחזיק טובה לעבודה זרה או לכמריה, \u0003ואין נהנין מהן בטובה\u0004 כשמחזיק להם על כך טובה.","\u0003ואני אומר:\u0004 תשובה זו \u0003אינה גנובה,\u0004 כי \u0003שלא בטובת רבן גמליאל\u0004 כלומר, כשרבן גמליאל נהנה, גם אם לא החזיק להם טובה — \u0003כבטובת אחרים דמי\u0004 \u0005[נחשב]\u0006 הדבר, כמו שאדם אחר נהנה ומחזיק להם טובה, משום שעצם העובדה שהוא בא לשם הרי זה כבוד ועזרה לעבודה זרה.","\u0003רב שימי בר חייא אמר: גנובתה\u0004 היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003לו: זו עומדת על הביב וכל אדם משתינין בפניה.\u0004 שכן יש לשאול: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003משתינין בפניה מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 עבודה זרה ש\u0003רק\u0004 (ירק) \u0003בפניה,\u0004 או \u0003השתין בפניה,\u0004 או \u0003גיררה\u0004 (גרר אותה בבוץ), \u0003ו\u0004כן אם \u0003זרק בה את הצואה\u0004 — \u0003הרי זו אינה בטילה\u0004 בכך.","\u0003ואני אומר:\u0004 תשובה זו \u0003אינה גנובה,\u0004 מדוע? \u0003התם\u0004 \u0005[שם]\u0006 אין זה נחשב ביטול, אלא \u0003לפי שעתא\u0004 \u0005[שעה]\u0006 \u0003הוא רתח עלה\u0004 \u0005[כועס עליה]\u0006 על העבודה זרה ונוהג בה זלזול, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מפייס לה\u0004 \u0005[אותה],\u0006 אבל \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003כל שעתא ושעתא\u0004 \u0005[שעה ושעה]\u0006 \u0003בזלזולה\u0004 היא \u0003קיימא\u0004 \u0005[עומדת].\u0006 כלומר, דבר קבוע הוא, והיא בטלה מכבודה על ידי כך.","\u0003רבה בר עולא אמר: גנובתה\u0004 של תשובת רבן גמליאל היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דקאמר ליה\u0004 \u0005[שאמר לו]:\u0006 \u0003אין אומרין נעשה מרחץ נוי לאפרודיטי אלא נעשה אפרודיטי נוי למרחץ; וכי אמר\u0004 \u0005[ו\u0006גם \u0005כאשר הוא אומר]\u0006 \u0003\"נעשה מרחץ לאפרודיטי נוי\" מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003האומר \"בית זה לעבודה זרה\",\u0004 או \u0003\"כוס זה לעבודה זרה\"\u0004 — \u0003לא אמר כלום, שאין\u0004 דין \u0003הקדש לעבודה זרה,\u0004 ואין דבר נאסר עד שיקריבוהו בפועל.","\u0003ואני אומר:\u0004 תשובה זו \u0003אינה גנובה, נהי דאיתסורי לא מיתסרא\u0004 \u0005[\u0006כי \u0005אמנם אינה נאסרת\u0006 בכך\u0005]\u0006 משום עבודה זרה ממש, אבל \u0003נוי\u0004 של עבודה זרה \u0003מיהא איכא\u0004 \u0005[מכל מקום הרי יש\u0006 בכך\u0005]\u0006 אם משתמשים במרחץ זה שנעשה לכבודה, ואסור. ולכן אמת השיבו, ולא תשובה גנובה."],["\u0003הגוים העובדים את ההרים ואת הגבעות\u0004 — \u0003הן\u0004 ההרים והגבעות עצמם \u0003מותרין\u0004 בהנאה, \u0003ו\u0004אולם \u0003מה שעליהן,\u0004 אם מצפים אותם בכסף וזהב לנוי — \u0003אסורין\u0004 בהנאה, \u0003שנאמר:\u0004 \"פסילי אלהיהם תשרפון באש \u0003לא תחמד כסף וזהב עליהם\"\u0004 (דברים ז, כה), כלומר כסף וזהב שנמצאים עליהם, על העבודה זרה, אסורים הם.","\u0003ר' יוסי הגלילי אומר:\u0004 ומנין שההרים והגבעות עצמם מותרים? שנאמר: \"אבד תאבדון את כל המקומות אשר עבדו שם הגוים את אלהיהם על ההרים הרמים ועל הגבעות ותחת כל עץ רענן\" (דברים יב, ב), ויש לדייק כי המצוה לאבד היא את \u0003אלהיהם\u0004 ש\u0003על ההרים\u0004 — \u0003ולא\u0004 ש\u0003ההרים\u0004 עצמם \u0003אלהיהם,\u0004 וכן \u0003אלהיהם\u0004 הם \u0003על הגבעות\u0004 — \u0003ולא הגבעות\u0004 עצמן \u0003אלהיהם.\u0004","ואם תשאל: הואיל וכך, יש לדייק גם לגבי עץ רענן — \"אלהיהם תחת כל עץ רענן\" ולא עץ רענן אלהיהם, \u0003ומפני מה אשירה אסורה?\u0004 \u0003מפני שיש בה תפיסת ידי אדם,\u0004 שהרי בני אדם נוטעים אותה, \u0003וכל שיש בה תפיסת ידי אדם\u0004 — \u0003אסור.\u0004","\u0003אמר ר' עקיבא, אני אובין\u0004 (אבין, אסביר) \u0003ואדון לפניך\u0004 פסוק זה באופן אחר לגמרי: לא הוזכרו הרים וגבעות ועץ רענן אלא כסימן, וכך אומר הכתוב: \u0003כל מקום שאתה מוצא הר גבוה וגבעה נשאה ועץ רענן\u0004 נטוע שם, \u0003דע שיש שם עבודה זרה.\u0004","ושואלים: \u0003ור' יוסי הגלילי היינו תנא קמא\u0004 \u0005[הרי זו\u0006 ממש שיטתו של \u0005התנא הראשון]\u0006 ששניהם מתירים את ההרים! \u0003אמר רמי בר חמא אמר ריש לקיש: צפוי הר כהר איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שבענין זה נחלקו, \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003צפוי הר אינו כהר\u0004 עצמו, \u0003ומיתסר\u0004 \u0005[ו\u0006הוא עצמו \u0005נאסר]\u0006 שלא כהר, \u0003ור' יוסי הגלילי סבר\u0004 \u0005[סבור]:\u0006 \u0003צפוי הר הרי הוא כהר\u0004 עצמו, ואף הוא מותר.","\u0003רב ששת אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003צפוי הר אינו כהר\u0004 לענין איסור."],["\u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003באילן שנטעו\u0004 סתם \u0003ולבסוף עבדו\u0004 כעבודה זרה \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003אילן שנטעו ולבסוף עבדו\u0004 — \u0003מותר,\u0004 שהרי הוא מחובר לקרקע, \u0003ור' יוסי הגלילי סבר: אילן שנטעו ולבסוף עבדו\u0004 — \u0003אסור.\u0004","\u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה בסוף\u0006 המשנה\u0005]:\u0006 \u0003מפני מה אשירה אסורה? מפני שיש בה תפיסת ידי אדם, וכל שיש בו תפיסת ידי אדם\u0004 — \u0003אסור.\u0004 ודי היה בחלק הראשון של הדברים: מפני שיש בה תפיסת ידי אדם, התוספת \u0003\"וכל שיש בו תפיסת אדם\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 באה? \u0003לאו לאתויי\u0004 \u0005[האם לא להביא,\u0006 לרבות\u0005]\u0006 \u0003אילן שנטעו ולבסוף עבדו?\u0004","ומעירים, \u0003ואף ר' יוסי בר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003אילן שנטעו ולבסוף עבדו\u0004 — \u0003אסור. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי בר' יהודה אומר, מתוך שנאמר: \"אלהיהם על ההרים\"\u0004 (דברים יב, ב), והרי זה בא ללמד — \u0003ולא ההרים אלהיהם,\u0004 וכן \u0003\"אלהיהם על הגבעות\"\u0004 (דברים יב, ב) — \u0003ולא גבעות אלהיהם, שומע אני\u0004 גם: \u0003\"תחת כל עץ רענן אלהיהם\"\u0004 (דברים יב, ב) — \u0003ולא\u0004 עץ \u0003רענן\u0004 עצמו \u0003אלהיהם,\u0004 ועץ שעבדוהו אינו נאסר?","לכן \u0003תלמוד לומר: \"ואשריהם תשרפון באש\"\u0004 (דברים יב, ג), שאף אילן הנעבד לעבודה זרה (\"אשרה\") אסור בהנאה.","ושואלים: \u0003אלא\u0004 לפי זה, \u0003\"תחת כל עץ רענן\u0004 אלהיהם\" \u0003למה לי?\u0004 ומשיבים: \u0003ההוא ל\u0004דברי \u0003ר' עקיבא\u0004 במשנה \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ש\u0003אמר ר' עקיבא, אני אובין ואדון לפניך:\u0004 כוונת הפסוק אינה אלא לתת סימן, לומר כי \u0003כל מקום שאתה מוצא הר גבוה וגבעה נשאה ועץ רענן, דע שיש שם עבודה זרה.\u0004","ושואלים מצד אחר: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 הסבורים שאילן שנטעו ואחר כך עבדו אינו נאסר, \u0003האי\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \u0003\"ואשריהם תשרפון באש\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005לו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריכים\u0006 הם \u0005אותו]\u0006 \u0003לאילן שנטעו מתחילה לכך\u0004 לשם עבודה זרה, שהוא נאסר בהנאה וחייב שריפה.","ושואלים: \u0003ור' יוסי בר' יהודה נמי מיבעי ליה להכי\u0004 \u0005[גם כן צריך אותו\u0006 את הכתוב הזה \u0005לכך]!\u0006 ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן],\u0006 גם הוא לומד מכתוב זה איסורו של אילן שניטע מתחילה לעבודה זרה. ושואלים: \u0003אלא\u0004 לפי זה \u0003אילן שנטעו ולבסוף עבדו מנא ליה\u0004 \u0005[מנין לו]\u0006 שאסור? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 דבר זה \u0003מ\u0004מה שכתוב: \u0003\"ואשריהם תגדעון\"\u0004 (דברים ז, ה), \u0003איזהו עץ שגידועו\u0004 (מה שגודעים וקוצצים אותו) \u0003אסור\u0004 \u0003ו\u0004אולם \u0003עיקרו\u0004 (שורשו, גזעו) \u0003מותר? הוי אומר: אילן שנטעו ולבסוף עבדו,\u0004 שמה שגדל בו קודם שנעבד — אינו נאסר.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 בברייתא אין ר' יוסי בר' יהודה לומד את דינו מכתוב זה, אלא מהכתוב: \u0003\"ואשריהם תשרפון באש\" קא נסיב לה תלמודא\u0004 \u0005[הביא אותו\u0006 כ\u0005לימוד]!\u0006","ומשיבים: בסגנון של \u0003\"אילו לא נאמר\" קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין את דבריו: \u0003אילו לא נאמר \"תשרפון באש\", הייתי אומר: \"אשריהם תגדעון\"\u0004 מדבר \u0003באילן שנטעו מתחילה לכך, השתא דכתיב\u0004 \u0005[עכשיו שנאמר]:\u0006 \u0003\"ואשריהם תשרפון באש\", אייתר ליה\u0004 \u0005[נעשה מיותר לו]\u0006 \u0003\"ואשריהם תגדעון\",\u0004 ללמוד ממנו \u0003לאילן שנטעו ולבסוף עבדו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 הסבורים שאילן שנטעו ואחר כך עבדו אינו נאסר, \u0003האי\u0004 \u0005[אותו\u0006 פסוק\u0005]\u0006 \u0003\"ואשריהם תגדעון\" מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו]?\u0006 ומשיבים: הם מפרשים אותו \u0003לכ\u0004 דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: גידועי\u0004 כלומר, המצוה של גדיעת \u0003עבודה זרה קודמין לכיבוש ארץ ישראל\u0004 כולה, \u0003כיבוש ארץ ישראל קודם לביעור\u0004 מוחלט של ה\u0003עבודה זרה.\u0004","ומעירים: והוא כמו ברייתא \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 על הפסוק \"ונתצתם את מזבחותם ושברתם את מזבחותם ואשריהם תשרפון באש\" (דברים יב, ג): \u0003\"ונתצתם את מזבחתם\" והנח\u0004 כמות שהם, \u0003\"ושברתם את מצבתם\" והנח.\u0004","ותוהים: \u0003והנח סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 שיניחם ולא יבערם? הלוא \u0003שריפה בעי\u0004 \u0005[צריכים]\u0006 כמו שנאמר באשריהם שבפסוק זה! \u0003אמר רב הונא:\u0004 אין הכוונה שיניחם כך לעולם, אלא: הנח, \u0003רדוף, ואחר כך שרוף.\u0004 כלומר, קודם ינתצום וישברום, לאחר מכן יכבשו את הארץ, ואחר כך יבערום לגמרי. והוא הדין לאילן שנטעו ואחר עבדו, שנאמר בו \"ואשריהם תגדעון\".","ושואלים: \u0003ור' יוסי בר' יהודה, האי סברא\u0004 \u0005[סברה זו]\u0006 שמשבר ומניח ואחר כך מבער, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\"אבד תאבדון\"\u0004 (דברים יב, ב) שהוא דורש את כפל המלים בשני שלבים: \u0003אבד\u0004 את העבודה הזרה, \u0003ואחר כך תאבדון\u0004 לחלוטין את מה שנשאר.","ומן הצד השני, \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם למדים מכאן? \u0003הא מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה נצרך לו]\u0006 \u0003לעוקר עבודה זרה, שצריך לשרש אחריה\u0004 ולאבד כל זכר ממנה.","ושואלים: \u0003ור' יוסי בר' יהודה,\u0004 הציווי \u0003לשרש אחריה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו הדבר]\u0006 \u0003מ\"ואבדתם את שמם מן המקום ההוא\"\u0004 (דברים יב, ב).","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם למדים מכתוב זה? \u0003ההוא\u0004 אותו פסוק נצרך לענין \u0003לכנות לה שם\u0004 שצריך לשנות את שמה של העבודה זרה, ולהשתמש בשם של גנאי. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מנין לעוקר עבודה זרה שצריך לשרש אחריה? תלמוד לומר: \"ואבדתם את שמם\".\u0004"],["\u0003אמר לו ר' עקיבא, והלא כבר נאמר: \"אבד תאבדון\u0004 את כל המקומות אשר עבדו שם הגוים... את אלוהיהם\" (דברים יב, ב), שיש לאבד את מקומות העבודה זרה עצמה. \u0003אם כן, מה תלמוד לומר\u0004 (מלמדנו) הפסוק שאחריו \u0003\"ואבדתם את שמם מן המקום ההוא\"\u0004 (דברים יב, ג)? כוונתו \u0003לכנות לה שם\u0004 אחר, שיאבד שמה של עבודה זרה מן העולם.","\u0003יכול\u0004 יכנה לה שם \u0003לשבח?\u0004 ותמהים: \u0003לשבח סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 להציע ליתן למקום דבר כזה שם משובח יותר? \u0003אלא,\u0004 כך היתה השאלה, \u0003יכול\u0004 יכנה לה שם שהוא \u0003לא לשבח ולא לגנאי? תלמוד לומר: \"שקץ תשקצנו ותעב תתעבנו כי חרם הוא\"\u0004 (דברים ז, כו),","\u0003הא כיצד? היו קורין אותה\u0004 למקום הזה \u0003בית גליא\u0004 — \u0003קורין אותה \"בית כריא\",\u0004 קראו לה \u0003עין כל\u0004 — קוראים אותה מעתה \u0003\"עין קוץ\".\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה שונה המשניות לפני]\u0006 \u0003רב ששת: הגוים העובדים את ההרים ואת הגבעות\u0004 — \u0003הן\u0004 ההרים והגבעות עצמם \u0003מותרין ו\u0004אילו \u0003עובדיהן\u0004 נידונים למיתה \u0003בסייף, ו\u0004העובדים \u0003את הזרעים ואת הירקות\u0004 — \u0003הן\u0004 הזרעים והירקות \u0003אסורין, ועובדיהן\u0004 נידונים \u0003בסייף.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לתנא: מי ש\u0003אמר לך, מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יוסי בר יהודה היא,\u0004 ש\u0003אמר: אילן שנטעו ולבסוף עבדו\u0004 — \u0003אסור.\u0004","ושואלים: \u0003ולוקמה\u0004 \u0005[ושיעמיד\u0006 את הדבר\u0005]\u0006 \u0003באילן שנטעו מתחלה לכך\u0004 (לשם עבודה זרה) \u0003ו\u0004יפרש שהוא אף כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' יוסי בר' יהודה! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יכול לעלות על דעתך\u0006 כך\u0005],\u0006 \u0003דקתני דומיא\u0004 \u0005[ששנה\u0006 דין זה של זרעים וירקות \u0005בדומה]\u0006 ל\u0003הר\u0004 ששנה באותה ברייתא, \u0003מה הר\u0004 הוא דבר \u0003שלא נטעו מתחלה לכך,\u0004 \u0003אף האי נמי\u0004 \u0005[זה גם כן]\u0006 הצומח — \u0003שלא נטעו מתחלה לכך,\u0004 והוא אסור דווקא לשיטת ר' יוסי בר' יהודה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה: \u0003אבני הר שנדלדלו\u0004 ממנו, ואינן מחוברות עוד, והשתחוו להן — נחלקו בכך \u0003בני ר' חייא\u0004 (חזקיה ויהודה) \u0003ור' יוחנן, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אבנים אלה \u0003אסורות, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מותרות.\u0004 ומסבירים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאמר]\u0006 \u0003מותרות?\u0004 לדעתו אבנים אלה נידונות \u0003כהר\u0004 עצמו, \u0003מה הר\u0004 הוא דבר \u0003שאין בו תפיסת ידי אדם ומותר, אף הני\u0004 \u0005[אלה]\u0006 הם דברים \u0003שאין בהן תפיסת ידי אדם ומותרין.\u0004","ומקשים: \u0003מה להר שכן מחובר!\u0004 ומשיבים: \u0003בהמה תוכיח\u0004 שאינה בכלל מחובר, ואם משתחווה לה עדיין היא מותרת.","ודוחים: \u0003מה לבהמה\u0004 שמותרת, \u0003שכן\u0004 היא \u0003בעלת חיים,\u0004 אבל אבנים, יש לומר שהן נאסרות בהשתחוויה בלבד! ומשיבים: \u0003הר יוכיח,\u0004 שאינו בעל חיים, ומותר.","\u0003וחזר הדין,\u0004 שהרי אפשר שוב לומר: מה להר שכן מחובר, ונמצא הדיון סובב (\"חוזר\"). ולכן יש ללמוד באופן כזה: הר ובהמה, \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 לא זה דומה לזה ולא זה דומה לזה, מה \u0003הצד השוה שבהן\u0004 — \u0003שאין בהן תפיסת ידי אדם ומותר, אף כל שאין בהן תפיסת ידי אדם ומותר.\u0004","ומקשים: \u0003מה להצד השוה שבהן שכן לא נשתנו מברייתן\u0004 שנשארו כמות שנבראו, מה שאין כן באבני ההר שנדלדלו!","\u0003אלא אתיא\u0004 \u0005[נלמד\u0006 את הדבר\u0005]\u0006 \u0003מבהמה בעלת מום\u0004 שנשתנתה מברייתה, שאינה נאסרת בהשתחוויה, \u0003ומהר.\u0004","\u0003ואי נמי\u0004 \u0005[או גם כן],\u0006 \u0003מבהמה תמה\u0004 (שלימה) \u0003ומאילן יבש\u0004 שנשתנה מברייתו, שמאחר שאין בהם תפיסת ידי אדם — מותרים.","\u0003ומאן דאסר\u0004 \u0005[ומי שאוסר],\u0006 סברתו היא: \u0003להכי כתיב\u0004 \u0005[לכך נאמר]\u0006 בעבודה זרה \u0003\"שקץ תשקצנו ותעב תתעבנו\"\u0004 (דברים ז, כו), לומר \u0003דאף על גב דאתיא מדינא להיתרא\u0004 \u0005[שאף על פי שבאה,\u0006 שעולה, \u0005מן הדין להיתר],\u0006 \u0003לא תתיא\u0004 \u0005[תביא,\u0006 תלמד\u0005]\u0006 כן, אלא עליך לדון לאיסור.","ומעירים: לא נאמר מי היו המתירים והאוסרים במחלוקת זו, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003בני ר' חייא דשרו\u0004 \u0005[\u0006הם \u0005שהתירו],\u0006 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003חזקיה,\u0004 בנו של ר' חייא: \u0003זקף ביצה להשתחוות לה, מהו\u0004 דינה?","ומסבירים: \u0003קא סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 שמדובר כאן כאשר זקף ביצה זו \u0003להשתחוות לה ו\u0004גם \u0003השתחוה לה, ו\u0004לפיכך יש להבין כי \u0003קא מיבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 שאלה זו: \u0003האי זקיפתה\u0004 \u0005[אותה זקיפה],\u0006 \u0003אי הוי\u0004 \u0005[האם הוא\u0006 נחשב\u0005]\u0006 כ\u0003מעשה\u0004 ויש בה תפיסת יד אדם, \u0003אי לא הוי\u0004 \u0005[או לא\u0006 נחשב\u0005]\u0006 כ\u0003מעשה,\u0004 ונדייק מכאן: \u0003אבל\u0004 אם \u0003לא זקף\u0004 את הביצה כלל — \u0003לא מיתסרא\u0004 \u0005[אינה נאסרת],\u0006 אף על פי שהשתחווה לה; \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בני ר' חייא דשרו\u0004 \u0005[\u0006הם \u0005שהתירו]\u0006 דבר שלא היתה בו תפיסת יד אדם.","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך: בני ר' חייא\u0004 הם \u0003דאסרי\u0004 \u0005[שאסרו],\u0006 ולדעתם במקרה ש\u0003השתחוה לה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא זקפה אסורה, והכא\u0004 \u0005[וכאן]\u0006 בשאלתו של חזקיה \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003כגון שזקף ביצה להשתחוות לה, ולא השתחוה לה.\u0004","ומקשים: \u0003ולמאן\u0004 \u0005[\u0006ולדעת \u0005מי]?\u0006 \u0003אי למאן דאמר\u0004 \u0005[אם\u0006 לדעת \u0005מי שאומר]:\u0006 \u0003עבודה זרה של ישראל אסורה מיד\u0004 כשייחד אותה לכך, אם כן ביצה זו \u0003אסורה,\u0004 \u0003אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שעבודה זרה של ישראל אינה נאסרת \u0003עד שתיעבד\u0004 — \u0003הא לא פלחה\u0004 \u0005[הרי לא עבד אותה]\u0006 ומדוע תיאסר?","ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 השאלה אלא לשיטת הסבור שאינה נאסרת עד שתיעבד, ובכל זאת יש מקום לאסור, \u0003כגון שזקף ביצה להשתחוות לה ולא השתחוה לה, ובא גוי והשתחוה לה;\u0004 ומקרה זה הוא","\u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: ישראל שזקף לבינה להשתחוות לה ובא גוי והשתחוה לה\u0004 — לבינה זו \u0003אסורה,\u0004 שגילוי דעתו של היהודי ומעשהו של הגוי — מצטרפים לאוסרה. \u0003ו\u0004אף שהדברים דומים, מכל מקום חזקיה לגבי ביצה \u0003קא מיבעיא ליה\u0004 \u0005[נשאלה לו\u0006 כך\u0005]:\u0006 האם נאמר כי \u0003לבינה הוא דמינכרא\u0004 \u0005[שניכרת]\u0006 \u0003זקיפתה,\u0004 לכן נחשב הדבר כגילוי דעת לעבודה זרה, \u0003אבל ביצה\u0004 שזוקף אותה \u0003לא\u0004 ניכר הדבר, ולא ייחשב הדבר כגילוי דעת לעבודה זרה, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006 שאלה זו נשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה. ואף לא נפתרה השאלה האם בני ר' חייא התירו או אסרו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: המשתחוה להר,\u0004 שכאמור במשנה אינו נאסר על האדם בהנאה, \u0003אבניו\u0004 של הר זה \u0003מהו למזבח?\u0004 האם מותרים הם לשימוש?"],["האם \u0003יש\u0004 דין \u0003נעבד\u0004 לעבודה זרה \u0003ב\u0004דבר שהוא \u0003מחובר אצל גבוה\u0004 (לענין הקרבת קרבן) כמו בעל חיים שנעבד, שהוא נאסר לקרבן, \u0003או אין\u0004 דין \u0003נעבד במחובר\u0004 \u0003אצל גבוה,\u0004 כפי שאינו נאסר בהנאה להדיוט?","וגם \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ותחליט ש\u0003יש\u0004 דין \u0003נעבד במחובר אצל גבוה,\u0004 עדיין יש לשאול: האם \u0003מכשירי קרבן\u0004 כמו המזבח, \u0003כקרבן דמו\u0004 \u0005[נחשבים]\u0006 ונפסלים בנעבד \u0003או לא?\u0004","\u0003אמר רבא, קל וחומר\u0004 הוא: \u0003ומה אתנן שמותר\u0004 גם כשהוא \u0003בתלוש להדיוט\u0004 — בכל זאת \u0003אסור\u0004 גם אם היה \u0003במחובר לגבוה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תביא אתנן זונה ומחיר כלב\u0004 בית ה' אלהיך\" (דברים כג, יט), והאיסור נאמר בלשון כללית, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה \u0003תלוש ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003במחובר,\u0004 אם כך, \u0003נעבד שאסור בתלוש\u0004 אפילו \u0003להדיוט\u0004 — \u0003אינו דין שאסור במחובר לגבוה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: או חילוף,\u0004 הואיל ואין הדברים מפורשים בכתוב, שמא נניח הנחה הפוכה, שנעבד במחובר נאסר לגבוה, ונדון להיפך: \u0003ומה נעבד שאסור בתלוש אצל הדיוט\u0004 — \u0003מותר במחובר לגבוה, שנאמר: \"אלהיהם על ההרים\"\u0004 (דברים יב, ב) ולמדים מכאן — \u0003ולא ההרים אלהיהם,\u0004 ונאמר בלשון כללית \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003להדיוט ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לגבוה\u0004 ששניהם מותרים, אם כן, \u0003אתנן שמותר בתלוש להדיוט\u0004 — \u0003אינו דין שמותר במחובר לגבוה?\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 מה שנאמר לגבי אתנן \u0003\"בית ה' אלהיך\",\u0004 ויש בכלל זה גם מחובר שנאסר לגבוה — \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו\u0006 הדבר \u0005כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"בית ה' אלהיך\"\u0004 — \u0003פרט לפרה שאינה באה לבית,\u0004 שנעשית מחוץ למקדש, ואינה נפסלת באתנן, \u0003דברי ר' אליעזר. וחכמים אומרים: לרבות את הריקועים\u0004 של זהב, שמקשטים בהם את בית קודש הקודשים, לומר שאסורים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא קאמינא לחומרא ואת אמרת לקולא\u0004 \u0005[אני אומר\u0006 את הקל וחומר \u0005להחמיר ואתה אומר להקל],\u0006 כשיש מקום שאפשר \u0003קולא וחומרא\u0004 \u0005[להקל או להחמיר]\u0006 בו — \u0003לחומרא פרכינן\u0004 \u0005[להחמיר אנו דנים]\u0006 ולא להקל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: ו\u0004כלל הוא ש\u0003כל היכא דאיכא קולא וחומרא, לקולא לא פרכינן\u0004 \u0005[וכל מקום שיש\u0006 מקום \u0005להקל ולהחמיר, להקל אין אנו דנים]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003הזאה\u0004 של מי חטאת על טמא מת, לשם אכילת קרבן \u0003פסח, דפליגי\u0004 \u0005[שנחלקו\u0006 בכך\u0005]\u0006 \u0003ר' אליעזר ור' עקיבא,\u0004 האם מזים על הטמא אף בשבת, ש\u0003ר' אליעזר סבר לחומרא\u0004 \u0005[סבור להחמיר]\u0006 \u0003וקא מחייב ליה לגברא\u0004 \u0005[והוא מחייב את האיש]\u0006 להיטהר ולהביא קרבן, \u0003ור' עקיבא\u0004 דן \u0003לקולא ופטר\u0004 \u0005[להקל ופוטר],\u0006 \u0003וקא פריך\u0004 \u0005[ודן]\u0006 \u0003ר' עקיבא\u0004 קל וחומר \u0003לקולא\u0004 \u0005[להקל]!\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו],\u0006 שאמר ר' אליעזר: אם שחיטה שהיא אסורה מן התורה בשבת, הותרה לצורך שחיטת הפסח, הזאה שלא נאסרה אלא על ידי חכמים משום שבות — אינו דין שתהא מותרת? ועל כך \u0003השיב ר' עקיבא: או חילוף,\u0004 תהפוך את הקל וחומר ותאמר כך: \u0003ומה הזאה שהיא משום שבות\u0004 (מדברי חכמים) — \u0003אינה דוחה\u0004 את \u0003השבת, שחיטה שהיא דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003לא כל שכן\u0004 שלא תדחה?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לא התכוון ר' עקיבא ללמוד להקל על ידי אותו קל וחומר, אלא \u0003ר' אליעזר\u0004 הוא \u0003גמריה\u0004 \u0005[שלימד אותו]\u0006 הלכה זו \u0003ואייקר ליה תלמודא\u0004 \u0005[ונשתכח לו תלמודו],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' עקיבא לאדכוריה\u0004 \u0005[להזכירו]\u0006 בדרך של משא ומתן, שלא רצה לומר לו במפורש ששכח. ומעירים: \u0003והיינו דאמר ליה\u0004 \u0005[וזהו שאמר לו]\u0006 בסוף אותו דיון: \u0003רבי, אל תכפירני בשעת הדין, כך מקובל אני ממך: הזאה שבות\u0004 היא, \u0003ו\u0004בכל זאת \u0003אינה דוחה את השבת.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: המשתחוה לקמת חטים, מהו ל\u0004עשות מהן \u0003מנחות?\u0004 האם נאמר שכיון שהקמה הפכה אחר כך להיות לחיטה \u0003יש שינוי בנעבד,\u0004 וכיון שנשתנה הדבר מברייתו בטל ממנו איסור נעבד, \u0003או אין שינוי בנעבד,\u0004 שכיון שנעבד נאסר, הרי גם לאחר ששינוהו עדיין איסורו חל עליו?","\u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, ששנינו: \u0003כל האסורין לגבי מזבח\u0004 — \u0003ולדותיהן מותרים, ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 \u0003ר' אליעזר אוסר.\u0004 ולכאורה מחלוקת זו היא בענין שינוי, האם אומרים שהעובר לאחר שנולד נשתנה ממה שהיה ומותר, או שהוא עומד באיסורו.","ודוחים: \u0003ולאו אתמר עלה\u0004 \u0005[והאם לא נאמר על כך],\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה: מחלוקת\u0004 זו ביחס לוולדות הנאסרים לגבי מזבח, היא כגון \u0003שנרבעו\u0004 הבהמות ונאסרו \u0003ולבסוף\u0004 לאחר מכן \u0003עיברו,\u0004"],["\u0003אבל עיברו ולבסוף נרבעו\u0004 — \u0003דברי הכל אסורין. והכא נמי\u0004 \u0005[וכאן גם כן]\u0006 \u0003כעיברו ולבסוף נרבעו דמי\u0004 \u0005[נחשב]\u0006 הדבר, שהרי גוף החיטים היה קיים בשעה שעבדו את הקמה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמכאן רוצים לפתור את שאלתו של רמי בר חמא, שעל אותה משנה נאמר בשם רב נחמן: \u0003מחלוקת\u0004 ר' אליעזר וחכמים האם הוולדות אסורים — \u0003כשנרבעו ולבסוף עיברו, אבל עיברו ולבסוף נרבעו\u0004 — \u0003דברי הכל אסור; והני נמי\u0004 \u0005[ואלה גם כן],\u0006 חיטים שהשתחווה להם כשהיו בקמה, \u0003כי\u0004 \u0005[כמו]\u0006 \u0003עיברו ולבסוף נרבעו דמי\u0004 \u0005[נחשבות],\u0006 ואסורות למנחה.","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 העובר \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 היה \u0003בהמה והשתא\u0004 \u0005[ועכשיו,\u0006 לאחר שנולד\u0005]\u0006 הוא \u0003בהמה,\u0004 אלא \u0003דשא הוא דאחיזא באנפה\u0004 \u0005[דלת היא שאוחזת\u0006 וסוגרת \u0005בפניו],\u0006 ולא היה יכול לצאת מן הרחם, ולכן הלידה אינה נחשבת לשינוי גמור. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003מעיקרא חיטי והשתא קמחא\u0004 \u0005[מתחילה\u0006 היו אלה \u0005חיטים ועכשיו\u0006 זהו \u0005קמח],\u0006 ונעשה שינוי ניכר בצורה, ויש מקום לומר שיהא מותר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ריש לקיש: המשתחוה לדקל, לולבו מהו\u0004 דינו \u0003ל\u0004ענין \u0003מצוה\u0004 של ארבעה מינים בחג הסוכות?","ומפרטים: \u0003באילן שנטעו מתחלה לכך\u0004 לשם עבודה זרה \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שהרי \u0003אפילו להדיוט נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 לולב זה בהנאה, וכל שכן לעשות בו שימוש של מצוה. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003באילן שנטעו\u0004 תחילה סתם \u0003ולבסוף עבדו.\u0004","ועוד, \u0003ואליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003ר' יוסי בר יהודה לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שהרי לדעתו \u0003אפילו להדיוט נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 במקרה כזה, \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003אליבא דרבנן\u0004 \u0005[לדעת חכמים],\u0006 שבמקרה כגון זה הם מתירים להדיוט, והשאלה היא: \u0003לענין מצוה מאי\u0004 \u0005[מה]\u0006 דינו? והסבר השאלה, \u0003מי מאיס\u0004 \u0005[האם\u0006 נחשב הוא \u0005כמאוס]\u0006 \u0003כלפי גבוה או לא?\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: באשירה שביטלה קמבעיא ליה\u0004 \u0005[נשאלה לו\u0006 השאלה\u0005]\u0006 לריש לקיש, והשאלה היתה: אם \u0003יש דחוי אצל מצו‍ת או אין דחוי אצל מצו‍ת?\u0004 כלומר, האם אנו אומרים שכיון שדבר נדחה מן האפשרות לקיים בו מצוה הריהו נדחה לעולם, או כיון שעכשיו הוא ראוי אין מתחשבים במה שנדחה בעבר?","ושואלים: \u0003תפשוט ליה מדתנן\u0004 \u0005[תפתור\u0006 את הבעיה \u0005הזו מ\u0006מה \u0005ששנינו\u0006 במשנה\u0005]\u0006 ביחס לדם שחיטה שמצוה לכסותו: אם \u0003כיסהו\u0004 כדין \u0003ו\u0004אחר כך \u0003נתגלה\u0004 הדם — \u0003פטור מלכסות\u0004 שוב, שכבר קיים את המצוה, אבל אם \u0003כיסהו הרוח\u0004 בתחילה — \u0003חייב לכסות. ואמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שאם כסהו הרוח חייב לכסות, \u0003אלא\u0004 במקרה \u0003שחזר ונתגלה, אבל לא חזר ונתגלה\u0004 — \u0003פטור מלכסות.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים \u0005בכך]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חזר ונתגלה מאי הוי\u0004 \u0005[מה בכך]?\u0006 הרי \u0003הואיל ואידחי אידחי\u0004 \u0005[ונדחה\u0006 מצורך כיסוי \u0005נדחה]!\u0006","\u0003ואמר רב פפא, זאת אומרת: אין דיחוי אצל מצו‍ת,\u0004 ואם כן, יש לנו פתרון לשאלה הזו, שאין דיחוי במצוות!","ומשיבים: לגבי פתרונו של \u0003רב פפא גופיה איבעיא ליה\u0004 \u0005[עצמו\u0006 הוא זה ש\u0005היה מסופק לו\u0006 לשואל\u0005],\u0006 ושאלתו היתה: האם \u0003מפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 הדבר כמו \u0003לרב פפא\u0004 ש\u0003אין דיחוי אצל מצו‍ת, לא שנא לקולא ולא שנא לחומרא\u0004 \u0005[אינו שונה\u0006 אם יש בכך \u0005להקל ולא שונה\u0006 אם יש בכך \u0005להחמיר],\u0006","\u0003או דלמא ספוקי מספקא ליה\u0004 \u0005[שמא ספק הוא לו\u0006 דבר זה\u0005],\u0006 \u0003ולחומרא אמרינן\u0004 \u0005[ולהחמיר אנו אומרים\u0006 כן\u0005]\u0006 לחייבו בכיסוי הדם, אבל \u0003לקולא לא אמרינן\u0004 \u0005[להקל\u0006 ולהתיר ליטול לולב של אשירה שביטלה \u0005אין אנו אומרים]?\u0006 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה זו: \u0003המשתחוה לבהמה,\u0004 שאינה נאסרת להדיוט מחמת השתחוואה זו, \u0003צמרה\u0004 של אותה בהמה \u0003מהו\u0004 \u0003ל\u0004ענין \u0003תכלת?\u0004","ושואלים: \u0003תכלת דמאי\u0004 \u0005[של מה],\u0006 לצורך מה? \u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003תכלת לכהנים\u0004 לבגדי כהונה — \u0003היינו בעיא\u0004 \u0005[\u0006הרי \u0005זוהי הבעיה]\u0006 של \u0003רמי בר חמא\u0004 לעיל, האם יש שינוי בנעבד לצורך גבוה! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003תכלת\u0004 עבור \u0003ציצית\u0004 — \u0003היינו בעיא\u0004 \u0005[זוהי הבעיה]\u0006 של \u0003ריש לקיש,\u0004 ששאל לגבי לולב של מצוה!","ומשיבים: \u0003אין הכי נמי דלא הוה למיבעי ליה\u0004 \u0005[אכן כך הוא גם כן, שלא היה\u0006 צריך \u0005לשאול\u0006 דבר \u0005זה],\u0006 \u0003והאי דקא בעי ליה הא\u0004 \u0005[וזה ששאל אותו],\u0006 הרי זה \u0003משום דאיכא מילי אחרנייתא\u0004 \u0005[שיש דברים אחרים]\u0006 שרוצה לשאול אגב כך. וכך היתה השאלה בשלימותה: \u0003צמרה מהו לתכלת? קרניה מהו לחצוצרות? שוקיה מהו ל\u0004עשות מהם \u0003חלילין? בני מעיה מהו לפארות\u0004 (מיתרים של כינור)?","ומעירים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי\u0006 שיטתו \u0005של מי שאומר]\u0006 ש\u0003עיקר שירה\u0004 שמצווים לשיר במקדש כשמקריבים קרבנות הוא \u0003בכלי, לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ש\u0003ודאי אסיר\u0004 \u0005[אסור],\u0006 שהרי הכלים הללו שעושים מאותה בהמה הם עיקר העבודה, והרי זה בכלל מכשירי קרבן, שדינם כקרבן שהנעבד פסול בו.","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לפי\u0006 שיטתו \u0005של מי שאומר]\u0006 \u0003עיקר שירה\u0004 ומצוותה הוא \u0003בפה,\u0004 האם הכלים \u0003בסומי קלא בעלמא הוא\u0004 \u0005[המתקת קול בלבד היא]\u0006 בתור ליווי לזמרה בפה, \u0003ו\u0004לכן יש לומר מצד אחד \u0003מייתינן\u0004 \u0005[\u0006ש\u0005מביאים אנו]\u0006 ממה שנעבד לצורך זה, שאינו עיקר מצוה ואינו מעכב את הקרבן, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו הכי אסיר\u0004 \u0005[כך אסור]\u0006 שהרי זה לצורך קרבן, ומגונה הדבר? גם שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה: המשתחוה למעין, מימיו,\u0004 שאינם נאסרים בהנאה שהרי מחוברים הם, \u0003מהו לנסכים\u0004 על גבי המזבח? ושואלים: \u0003מאי קא מיבעיא ליה\u0004 \u0005[מה\u0006 הבעיה \u0005שנשאלה לו]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 האם \u0003לבבואה\u0004 לדמות שהוא רואה במים \u0003קא סגיד\u0004 \u0005[הוא משתחווה]\u0006 ומותרים הם, \u0003או דלמא למיא קא סגיד\u0004 \u0005[שמא למים\u0006 עצמם \u0005הוא משתחווה],\u0006 ונאסרו לגבוה — \u0003ו\u0004אם כן \u0003תיבעי ליה\u0004 \u0005[תישאל לו\u0006 השאלה\u0005]\u0006 במשתחווה למים שב\u0003ספל\u0004 שמימיו תלושים, ו\u0003ל\u0004גבי \u0003הדיוט,\u0004 האם נאסרים עליו המים שבספל בהנאה!","ודוחים: \u0003לעולם\u0004 יש לומר כי \u0003למיא קא סגיד\u0004 \u0005[למים\u0006 עצמם \u0005הוא משתחווה],\u0006 \u0003והכי קמבעיא ליה\u0004 \u0005[וכך נשאלה לו\u0006 השאלה\u0005]:\u0006 \u0003למיא דקמיה קא סגיד\u0004 \u0005[\u0006האם \u0005למים שלפניו הוא משתחווה],\u0006 \u0003וקמאי קמאי אזדו\u0004 \u0005[וראשונים ראשונים הלכו],\u0006 ואם כן, שוב אין במעין מים אסורים, \u0003או דלמא לדברונא דמיא קא סגיד\u0004 \u0005[שמא לעיקר המים הוא משתחווה],\u0006 וממילא כל המים הנובעים ממנו נאסרים?","ושואלים: \u0003ומי מיתסרי\u0004 \u0005[והאם\u0006 הם \u0005נאסרים]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: מים של רבים אין נאסרין\u0004 משום עבודה זרה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו אלא במים \u0003דקא נבעי מארעא\u0004 \u0005[שנובעים מן הקרקע\u0006 שלו\u0005],\u0006 ומשום כך שלו הם, ויכול הוא לאוסרם.","\u0003מי שהיה ביתו סמוך לעבודה זרה\u0004 והיה קיר שלו משמש לעבודה זרה, \u0003ונפל\u0004 הקיר — \u0003אסור\u0004 לו \u0003לבנותו,\u0004 שהרי אם יבנה — הריהו בונה גם לעבודה זרה. אלא \u0003כיצד יעשה? כונס בתוך\u0004 השטח \u0003שלו ארבע אמות ובונה\u0004 את הקיר שלו, ועובדי עבודה זרה יצטרכו לבנות קיר לעצמם.","אם היה הקיר מתחילה \u0003שלו ושל עבודה זרה,\u0004 שהשטח והכותל היו שייכים לשניהם —"],["\u0003נידון מחצה על מחצה,\u0004 שמודד ממחצית עובי הכותל את ארבע אמות ההרחקה.","\u0003אבניו, עציו ועפרו\u0004 של הכותל שהיה עבודה זרה — \u0003מטמאין כ\u0004דין טומאת \u0003שרץ, שנאמר\u0004 בעבודה זרה: \u0003\"שקץ תשקצנו\"\u0004 (דברים ז, כו).","\u0003ר' עקיבא אומר:\u0004 הרי אלו מטמאים \u0003כנדה, שנאמר\u0004 בעבודה זרה: \u0003\"תזרם כמו דוה צא תאמר לו\"\u0004 (ישעיה ל, כב), \u0003מה נדה מטמאה במשא,\u0004 אף \u0003אף עבודה זרה מטמאה במשא.\u0004","על ההלכה ששנינו במשנה שצריך להרחיק מהקיר של בית עבודה זרה, שואלים: \u0003והא קא מרווח\u0004 \u0005[והרי\u0006 בכך \u0005הוא עושה רווח]\u0006 \u0003לעבודה זרה,\u0004 שנותן לה שטח גדול יותר מאשר היה לה קודם! \u0003אמר ר' חנינא מסורא: דעבד ליה\u0004 \u0005[שעושה\u0006 את המקום המתפנה \u0005הזה]\u0006 ל\u0003בית הכסא.\u0004","ומקשים: \u0003והא בעי צניעותא\u0004 \u0005[והרי צריך צניעות]\u0006 לבית הכסא, וכאן אינו יכול להצניע את עצמו! ומשיבים: \u0003דעבד ליה\u0004 \u0005[שעושה אותו]\u0006 \u0003בית הכסא\u0004 של \u0003לילה\u0004 שנפנה לצרכיו שם רק בלילה, בזמן שאין אנשים מצויים שם.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003איזהו צנוע? הנפנה בלילה במקום שנפנה ביום; ואף על גב דאוקימנא\u0004 \u0005[ואף על פי שהעמדנו]\u0006 את ההלכה הזו לא לענין המקום עצמו, אלא \u0003בכדרך\u0004 לומר שכדרך שנפנה ביום שאינו מגלה עצמו, כך נפנה בלילה שאינו מגלה עצמו, \u0003מיהו צניעותא בעי למעבד\u0004 \u0005[מכל מקום צניעות צריך לעשות],\u0006 וכאן אין לו מקום צנוע!","ומשיבים: \u0003דעבד ליה\u0004 \u0005[שעושה אותו]\u0006 בית הכסא \u0003לתינוקות,\u0004 שאינם נזהרים בכך.","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003דגדיר ליה\u0004 \u0005[שגודר אותו\u0006 את המקום הזה\u0005]\u0006 \u0003בהיזמי והינגי\u0004 (במיני קוצים) כך שלא יוכלו להשתמש במקום.","\u0003שלשה\u0004 סוגי \u0003בתים הן\u0004 לענין איסור עבודה זרה: \u0003בית שבנאו מתחלה לעבודה זרה\u0004 — \u0003הרי זה אסור\u0004 כולו. בית סתם, שלא נבנה לעבודה זרה, ש\u0003סיידו וכיידו לעבודה זרה ו\u0004בכך \u0003חידש\u0004 בו דברים — \u0003נוטל מה שחידש\u0004 וזורק, והבית עצמו מותר. בית סתם ש\u0003הכניס לתוכה עבודה זרה\u0004 \u0003ו\u0004אחר כך \u0003הוציאה\u0004 — \u0003הרי זה מותר,\u0004 שלא נאסר הבית מחמת עבודה זרה שהיתה בו לשעתה.","\u0003אמר רב: המשתחוה לבית\u0004 — \u0003אסרו.\u0004 ושואלים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 נאמר ש\u0005הוא סבור]\u0006 שדבר \u0003תלוש ולבסוף חברו\u0004 לקרקע \u0003כתלוש דמי\u0004 \u0005[נחשב],\u0006 שהרי הבית העשוי מאבנים שהיו תלושות, אף שכעת הוא מחובר — נדון כתלוש ונאסר? \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"בנאו\" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 משמע שדווקא אם בנאו מתחילה לשם עבודה זרה הריהו נאסר!","ומשיבים: אם \u0003בנאו\u0004 לשם כך, \u0003אף על פי שלא השתחוה לו\u0004 — נאסר, וכן אם \u0003השתחוה אף על פי שלא בנאו.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שלשה\u0004 המנויים במשנתנו, אינם כל מיני הבתים לענין עבודה זרה, אלא \u0003ארבעה הוו\u0004 \u0005[הם],\u0006 שהרי יש גם בית זה שהשתחווה לו!","ומשיבים: אין הוא מונה אותם לארבעה, \u0003כיון\u0004 ש\u0003לענין ביטול\u0004 \u0003בנה והשתחוה חד קא חשיב ליה\u0004 \u0005[אחד הוא מחשיב אותו],\u0006 שהרי אין הבדל בין זה לזה בהלכה זו.","\u0003שלש אבנים הן\u0004 של עבודה זרה: \u0003אבן שחצבה מתחלה לבימוס\u0004 (לבמה של עבודה זרה) — \u0003הרי זו אסורה.\u0004 אבן סתם ש\u0003סיידה וכיידה לשם עבודה זרה\u0004 — \u0003נוטל מה שסייד וכייד, ומותרת.\u0004 אבן ש\u0003העמיד עליה עבודה זרה ו\u0004אחר כך \u0003סילקה\u0004 — \u0003הרי זו מותרת.\u0004","על מה ששנינו במשנתנו שאבן שסיידה וכיידה לשם עבודה זרה — נאסרה בעצמה עד שיטול מה שהוסיף, \u0003אמר ר' אמי: והוא שסייד וכייד בגופה של אבן\u0004 עצמה, שחרץ וחקק באבן וסייד אותן צורות בתוך האבן.","ומקשים: \u0003והא דומיא דבית תנן\u0004 \u0005[והרי בדומה לבית\u0006 שסיידו וכיידו \u0005שנינו],\u0006 \u0003ובית לאו בגופיה\u0004 \u0005[לא בגופו]\u0006 \u0003הוא\u0004 שעושה שינויים, \u0003ומיתסר\u0004 \u0005[ו\u0006בכל זאת \u0005נאסר]!\u0006 ומשיבים: \u0003בית נמי איכא ביני אורבי\u0004 \u0005[גם כן יש בין הלבינים],\u0006 שנותן שם סיד, ונמצא עושה שינוי בגופו של הבית.","ומקשים: \u0003מי לא עסקינן דשייע והדר שייעיה\u0004 \u0005[האם איננו עוסקים\u0006 גם במקרה \u0005ש\u0006הבית \u0005חלק, שחזר והחליקו]\u0006 בטיט וכייד בו, ובכל זאת נאסר!","\u0003אלא כי אתמר\u0004 \u0005[כאשר נאמר]\u0006 מה שאמר \u0003ר' אמי\u0004 — \u0003לענין ביטול אתמר\u0004 \u0005[נאמר],\u0006 וכך כוונתו: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003סייד וכייד בגופה של אבן, כי\u0004 \u0005[כאשר]\u0006 \u0003נטל מה שחידש\u0004 — \u0003שפיר דמי\u0004 \u0005[טוב הוא],\u0006","ש\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון שסייד וכייד בגופה של אבן, כאבן שחצבה מתחלה לעבודה זרה דמיא\u0004 \u0005[נחשבת]\u0006 \u0003ותיתסר\u0004 \u0005[ותיאסר]\u0006 \u0003כולה,\u0004 ואינה מותרת גם אם נטל מה שחידש, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר כן."],["\u0003שלש אשרות הן\u0004 לענין איסור עבודה זרה וביטולה: \u0003אילן שנטעו מתחלה לשם עבודה זרה\u0004 — \u0003הרי זו\u0004 אשרה שכולה \u0003אסורה.\u0004 אילן ש\u0003גידעו\u0004 (חתך חלק מהגזע) או \u0003פיסלו.\u0004 (חתך חלק מענפיו) \u0003לשם עבודה זרה, והחליף\u0004 (הוציא ענפים חדשים) — \u0003נוטל מה שהחליף\u0004 ושורפו, שמה שצמח בה גדל לשם עבודה זרה, ומה שהיה באילן מקודם — מותר. אשרה שלישית היא ש\u0003העמיד תחתיה עבודה זרה, ו\u0004אחר כך \u0003נטלה\u0004 משם — \u0003הרי זו\u0004 האשרה \u0003מותרת.\u0004","על מה ששנינו שאילן שלא נטעו מתחילה לשם עבודה זרה נאסר כשגידעו ופסלו לשם עבודה זרה, \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: והוא שהבריך והרכיב בגופו של אילן.\u0004","ומקשים: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"גידעו ופיסלו\" תנן\u0004 \u0005[שנינו],\u0006 משמע שדי אם חתך מענפיו, ואפילו לא עשה פעולה של גידול ונטיעה באילן!","\u0003אלא כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 הדברים של \u0003ר' ינאי\u0004 — לא כדי לאסור את מה שגדל נאמר, אלא \u0003לענין ביטול איתמר\u0004 \u0005[נאמר],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003הבריך והרכיב בגופו של אילן, כי\u0004 \u0005[כאשר]\u0006 \u0003נטל מה שהחליף\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 כשר \u0005הדבר],\u0006 ומסבירים: ש\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 ש\u0003הבריך והרכיב בגופו של אילן, כאילן שנטעו מתחלה דמי\u0004 \u0005[ייחשב],\u0006 \u0003וליתסר כולה\u0004 \u0005[ושיאסר כולו]\u0006 ולא רק מה שהוסיף, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר כן.","\u0003אמר שמואל: המשתחוה לאילן\u0004 — \u0003תוספתיה\u0004 \u0005[הנוסף לו]\u0006 לאילן מאותה שעה, \u0003אסורה. מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003ר' אלעזר\u0004 מן המשנה: \u0003גידעו ופיסלו לעבודה זרה והחליף\u0004 — \u0003נוטל מה שהחליף.\u0004 ונדייק מכאן: דווקא \u0003גידעו ופיסלו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שעשה מעשה בגופו של האילן, \u0003לא גידעו ופיסלו\u0004 — \u0003לא,\u0004 משמע שבהשתחוואה בלבד אינו נאסר!","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003שמואל: הא מני\u0004 \u0005[זו,\u0006 המשנה, כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שאינם אוסרים אילן שהשתחווה לו לאחר שניטע בהיתר, \u0003ושמואל\u0004 ש\u0003אמר\u0004 את דבריו הרי זה \u0003כ\u0004דעת \u0003ר' יוסי בר יהודה,\u0004 ש\u0003אמר: אילן שנטעו ולבסוף עבדו\u0004 — \u0003אסור.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה ש\u0003ר' יוסי בר יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003בתוספת\u0004 שצמחה מכאן ולהבא \u0003פליגי\u0004 \u0005[\u0006הם \u0005חלוקים]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003תוספת\u0004 שצמחה בו מזמן שעבד אותו — \u0003לדברי הכל אסור, ובעיקרו\u0004 (גזעו) של עץ שגדל בהיתר \u0003פליגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 ש","\u0003ר' יוסי בר יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003עיקרו נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואשריהם תשרפון באש\"\u0004 (דברים יב, ג), ושריפה מכלה הכל, ומכאן שכל האילן הנעבד אסור, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003עיקר אילן שרי\u0004 \u0005[מותר],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואשירהם תגדעון\"\u0004 (דברים ז, ה), וגידוע מותיר באילן חלק שלא נכרת, \u0003איזהו אילן שגידועו אסור ועיקרו שרי\u0004 \u0005[מותר]?\u0006 \u0003הוי אומר: אילן שנטעו ולבסוף עבדו!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הא דלא מתרצינן הכי\u0004 \u0005[הרי אין אנו מתרצים כך]\u0006 את המקראות, כאשר נתפרשו שיטות אלה בגמרא לעיל (עבודה זרה מה,ב) \u0005—\u0006 \u0003איפוך\u0004 \u0005[הפוך]\u0006 ואמור את ההסבר שנתנו לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ל\u0004שיטתו של \u0003ר' יוסי בר יהודה,\u0004 \u0003ו\u0004את ההסבר לשיטת \u0003ר' יוסי בר יהודה\u0004 אמור \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]!\u0006","את ההצעה הזו דוחים: לפי פירוש זה, שהתוספת אסורה לדברי הכל, \u0003אם כן\u0004 משנתנו ששנינו בה שאם \u0003גידעו ופיסלו\u0004 נאסרה התוספת, \u0003מאן קתני לה\u0004 \u0005[מי שונה אותה]?\u0006 \u0003לא רבנן\u0004 \u0005[חכמים]\u0006 \u0003ולא ר' יוסי בר יהודה,\u0004 ומפרטים: \u0003אי\u0004 \u0005[אם]\u0006 תאמר כ\u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003בלא גידעו ופיסלו נמי\u0004 \u0005[גם כן]\u0006 \u0003תוספת אסורה, אי\u0004 \u0005[אם]\u0006 תאמר כ\u0003ר' יוסי בר יהודה, עיקר אילן נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור!\u0004","ומתרצים: \u0003אי בעית אימא רבנן\u0004 \u0005[אם תרצה אמור\u0006 שהוא שיטת \u0005חכמים]\u0006 \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהוא שיטת \u0003ר' יוסי בר יהודה.\u0004 ומסבירים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהוא כשיטת \u0003ר' יוסי בר יהודה,\u0004 כך נפרש: \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' יוסי בר יהודה\u0004 ש\u0003בלא גידעו ופיסלו\u0004 אלא בעבודה בלבד גם כן \u0003עיקר אילן אסור\u0004 — הרי זה כשעושה זאת \u0003בסתמא\u0004 \u0005[בסתם]\u0006 בלי לעשות דבר בגוף האילן, \u0003אבל גידעו ופיסלו\u0004 — בגידוע \u0003גלי אדעתיה\u0004 \u0005[גילה דעתו]\u0006 ש\u0003בתוספת ניחא ליה\u0004 \u0005[נוח לו]\u0006 שתהיה עבודה זרה, \u0003בעיקר אילן לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 ואינו עושה אותו לעבודה זרה.","ולהיפך, \u0003איבעית אימא רבנן\u0004 \u0005[אם תרצה אמור\u0006 שהוא שיטת \u0005חכמים],\u0006 \u0003\"גידעו ופיסלו\" איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005]\u0006 שרק התוספת אסורה, ומדוע? \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דעבד ליה\u0004 \u0005[שעושה לו]\u0006 לאילן \u0003מעשה בגופיה\u0004 \u0005[בגופו],\u0006 \u0003עיקר אילן נמי ליתסר\u0004 \u0005[גם כן שייאסר],\u0006 \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שלדעתם אין נאסר בכך אלא התוספת, ולא האילן עצמו.","\u0003איזו אשרה? כל שיש תחתיה עבודה זרה. ר' שמעון אומר: כל שעובדין אותה\u0004 עצמה. \u0003ומעשה ב\u0004יישוב \u0003צידן באילן שהיו עובדין אותו\u0004 לעבודה זרה, \u0003ומצאו תחתיו גל\u0004 אבנים, \u0003אמר להן ר' שמעון: בדקו את הגל הזה, ובדקוהו ומצאו בו צורה\u0004 (של אליל), \u0003אמר להן: הואיל ולצורה הן עובדין, נתיר להן את האילן,\u0004 שהאילן עצמו אינו אסור.","שנינו במשנה: \u0003איזהו אשרה.\u0004 ויש לשאול: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"שלש אשרות\" תנן\u0004 \u0005[שנינו]\u0006 במשנה הקודמת, ובכללן אשרה זו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 במשנה הקודמת: שלש אשרות הן, \u0003שתים\u0004 נחשבות אשרה \u0003לדברי הכל, ואחת\u0004 היא \u0003מחלוקת\u0004 של \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 וכך צריך להבין את משנתנו: \u0003איזו היא אשרה שנחלקו בה ר' שמעון וחכמים? כל שיש תחתיה עבודה זרה,\u0004 ואילו \u0003ר' שמעון אומר: כל שעובדים אותה\u0004 היא אשרה.","ושואלים לענין הלכה: \u0003איזו היא אשרה סתם?\u0004 כיצד יודעים אם אילן מסויים הוא עדיין עבודה זרה? \u0003אמר רב: כל שכומרים\u0004 של עבודה זרה \u0003יושבין תחתיה ואין טועמין מפירותיה,\u0004 משמע שהם סבורים שהיא מוקדשת לעבודה זרה. \u0003ושמואל אמר: אפילו אמרי\u0004 \u0005[אומרים]\u0006 אנשים: \u0003הני תמרי\u0004 \u0005[התמרים האלה]\u0006 של אילן זה הולכים \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003נצרפי\u0004 (מין עבודה זרה) — הרי האילן \u0003אסור, דרמי בי שיכרא ושתי ליה\u0004 \u0005[שמטילים\u0006 אותם \u0005למקום שעושים שיכר ושותים אותו]\u0006 את השיכר \u0003ביום\u0004 \u0003אידם. אמר אמימר, אמרו לי סבי\u0004 \u0005[זקני]\u0006 \u0003דפומבדיתא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כשמואל.\u0004"],["\u0003לא ישב בצילה\u0004 של אשירה, גם אם אינו יושב תחתיה ממש, כלומר תחת ענפיה, שהרי הוא נהנה כך מעבודה זרה, \u0003ואם ישב\u0004 — \u0003טהור. ולא יעבור תחתיה\u0004 ממש, \u0003ואם עבר\u0004 — \u0003טמא.\u0004 אבל אם \u0003היתה גוזלת את הרבים\u0004 שענפיה יוצאים לרשות הרבים, \u0003ועבר תחתיה\u0004 — \u0003טהור.\u0004","שנינו במשנה: \u0003לא ישב בצילה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי נמצא נהנה מעבודה זרה! \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא לצל צילה,\u0004 כלומר, לצל המתארך שלה, שהוא ארוך מקומתה של האשירה עצמה.","ושואלים: האם \u0003מכלל\u0004 דברים אלה נלמד ש\u0003בצל\u0004 שהוא באורך \u0003קומתה, אם ישב\u0004 — \u0003טמא?\u0004 ודוחים: \u0003לא,\u0004 יש לפרש ש\u0003אפילו לצל קומתה נמי\u0004 \u0005[גם כן],\u0006 \u0003אם ישב\u0004 — \u0003טהור, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003אפילו לצל צילה לא ישב\u0004 לכתחילה.","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש שהיו שונים\u0006 דבר זה \u0005על הסוף,\u0006 הקטע הבא של המשנה\u0005]\u0006 ששנינו בו: \u0003ואם ישב\u0004 — \u0003טהור.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא לצל קומתה.\u0004 ותוהים: \u0003מכלל\u0004 הדברים תלמד ש\u0003לצל צילה אפילו לכתחלה ישב?\u0004 ודוחים: \u0003לא, הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003אפילו לצל קומתה, אם ישב\u0004 — \u0003טהור.\u0004","ועוד שנינו במשנה: \u0003ולא יעבור תחתיה, ואם עבר\u0004 — \u0003טמא.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהוא טמא? \u0003אי אפשר דליכא\u0004 \u0005[שאין]\u0006 \u0003תקרובת עבודה זרה\u0004 מתחת לעץ, והיא מטמאת. וכיון שהעץ מאהיל על הטומאה ועליו — הריהו נטמא מחמת אוהל הטומאה.","ומעירים: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה בן בתירא היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירא אומר: מנין לתקרובת עבודה זרה שמטמאה באהל\u0004 כמת? \u0003שנאמר: \"ויצמדו לבעל פעור ויאכלו זבחי מתים\"\u0004 (תהלים קו, כח) כלומר, זבחים שזבחו לעבודה זרה, ומן ההשוואה בכתוב נלמד: \u0003מה מת מטמא באהל\u0004 — \u0003אף תקרובת עבודה זרה מטמא באהל.\u0004","שנינו במשנה: \u0003היתה גוזלת את הרבים, ועבר תחתיה\u0004 — \u0003טהור. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 השאלה: האם הלשון היא לשון דיעבד, שאם \u0003עבר\u0004 תחתיה טהור, ואולם לכתחילה אין לעשות כן, \u0003או\u0004 הכוונה שלכתחילה \u0003עובר\u0004 תחתיה וטהור? \u0003ר' יצחק בן אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה אמר: עובר\u0004 תחתיה לכתחילה, \u0003ור' יוחנן אמר: אם עבר.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים\u0006 בהלכה\u0005]:\u0006 \u0003הא דאיכא דירכא אחרינא\u0004 \u0005[זה שיש דרך אחרת]\u0006 לעבור בה, ואז לא יעבור לכתחילה, \u0003הא דליכא דירכא אחרינא\u0004 \u0005[זה שאין דרך אחרת],\u0006 ואז עובר תחתיה אפילו לכתחילה.","מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת,\u0004 שהיה עיוור, \u0003לשמעיה\u0004 \u0005[לשמשו]\u0006 שהיה מוליך אותו: \u0003כי מטית להתם ארהיטני\u0004 \u0005[כאשר אתה מגיע לשם,\u0006 מתחת לצל האשירה שברחוב, \u0005הריצני].\u0006 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דליכא דירכא אחרינא\u0004 \u0005[אם שאין דרך אחרת],\u0006 \u0003למה לי \"ארהיטני\"\u0004 \u0005[הריצני]?\u0006 \u0003מישרא שרי\u0004 \u0005[\u0006הרי \u0005מותר\u0006 הדבר\u0005]!\u0006 \u0003ואי דאיכא דירכא אחרינא, כי אמר \"ארהיטני\" מי שרי\u0004 \u0005[ואם שיש דרך אחרת, כאשר אומר לו \"הריצני\" האם מותר]?\u0006","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דליכא דירכא אחרינא\u0004 \u0005[שאין דרך אחרת],\u0006 וכפי שנאמר לעיל מותר הדבר, \u0003ו\u0004בכל זאת \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שצריך להיזהר במעשיו יותר, שלא ילמדו ממנו לעשות כן לכתחילה.","\u0003זורעין תחתיה\u0004 תחת האשירה \u0003ירקות בימות הגשמים,\u0004 שצל האילן אינו מביא כל תועלת לירקות שתחתיו, ואף מונע מהם את השמש. \u0003אבל לא בימות החמה,\u0004 לפי שאין הצל מזיק להם, והוא אף מגן על הירקות מן השמש. \u0003והחזירין\u0004 (חזרת, חסה) אין זורעים תחתיה \u0003לא בימות החמה ולא בימות הגשמים,\u0004 שגם בימות הגשמים הצל טוב להם. \u0003ר' יוסי אומר: אף לא\u0004 יזרע תחת האשירה \u0003ירקות בימות הגשמים, מפני שהנביה\u0004 (השלכת) \u0003נושרת עליהן והוה\u0004 (ומשמשת) \u0003להן לזבל,\u0004 ואם כן הריהו נהנה מעץ האשירה.","על המחלוקת במשנתנו, שואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003זה וזה גורם\u0004 — \u0003אסור\u0004 כלומר, אם יש שני גורמים לדבר, שאחד מהם מותר ואחד אסור, אסורה התוצאה. ולכן אף שהירקות ניזונים מן הקרקע שהיא מותרת — אסור הדבר, משום הנביה של עצי האשירה, \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 \u0003זה וזה גורם\u0004 — \u0003מותר,\u0004 ולכן הם מתירים?","\u0003הא איפכא שמעינן להו\u0004 \u0005[הרי ההיפך אנו שומעים אותם],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 עבודה זרה \u0003שוחק וזורה לרוח או מטיל לים. אמרו לו:\u0004 אם זורה אותה לרוח \u0003אף היא נעשה זבל, ו\u0004הרי \u0003נאמר: \"לא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח), ומשמע שחכמים הם החוששים להנאה מזבל של עבודה זרה, ור' יוסי אינו חושש לכך, ואם כן,","\u0003קשיא דרבנן אדרבנן\u0004 \u0005[קשה\u0006 מדברי \u0005חכמים על\u0006 דברי \u0005חכמים],\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי!\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי ר' \u0003יוסי לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003התם\u0004 \u0005[שם,\u0006 שהוא מפזר וזורה לרוח\u0005]\u0006 \u0003דקאזיל\u0004 \u0005[שהולך הכל]\u0006 \u0003לאיבוד\u0004 ואינו נעשה זבל במקום אחר — \u0003מתיר, הכא דלא קאזיל\u0004 \u0005[כאן שאינו הולך]\u0006 \u0003לאיבוד,\u0004 אלא נצבר על גבי הירקות — \u0003אסור.\u0004","\u0003אלא דרבנן אדרבנן קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים קשה]!\u0006 ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לא תיפוך\u0004 \u0005[אל תהפוך],\u0006 אלא הסבר את דברי \u0003ר' יוסי\u0004 \u0003כדשנין\u0004 \u0005[כמו שתירצנו],\u0006 \u0003דרבנן\u0004 \u0005[\u0006ואת דברי \u0005חכמים]\u0006 \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא\u0004 בענין אחר, בדרך הפשטת העור בבכור בהמה: \u0003מה שמשביח בעור\u0004 כשמפשיט אותו בדרך מסויימת \u0003פוגם בבשר,\u0004","\u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003מה שמשביח\u0004 האילן \u0003בנביה\u0004 (בשלכת) הנושרת ממנו \u0003פוגם בצל\u0004 שהוא מאפיל על הירקות, ואם כן בסך הכל אינו נהנה מן העבודה הזרה.","ולעצם הענין שואלים: \u0003ו\u0004האם \u0003סבר ר' יוסי\u0004 ש\u0003זה וזה גורם אסור? והתניא\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר: נוטעין יחור\u0004 מענף \u0003של\u0004 עץ שהוא \u0003ערלה,\u0004 שאף שערלה אסורה בהנאה — אין איסור ערלה בענפים, \u0003ואין נוטעין אגוז של ערלה, מפני שהוא פרי\u0004 ואסור בהנאה. \u0003ואמר רב יהודה אמר רב: מודה ר' יוסי, שאם נטע\u0004 אגוז של ערלה, ואת מה שצמח או \u0003הבריך\u0004 או \u0003הרכיב\u0004 בעץ רגיל — \u0003מותר\u0004 מה שגדל בו.","\u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מודה ר' יוסי\u0004"],["\u0003שאם נטע והבריך והרכיב\u0004 — \u0003מותר,\u0004 משמע שהוא סבור שכיון שיש שני גורמים בדבר ורק אחד מהם אסור, התוצאה אינה אסורה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003שני ליה\u0004 \u0005[שונה לו]\u0006 \u0003לר' יוסי בין שאר איסורין לעבודה זרה,\u0004 שבעבודה זרה דווקא הוא סבור שזה וזה גורם אסור, על כך יש לשאול: \u0003ומי שני ליה\u0004 \u0005[והאם\u0006 אכן \u0005שונה לו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שדה שנזדבלה בזבל עבודה זרה, וכן פרה שנתפטמה בכרשיני עבודה זרה, תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003שדה\u0004 שנזדבלה — \u0003תזרע\u0004 כדרכה, \u0003פרה\u0004 — \u0003תשחט\u0004 ותיאכל. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003שדה\u0004 — \u0003תבור\u0004 (שישאירנה בורה, בלי לזורעה), \u0003ופרה\u0004 — \u0003תרזה,\u0004 עד שיכלה מהם מה שהשביחו מעבודה עבודה זרה.","\u0003מאי לאו הא\u0004 \u0005[האם לא זו]\u0006 הברייתא שמתירה — כשיטת \u0003ר' יוסי\u0004 האומר שזה וזה גורם מותר, \u0003והא רבנן\u0004 \u0005[וזו\u0006 כדעת \u0005חכמים]\u0006 שאוסרים? ודוחים: \u0003לא, הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' אליעזר, והא רבנן\u0004 \u0005[וזו\u0006 שיטת \u0005חכמים]\u0006 החולקים בענין זה וזה גורם, ודעת המתיר בעבודה זרה לא שיטת ר' יוסי היא.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]?\u0006 היכן נתפרש שהם חולקים בכך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר במחלוקת \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 בענין של","\u0003שאור, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שאור של חולין ו\u0004שאור \u0003של תרומה\u0004 (שאסורה לזר, שאינו כהן) \u0003שנפלו לתוך העיסה\u0004 של חולין, ואין \u0003לא בזה\u0004 בלבד \u0003כדי לחמץ\u0004 (לגרום לעיסה להחמיץ) \u0003ולא בזה כדי לחמץ, ונצטרפו\u0004 יחד \u0003וחימצו\u0004 —","\u0003ר' אליעזר אומר: אחר האחרון אני בא,\u0004 ואם האחרון היה תרומה — הכל אסור לזר, ואם האחרון שנפל היה חולין — מותר. \u0003וחכמים אומרים: בין שנפל איסור לכתחלה ובין שנפל איסור לבסוף, אינו אסור עד שיהא בו\u0004 עצמו \u0003כדי לחמץ\u0004 את העיסה;","\u0003ו\u0004על כך \u0003אמר אביי: לא שנו\u0004 לדעת ר' אליעזר שאם האחרון היה חולין מותרת העיסה, \u0003אלא\u0004 במקרה \u0003שקדם וסילק את האיסור,\u0004 שהאיסור גופו אינו נמצא עוד שם, \u0003אבל לא קדם וסילק את האיסור\u0004 — אסור, למרות שיש גם גורם היתר. ומשמע מכאן שר' אליעזר סבור שזה וזה גורם — אסור, וחכמים חולקים עליו.","ודוחים: \u0003וממאי דטעמא\u0004 \u0005[ומנין\u0006 אתה יודע \u0005שהטעם]\u0006 של \u0003ר' אליעזר\u0004 הוא \u0003כ\u0004דברי \u0003אביי?\u0004 \u0003דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003ר' אליעזר משום\u0004 ש\u0003אחר אחרון אני בא, אי גמיר באיסורא\u0004 \u0005[אם\u0006 הוא \u0005נגמר באיסור]\u0006 \u0003אסורה\u0004 העיסה, \u0003ואי גמיר בהיתירא\u0004 \u0005[ואם\u0006 הוא \u0005נגמר בהיתר]\u0006 \u0003מותרין\u0004 בה הכל, \u0003בין סלקיה\u0004 \u0005[\u0006ש\u0005סילק אותו]\u0006 את האיסור תחילה \u0003ובין לא סלקיה\u0004 \u0005[סילק אותו],\u0006 ואין זה איפוא קשור לענין זה וזה גורם!","\u0003אלא\u0004 יש לומר שמדובר במחלוקת \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 של \u0003עצים,\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003נטל הימנה\u0004 (מן האשירה) \u0003עצים\u0004 — \u0003אסורה\u0004 (אסורים) \u0003בהנאה. הסיק בה את התנור\u0004 בעצים אלה, אם היה זה תנור \u0003חדש\u0004 — \u0003יותץ\u0004 (יישבר), שנמצא שנגמרה מלאכתו על ידי עצי האשירה. אם היה זה תנור \u0003ישן\u0004 — \u0003יוצן\u0004 יצננו אותו, ולא ישתמש בחום הבא מעצים אלה. אם \u0003אפה בו את הפת\u0004 — הפת הזו \u0003אסורה בהנאה.\u0004","\u0003נתערבה\u0004 פת זו \u0003באחרים\u0004 — \u0003כולן אסורות בהנאה. ר' אליעזר אומר:\u0004 ישתמש בכל הככרות, אבל \u0003יוליך הנאה\u0004 כנגד מה שנהנה מן האיסור \u0003לים המלח. אמרו לו\u0004 חכמים: \u0003אין פדיון לעבודה זרה.\u0004 הרי שר' אליעזר סבור שזה וזה גורם אסור, שהרי הפת יש בה גורם אחד בלבד של איסור (עצי ההסקה) והשאר הם היתר, ובכל זאת היא אסורה בהנאה.","ודוחים: לשיטתך, \u0003רבנן דפליגי עליה\u0004 \u0005[חכמים שחולקים עליו]\u0006 על \u0003ר' אליעזר\u0004 בענין שדה שנזדבלה בזבל עבודה זרה, \u0003מאן נינהו\u0004 \u0005[מי הם]?\u0006","\u0003אילימא רבנן\u0004 \u0005[אם תאמר\u0006 שהם \u0005חכמים]\u0006 שחולקים עליו בענין \u0003עצים,\u0004 הלוא \u0003אחמורי מחמרי\u0004 \u0005[מחמירים\u0006 הם יותר ממנו\u0005],\u0006 ובודאי הם סבורים שזה וזה גורם אסור!","\u0003אלא\u0004 תאמר שהם \u0003רבנן\u0004 \u0005[חכמים]\u0006 שנחלקו עליו ב\u0003שאור, אימר דשמעת להו לרבנן דמקילי\u0004 \u0005[אמור ששמעת אותם את החכמים שמקילים]\u0006 \u0003בשאור, בעבודה זרה מי מקילי\u0004 \u0005[האם\u0006 הם \u0005מקילים]?\u0006","\u0003אלא לעולם\u0004 נחזור להסבר הראשון: \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המתירה לזרוע בשדה שנזדבלה בזבל עבודה זרה — שיטת \u0003ר' יוסי\u0004 היא, הסבור שזה וזה גורם — מותר, \u0003והא\u0004 \u0005[וזו]\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 האוסרים.","ומה שהיה קשה לנו במשנתנו, מדוע אסר ר' יוסי לזרוע ירקות תחת אשירה, יש לומר כי \u0003ר' יוסי לדבריהם דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לדידי\u0004 \u0005[לי\u0006 עצמי, לשיטתי\u0005]\u0006 \u0003זה וזה גורם\u0004 — \u0003מותר,\u0004 ובכל מקרה מותר לזרוע תחת אשירה, אבל גם","\u0003לדידכו דאמריתו\u0004 \u0005[לשיטתכם, שאתם אומרים]\u0006 \u0003זה וזה גורם אסור, אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[על כל פנים]\u0006 ש\u0003אף ירקות\u0004 יהיו אסורים \u0003בימות הגשמים\u0004 בגלל הנביה!","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה טעמם שמתירים? ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא\u0004 לענין דרך הפשטת עור הבכור, שיש לקזז את הרווח וההפסד שבדבר. כך לענייננו, מה שהירקות נהנים מן הזבל מפסידים הם בגלל הצל, ונמצא שבסך הכל אין לו הנאה מעץ האשירה.","ומסכמים: \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי\u0004 בענין זה. מסופר, \u0003ההוא גינתא דאיזדבל בזבלא\u0004 \u0005[גינה אחת שהזדבלה בזבל]\u0006 של \u0003עבודה זרה, שלח רב עמרם קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף\u0004 לשאול מה לעשות. \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי.\u0004"],["\u0003נטל ממנה\u0004 מן האשירה \u0003עצים\u0004 — \u0003אסורין\u0004 העצים \u0003בהנאה. הסיק בהן\u0004 בעצים אלה \u0003את התנור, אם\u0004 היה זה תנור \u0003חדש\u0004 שמתחזק ומתחסם מחמת ההסקה הראשונה — \u0003יותץ\u0004 (יישבר) התנור, שהרי נוצר על ידי איסור עבודה זרה, \u0003ואם\u0004 היה זה תנור \u0003ישן\u0004 שהוסק קודם לכן — \u0003יוצן\u0004 (יצונן), ולא ישתמש בחום שגרמו עצים אלה. \u0003אפה בו את הפת\u0004 — פת זו \u0003אסורה בהנאה.\u0004","\u0003נתערבה\u0004 הפת \u0003באחרות\u0004 — \u0003כולן אסורות בהנאה, ר' אליעזר אומר: יוליך\u0004 דמי \u0003הנאה\u0004 שקיבל מהאיסור \u0003לים המלח,\u0004 כלומר יאבדם, וכך יוכל להנות מן הפת \u0003אמרו לו: אין פדיון לעבודה זרה,\u0004 אלא צריך לבער הכל.","\u0003נטל הימנה\u0004 מן האשירה \u0003כרכור\u0004 מכשיר לאריגה — הרי הכרכור הזה \u0003אסור בהנאה.\u0004 אם \u0003ארג בו\u0004 בכרכור זה \u0003את הבגד\u0004 — \u0003אסור\u0004 הבגד \u0003בהנאה. נתערב\u0004 בגד זה של איסור \u0003באחרים ואחרים באחרים\u0004 — \u0003כולן אסורין בהנאה, ר' אליעזר אומר: יוליך הנאה לים המלח, אמרו לו: אין פדיון לעבודה זרה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיע לנו במשנה את המחלוקת הן במקרה של הפת והן במקרה של הבגד, \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק את ההלכה \u0005הראשונה]\u0006 היינו אומרים: דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' אליעזר\u0004 שיכול להוליך דמי הנאה וליהנות, \u0003משום דבעידנא דקא גמרה\u0004 \u0005[שבזמן שנגמרה]\u0006 \u0003פת, קלי לה איסורא\u0004 \u0005[נשרף\u0006 כבר \u0005האיסור\u0006 גופו\u0005],\u0006 \u0003אבל כרכור דאיתיה לאיסורא בעיניה\u0004 \u0005[שהאיסור נמצא\u0006 עדיין \u0005בעינו]\u0006 \u0003אימא מודי לרבנן\u0004 \u0005[אמור\u0006 ש\u0005מודה\u0006 בכך \u0005לחכמים]\u0006 שהדבר אסור.","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 את המחלוקת רק ב\u0003כרכור,\u0004 היינו אומרים: דווקא \u0003בהא קאמרי רבנן\u0004 \u0005[בזה אמרו חכמים]\u0006 שאין פתרון לדבר, \u0003אבל פת\u0004 שנשרף האיסור \u0003אימא מודו ליה\u0004 \u0005[אמור\u0006 ש\u0005מודים לו]\u0006 \u0003לר' אליעזר\u0004 שיוליך דמי הנאה לים המלח, ולכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים. \u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר נחמני אמר רב חסדא אמר זעירי: הלכה כר' אליעזר. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב חסדא: אמר לי אבא בר רב חסדא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר זעירי: הלכה כר' אליעזר.\u0004","","\u0003אמר רב אדא בר אהבה: לא שנו\u0004 פתרון זה \u0003אלא\u0004 ב\u0003פת\u0004 שנאפתה באיסור, \u0003אבל\u0004 \u0003חבית\u0004 של יין אסור — \u0003לא,\u0004 אין לה היתר בדרך זו. \u0003ורב חסדא אמר: אפילו חבית מותרת.\u0004","מסופר, \u0003ההוא גברא דאיתערב ליה חביתא דיין נסך בחמריה\u0004 \u0005[אדם אחד שהתערבה לו חבית\u0006 אחת \u0005של יין נסך בתוך\u0006 חביות של \u0005יינו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 לשאול מה לעשות, \u0003אמר\u0004 לו רב חסדא: \u0003שקול ארבע זוזי\u0004 \u0005[קח ארבעה זוזים],\u0006 שהם דמי חבית יין, \u0003ושדי בנהרא\u0004 \u0005[וזרוק\u0006 אותם \u0005בנהר],\u0006 כדי שלא יהנה מדמי היין האסור המעורב בחביות, \u0003ונשתרי לך\u0004 \u0005[ויהיה מותר לך]\u0006 הכל.","\u0003כיצד מבטלה\u0004 את האשירה? אם \u0003קירסם\u0004 כלומר, חתך ממנה קיסמים לצורכו, או \u0003זירד\u0004 לקח ממנה זרדים לחים, או \u0003נטל ממנה מקל או שרביט,\u0004 או \u0003אפילו עלה\u0004 — \u0003הרי זה בטלה\u0004 לפי שהוא מראה שאינו מתייחס אליה עוד כעבודה זרה. אם \u0003שיפה\u0004 (שייף אותה) \u0003לצרכה\u0004 כלומר, לצורך האילן לחזקו או ליפותו — \u0003אסורה,\u0004 אם עשה זאת \u0003שלא לצרכה\u0004 — \u0003מותרת.\u0004","ושואלים: \u0003אותן שפאין\u0004 ששיפה מן העץ של האשירה לצורכה, \u0003מה תהא עליהן?\u0004 מה דינם? \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב הונא ור' חייא בר\u0004 \u0005[בנו]\u0006 של \u0003רב, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אסורין,\u0004 לפי שהם חלק מן האשירה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מותרין,\u0004 שהרי חלקים אלה הוא משליך ומבטל. ומעירים: \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמי שאומר]\u0006 \u0003מותרין, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003גוי ששיפה עבודה זרה לצרכו\u0004 ועל ידי כך ביטלה — \u0003היא ושפאיה מותרין,\u0004 אם עשה זאת \u0003לצרכה\u0004 — \u0003היא\u0004 עצמה \u0003אסורה ושפאיה מותרין. וישראל ששיפה עבודה זרה, בין לצרכה בין לצרכו\u0004 — \u0003היא ושפאיה אסורין,\u0004 שאין ישראל יכול לבטל עבודה זרה. ומביאים מחלוקת אמוראים בענין משנתנו.","","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003עבודה זרה שנשתברה\u0004 מאליה, \u0003רב אמר: צריך לבטל כל קיסם וקיסם\u0004 שבה, \u0003ושמואל אמר: עבודה זרה אינה בטלה אלא\u0004 כשהיא נשברת \u0003דרך גדילתה.\u0004","ותוהים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003דרך גדילתה מי מבטלא\u0004 \u0005[האם\u0006 היא \u0005מתבטלת]?\u0006 \u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך צריך להבין את דבריו: \u0003אין עבודה זרה צריכה לבטל אלא\u0004 כשהיא נשברת \u0003דרך גדילתה,\u0004 כגון שנושרים ממנה עלים, אבל זו שנשברה — אינה צריכה ביטול עוד.","ושואלים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005ב\u0006נושא זה \u0005הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003עובדין\u0004 הגוים אפילו \u0003לשברין, ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003אין עובדין לשברין?\u0004 ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עובדין\u0004 הם \u0003לשברין, והכא\u0004 \u0005[וכאן]\u0006 \u0003בשברי שברים קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003שברי שברים\u0004 אף הם \u0003אסורין, ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל, \u0005סבור]:\u0006 \u0003שברי שברים מותרין.\u0004 \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שברי שברים מותרין, והכא\u0004 \u0005[וכאן]\u0006 \u0003בעבודה זרה של חליות\u0004 שעשוה חוליות המתחברות יחד \u0003וב\u0004אופן ש\u0003הדיוט\u0004 (אדם שאינו מומחה) \u0003שיכול להחזירה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ובכך נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003כיון\u0004 ש\u0003הדיוט יכול להחזירה,\u0004 גם אם התפרקה \u0003לא בטלה. ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003אין עבודה זרה בטלה אלא דרך גדילתה, דהיינו אורחיה\u0004 \u0005[שזו דרכו],\u0006 \u0003הא לאו\u0004 \u0005[זו לא]\u0006 \u0003גדילתה היא,\u0004 זו אין דרכה להיות מפורקת, \u0003ו\u0004כיון שנתפרקה \u0003אין צריכה לבטל.\u0004 \u0003ר' ישמעאל אומר: שלש אבנים\u0004 שהיו \u0003זו בצד זו בצד\u0004 עבודה זרה של \u0003מרקוליס,\u0004 שיש שם גל אבנים שזורקים לכבודו, חלק מן העבודה זרה עצמה — הרי הן \u0003אסורות,\u0004 אם היו \u0003שתים\u0004 בלבד — \u0003מותרות. וחכמים אומרים:\u0004 אותן \u0003שנראות עמו,\u0004 שנראה שנפלו ממנו — \u0003אסורות, ושאין נראות עמו\u0004 — \u0003מותרות.\u0004","","","","","ושואלים: \u0003בשלמא רבנן קסברי\u0004 \u0005[נניח חכמים\u0006 אפשר לומר ש\u0005סבורים הם]\u0006 ש\u0003עובדין לשברים\u0004 של עבודה זרה, ומשום כך, אם \u0003נראות עמו, דאיכא למימר מיניה נפל\u0004 \u0005[שיש\u0006 מקום \u0005לומר\u0006 ש\u0005ממנו נפלו]\u0006 האבנים — הרי הן נחשבות כשברים של גל של מרקוליס ו\u0003אסורות, שאין נראות עמו\u0004 — \u0003מותרות,\u0004 משום שנראה שלא ממנו נפלו.","\u0003אלא ר' ישמעאל מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 סבור הוא ש\u0003עובדין לשברין, אפילו תרתי נמי ליתסר\u0004 \u0005[שתים גם כן יהיה אסור],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אין עובדין לשברים, אפילו תלת נמי\u0004 \u0005[שלוש גם כן]\u0006 \u0003לא\u0004 ייאסרו!","\u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: בידוע שנשרו ממנו\u0004 אותן האבנים — \u0003דברי הכל אסורות\u0004 בכל מקרה. \u0003ואפילו למאן דאמר\u0004 \u0005[לדעת מי שאומר]:\u0006 \u0003אין עובדין לשברים\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003עבודה זרה דלאו היינו אורחיה\u0004 \u0005[שאין זו דרכה]\u0006 לעובדה בשברים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דמעיקרא תבורי מיתברי\u0004 \u0005[שמתחילה שבורים הם]\u0006 שזורקים לגל אבנים בודדות ולא מחוברות — \u0003היינו אורחיה\u0004 \u0005[זו דרכו],\u0006 ולכן אינם יוצאות מגדר עבודה זרה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בסתמא\u0004 \u0005[ב\u0006אבנים \u0005סתם],\u0006 שלא ברור מהיכן הגיעו."]]};
